// === Global keyboard shortcuts ===
// "/" focuses the rankings search; "?" opens help; "g <letter>" jumps to a tab.
// Only fires when no editable element is focused, so users can still type
// freely in inputs / textareas / contenteditable.
(function _initKeyboardShortcuts() {
  const NAV_KEYS = {
    r: 'rankings', c: 'compare', g: 'games', t: 'trade', m: 'mockdraft',
    p: 'prospect', y: 'myteams', a: 'account', v: 'trivia', b: 'backtest'
  };
  let pendingG = false;
  let gTimer = null;
  function _isEditableTarget(el) {
    if (!el) return false;
    const tag = el.tagName;
    if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return true;
    if (el.isContentEditable) return true;
    return false;
  }
  document.addEventListener('keydown', e => {
    if (_isEditableTarget(e.target)) return;
    if (e.altKey || e.ctrlKey || e.metaKey) return;
    // "/" → focus rankings search
    if (e.key === '/' && !e.shiftKey) {
      const search = document.getElementById('search');
      if (search) {
        e.preventDefault();
        // Switch to Rankings if needed, then focus the search
        if (typeof window.switchPage === 'function' && !document.getElementById('pageRankings').classList.contains('active')) {
          window.switchPage('rankings');
        }
        setTimeout(() => search.focus(), 0);
      }
      return;
    }
    // "?" → open help
    if (e.key === '?' || (e.key === '/' && e.shiftKey)) {
      e.preventDefault();
      const ov = document.getElementById('helpOverlay');
      if (ov) ov.classList.add('open');
      return;
    }
    // "Escape" → close help
    if (e.key === 'Escape') {
      const ov = document.getElementById('helpOverlay');
      if (ov && ov.classList.contains('open')) { ov.classList.remove('open'); return; }
    }
    // "g <letter>" → navigate
    if (pendingG) {
      pendingG = false;
      if (gTimer) { clearTimeout(gTimer); gTimer = null; }
      const target = NAV_KEYS[e.key.toLowerCase()];
      if (target && typeof window.switchPage === 'function') {
        e.preventDefault();
        window.switchPage(target);
      }
      return;
    }
    if (e.key === 'g') {
      pendingG = true;
      gTimer = setTimeout(() => { pendingG = false; gTimer = null; }, 1500);
      return;
    }
  });
})();

