// Search autocomplete — top-5 matches in a dropdown below the input.
// Click or Enter opens the player card; Arrow/Esc navigate/close.
(function _initSearchAutocomplete() {
  const input = document.getElementById('search');
  const suggest = document.getElementById('searchSuggest');
  if (!input || !suggest) return;
  let items = [];
  let activeIdx = -1;
  function buildItems(q) {
    if (!q || q.length < 2) return [];
    const lc = q.toLowerCase();
    const matches = [];
    for (const d of D) {
      if (!d || !d.n || d._isFuturePick) continue;
      const name = d.n.toLowerCase();
      const team = (d.t || '').toLowerCase();
      let score = 0;
      if (name.startsWith(lc)) score = 100;
      else if (name.includes(lc)) score = 60;
      else if (team === lc) score = 50;
      else if (team.startsWith(lc)) score = 30;
      if (score > 0) matches.push({ d, score });
    }
    matches.sort((a, b) => b.score - a.score || (a.d.myRank || 999) - (b.d.myRank || 999));
    return matches.slice(0, 5).map(m => m.d);
  }
  function esc(s) { return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c])); }
  function drawSuggest() {
    if (!items.length) { suggest.hidden = true; suggest.innerHTML = ''; input.setAttribute('aria-expanded', 'false'); return; }
    suggest.hidden = false;
    input.setAttribute('aria-expanded', 'true');
    suggest.innerHTML = items.map((d, i) => {
      const img = d._slImg ? '<img src="' + esc(window._fixHeadshotUrl(d._slImg)) + '" alt="" loading="lazy" onerror="this.style.display=\'none\'">' : '<div style="width:28px;height:28px;border-radius:50%;background:var(--surface);flex-shrink:0"></div>';
      const posRank = d.myPosRank ? ' · ' + esc(String(d.myPosRank)) : (d.r ? ' · ' + esc(d.r) : '');
      return '<div class="search-suggest-item' + (i === activeIdx ? ' active' : '') + '" role="option" data-idx="' + i + '" tabindex="-1">' + img +
        '<div class="ss-text"><div class="ss-name">' + esc(d.n) + '</div>' +
        '<div class="ss-meta">' + esc(d.s || '') + ' · ' + esc(d.t || 'FA') + posRank + '</div></div></div>';
    }).join('');
  }
  function pick(i) {
    const d = items[i];
    if (!d) return;
    suggest.hidden = true;
    items = []; activeIdx = -1;
    input.value = '';
    query = '';
    input.setAttribute('aria-expanded', 'false');
    if (_searchTimer) clearTimeout(_searchTimer);
    if (typeof render === 'function') render();
    if (typeof openPlayerCard === 'function') openPlayerCard(d);
  }
  input.addEventListener('input', () => {
    items = buildItems(input.value);
    activeIdx = items.length ? 0 : -1;
    drawSuggest();
  });
  input.addEventListener('keydown', e => {
    if (suggest.hidden || !items.length) {
      if (e.key === 'Escape') input.blur();
      return;
    }
    if (e.key === 'ArrowDown') { e.preventDefault(); activeIdx = Math.min(activeIdx + 1, items.length - 1); drawSuggest(); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); activeIdx = Math.max(activeIdx - 1, 0); drawSuggest(); }
    else if (e.key === 'Enter') { e.preventDefault(); if (activeIdx >= 0) pick(activeIdx); }
    else if (e.key === 'Escape') { suggest.hidden = true; input.setAttribute('aria-expanded', 'false'); }
  });
  suggest.addEventListener('mousedown', e => {
    // mousedown (not click) so we beat the input's blur from closing the dropdown
    const item = e.target.closest('.search-suggest-item');
    if (!item) return;
    e.preventDefault();
    pick(parseInt(item.dataset.idx, 10));
  });
  input.addEventListener('blur', () => {
    // Delay hide so click-on-item still registers
    setTimeout(() => { suggest.hidden = true; input.setAttribute('aria-expanded', 'false'); }, 150);
  });
  input.addEventListener('focus', () => {
    if (items.length) { suggest.hidden = false; input.setAttribute('aria-expanded', 'true'); }
  });
})();

