// Fullscreen toggle for the tier card view
(function _wireTcvFullscreen() {
  const fsBtn = document.getElementById('tcvFullscreenBtn');
  const wrap = document.getElementById('tierCardWrap');
  if (!fsBtn || !wrap) return;

  // Track where the player-card modal lives in the normal DOM so we can
  // move it into the fullscreen container (browser Fullscreen API only
  // renders descendants of the fullscreen element) and restore on exit.
  let _modalOriginalParent = null;
  let _modalOriginalNext = null;

  function _moveModalIntoFullscreen() {
    const modal = document.getElementById('modal');
    if (!modal) return;
    if (modal.parentNode === wrap) return; // already moved
    _modalOriginalParent = modal.parentNode;
    _modalOriginalNext = modal.nextSibling;
    wrap.appendChild(modal);
  }
  function _restoreModalToOriginalParent() {
    const modal = document.getElementById('modal');
    if (!modal || !_modalOriginalParent) return;
    if (_modalOriginalNext && _modalOriginalNext.parentNode === _modalOriginalParent) {
      _modalOriginalParent.insertBefore(modal, _modalOriginalNext);
    } else {
      _modalOriginalParent.appendChild(modal);
    }
    _modalOriginalParent = null;
    _modalOriginalNext = null;
  }

  function _exitTcvFullscreen() {
    wrap.classList.remove('tcv-fullscreen');
    const closeBtn = wrap.querySelector('.tcv-fs-close');
    if (closeBtn) closeBtn.remove();
    _restoreModalToOriginalParent();
    if (document.fullscreenElement) {
      try { document.exitFullscreen(); } catch(e) {}
    }
    fsBtn.textContent = '⛶ FULLSCREEN';
  }

  function _enterTcvFullscreen() {
    wrap.classList.add('tcv-fullscreen');
    // Inject a close (X) button inside the overlay
    if (!wrap.querySelector('.tcv-fs-close')) {
      const x = document.createElement('button');
      x.className = 'tcv-fs-close';
      x.textContent = '×';
      x.title = 'Exit fullscreen (Esc)';
      x.addEventListener('click', _exitTcvFullscreen);
      wrap.appendChild(x);
    }
    // Move the player-card modal in so it remains usable while fullscreen
    _moveModalIntoFullscreen();
    // Try the browser Fullscreen API too — gives true distraction-free mode
    if (wrap.requestFullscreen) {
      wrap.requestFullscreen().catch(() => { /* CSS overlay still works even if browser FS denied */ });
    }
    fsBtn.textContent = '⛶ EXIT FULLSCREEN';
  }

  fsBtn.addEventListener('click', () => {
    if (wrap.classList.contains('tcv-fullscreen')) _exitTcvFullscreen();
    else _enterTcvFullscreen();
  });

  // Sync state if the user exits via Esc / browser UI
  document.addEventListener('fullscreenchange', () => {
    if (!document.fullscreenElement && wrap.classList.contains('tcv-fullscreen')) {
      _exitTcvFullscreen();
    }
  });
  // Also handle Esc when the CSS overlay is on but no browser FS (some browsers / fallback)
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && wrap.classList.contains('tcv-fullscreen') && !document.fullscreenElement) {
      _exitTcvFullscreen();
    }
  });
})();

