// Hide non-applicable ADP tabs based on mode
// Best Ball: only Underdog + DK (the two best ball platforms)
// Dynasty: only Consensus + Sleeper + KTC
// Superflex: show all incl. DK (Underdog data-backed via d.sfa, DK Best Ball values shared)
// Redraft: show all incl. DK
// Per-mode default: dynasty/dynastysf default to Sleeper, bestball defaults to Underdog,
// redraft/superflex default to Consensus.
// Defaults reapplied when crossing group boundaries.
let _rnkLastGroup = null;
function updateRnkAdpForMode() {
  const isDynasty = currentMode === 'dynasty' || currentMode === 'dynastysf';
  const isBestBall = currentMode === 'bestball';
  const groupNow = isBestBall ? 'bestball' : isDynasty ? 'dynasty' : 'redraft';
  document.querySelectorAll('#rnkAdpSrcTabs .md-rank-src-tab').forEach(tab => {
    const src = tab.dataset.rnkadp;
    if (isBestBall) {
      // Only Underdog and DK make sense for Best Ball
      tab.style.display = (src === 'underdog' || src === 'dk') ? '' : 'none';
    } else if (isDynasty) {
      if (src === 'consensus') { tab.style.display = ''; return; }
      // Dynasty: only Consensus + Sleeper + KTC. DK is best-ball/redraft only.
      tab.style.display = (src === 'sleeper' || src === 'ktc') ? '' : 'none';
    } else {
      if (src === 'consensus') { tab.style.display = ''; return; }
      // ESPN & CBS publish 1QB redraft boards only — show in redraft, hide in superflex.
      if (src === 'espn' || src === 'cbs') { tab.style.display = currentMode === 'redraft' ? '' : 'none'; return; }
      // In non-dynasty/non-bestball modes: hide KTC (dynasty-only). DK is allowed.
      tab.style.display = src === 'ktc' ? 'none' : '';
    }
  });
  updateRnkAdpLocks();

  function _setRnkSrc(src) {
    rnkAdpSrc = src;
    document.querySelectorAll('#rnkAdpSrcTabs .md-rank-src-tab').forEach(b => b.classList.remove('active'));
    const t = document.querySelector('#rnkAdpSrcTabs .md-rank-src-tab[data-rnkadp="' + src + '"]');
    if (t) t.classList.add('active');
  }

  if (_rnkLastGroup !== groupNow) {
    // Crossed a group boundary — apply mode default.
    _setRnkSrc(isBestBall ? 'underdog' : isDynasty ? 'sleeper' : 'consensus');
    _rnkLastGroup = groupNow;
  } else {
    // Same group — only repair if current source isn't valid for this mode.
    if (isBestBall && rnkAdpSrc !== 'underdog' && rnkAdpSrc !== 'dk') {
      _setRnkSrc('underdog');
    } else if (isDynasty && rnkAdpSrc !== 'consensus' && rnkAdpSrc !== 'sleeper' && rnkAdpSrc !== 'ktc') {
      _setRnkSrc('sleeper');
    } else if (!isDynasty && !isBestBall && rnkAdpSrc === 'ktc') {
      _setRnkSrc('consensus');
    }
  }
}
updateRnkAdpForMode();

