// Export tier groupings (JSON) — players grouped under each tier label, no
// per-row stat noise, useful for quick sharing of tier philosophy.
document.getElementById('btnExportTiers').addEventListener('click', () => {
  const data = getFiltered();
  if (!data.length) { toast('Nothing to export'); return; }
  const useFilteredRank = (filter === 'QB' || filter === 'RB' || filter === 'WR' || filter === 'TE');
  // Sort tier boundaries ascending for grouping
  const sortedTiers = tiers.slice().sort((a, b) => a.afterRank - b.afterRank);
  const groups = [];
  let current = { tier: 'Untiered', label: '', afterRank: 0, players: [] };
  data.forEach((d, i) => {
    const displayRank = useFilteredRank ? (i + 1) : d.myRank;
    // Find the latest tier whose afterRank <= displayRank
    let owner = null;
    for (const t of sortedTiers) { if (t.afterRank <= displayRank) owner = t; else break; }
    const key = owner ? owner.label + '|' + owner.afterRank : '';
    if ((owner && current.label !== owner.label) || (!owner && current.tier !== 'Untiered')) {
      if (current.players.length) groups.push(current);
      current = owner
        ? { tier: 'Tier ' + owner.label, label: owner.label, name: owner.name, startRank: displayRank, players: [] }
        : { tier: 'Untiered', label: '', startRank: displayRank, players: [] };
    }
    current.players.push({ rank: displayRank, name: d.n, team: d.t, pos: d.s, posRank: d.myPosRank || d.r });
  });
  if (current.players.length) groups.push(current);

  const modeLabel = currentMode === 'dynastysf' ? 'DynastySF' : currentMode === 'dynasty' ? 'Dynasty' : currentMode === 'superflex' ? 'Superflex' : currentMode === 'bestball' ? 'BestBall' : 'Redraft';
  const verLabel = currentVersion === 'consensus' ? 'Consensus' : currentVersion === 'jacks' ? 'Jacks' : 'My';
  const posLabel = filter === 'ALL' ? 'All' : filter;
  const payload = {
    source: 'myfantasyfootball.co',
    version: currentVersion,
    mode: currentMode,
    position: filter,
    exportedAt: new Date().toISOString(),
    tierCount: groups.filter(g => g.tier !== 'Untiered').length,
    playerCount: data.length,
    tiers: groups
  };
  const blob = new Blob([JSON.stringify(payload, null, 2)], {type: 'application/json'});
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `${verLabel}-${modeLabel}-${posLabel}-Tiers.json`;
  a.click();
  toast(`Exported ${payload.tierCount} tier${payload.tierCount === 1 ? '' : 's'} to JSON`);
});

// Export to Underdog format CSV (id, firstName, lastName, rank)
document.getElementById('btnExportUnderdog').addEventListener('click', () => {
  let data = getFiltered();
  const _cut = _exportCutoff();
  const _truncated = data.length > _cut;
  if (_truncated) data = data.slice(0, _cut);
  if (_truncated) {
    if (!window._authCurrentUser && currentVersion === 'mine') {
      toast('Sign in to export your rankings');
      if (typeof window.openAuthModal === 'function') window.openAuthModal();
      return;
    }
    toast('Exporting top ' + _cut + ' — upgrade to PRO for the full list');
  }
  const modeLabel = currentMode === 'dynastysf' ? 'DynastySF' : currentMode === 'dynasty' ? 'Dynasty' : currentMode === 'superflex' ? 'Superflex' : currentMode === 'bestball' ? 'BestBall' : 'Redraft';
  const verLabel = currentVersion === 'consensus' ? 'Consensus' : currentVersion === 'jacks' ? 'Jacks' : 'My';
  const posLabel = filter === 'ALL' ? 'All' : filter;
  // Underdog's current export quotes every populated field; mirror that exactly.
  const esc = v => '"' + String(v ?? '').replace(/"/g, '""') + '"';
  const useFilteredRank = (filter === 'QB' || filter === 'RB' || filter === 'WR' || filter === 'TE');

  const headers = ['id','firstName','lastName','adp','projectedPoints','salary','positionRank','slotName','teamName','lineupStatus','byeWeek'];
  const rows = [headers.map(esc).join(',')];
  let matched = 0, skipped = 0;

  data.forEach((d, i) => {
    const udId = window.UNDERDOG_IDS && window.UNDERDOG_IDS[d.n];
    if (!udId) { skipped++; return; }
    matched++;
    const meta = (window.UNDERDOG_META && window.UNDERDOG_META[d.n]) || null;
    const displayRank = useFilteredRank ? (i + 1) : d.myRank;
    const parts = d.n.split(' ');
    // Prefer Underdog's own name spelling (e.g. Kenny Gainwell, Hollywood Brown)
    // so uploads match their player records.
    const firstName = meta ? meta.f : (parts[0] || '');
    let lastName = meta ? meta.l : (parts.slice(1).join(' ') || '');
    // Underdog's own export drops the suffix from some lastNames ("Harrison"
    // for Marvin Harrison Jr.) but their upload matcher wants the suffixed
    // name — re-append the site name's suffix when it's missing.
    const suf = (d.n.match(/ (Jr\.?|Sr\.?|II|III|IV|V)$/) || [])[1];
    if (suf && !lastName.endsWith(suf)) lastName += ' ' + suf;
    const posRank = d.myPosRank || d.r || '';
    const ppgProj = adjProjPpg(d) != null ? (adjProjPpg(d) * 17).toFixed(1) : '0.0';

    rows.push([
      esc(udId),
      esc(firstName),
      esc(lastName),
      esc(displayRank),
      esc(ppgProj),
      esc(meta ? meta.sal : ''),
      esc(posRank),
      esc(d.s),
      esc(meta ? meta.tm : d.t),
      '',
      ''
    ].join(','));
  });
  
  const csv = '\uFEFF' + rows.join('\r\n');
  const blob = new Blob([csv], {type: 'text/csv;charset=utf-8;'});
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `${verLabel}-${modeLabel}-${posLabel}-Underdog-Rankings.csv`;
  a.click();
  toast(`Exported ${matched} players to Underdog CSV` + (skipped ? ` (${skipped} skipped, no Underdog ID)` : ''));
});

