// === LIVE INJURY UPDATES: Load from Firestore and merge into D array ===
// The injury_scanner.py script pushes injury data to Firestore doc 'site_data/injury_updates'.
// This loads it on page load so the JS model injury discount system has fresh data.
// Also loads team/roster updates from 'site_data/roster_updates' for FA signings, trades, etc.
(function() {
  // firebase (app) now initializes early via the head loader, but firestore-compat stays
  // deferred, so `firebase.firestore` is still undefined during parse — bail cleanly then,
  // exactly as before. (NOTE: this loader has effectively no-op'd on load for a while because
  // the SDK isn't present at parse time; see the separately-flagged fix to run it via
  // _whenFirebaseReady if the injury/roster feed should actually apply.)
  if (typeof firebase === 'undefined' || !firebase.firestore || typeof D === 'undefined') return;
  var _pendingUpdates = 0;
  var _completedUpdates = 0;

  function _rebuildIfDone() {
    _completedUpdates++;
  }

  // --- Injury Updates ---
  _pendingUpdates++;
  try {
    firebase.firestore().collection('site_data').doc('injury_updates').get().then(function(doc) {
      if (!doc.exists) { _rebuildIfDone(); return; }
      var data = doc.data();
      if (!data || !data.players) { _rebuildIfDone(); return; }
      var updated = 0;
      var cleared = 0;
      var players = data.players;
      var clearedList = data.cleared || []; // players Sleeper shows as healthy now
      
      // Apply injury tags
      D.forEach(function(d) {
        if (!d.n) return;
        if (players[d.n]) {
          var p = players[d.n];
          if (!d.inj || d._injFromFirestore) {
            d.inj = p.inj;
            d._injFromFirestore = true;
            updated++;
          }
        }
      });
      
      // Clear injuries for players Sleeper now shows as healthy
      if (clearedList.length > 0) {
        var clearedSet = {};
        clearedList.forEach(function(name) { clearedSet[name] = true; });
        D.forEach(function(d) {
          if (d.n && d._injFromFirestore && clearedSet[d.n]) {
            d.inj = null;
            d._injFromFirestore = false;
            d._injDiscount = null;
            cleared++;
          }
        });
      }
      
      if (updated > 0 || cleared > 0) {
        console.log('[InjuryUpdates] Applied ' + updated + ' injuries, cleared ' + cleared + ' (updated: ' + (data.updated || 'unknown') + ')');
      }
      _rebuildIfDone();
    }).catch(function(e) {
      console.log('[InjuryUpdates] Could not load:', e.message || e);
      _rebuildIfDone();
    });
  } catch(e) { _rebuildIfDone(); }

  // --- Roster/Team Updates ---
  _pendingUpdates++;
  try {
    firebase.firestore().collection('site_data').doc('roster_updates').get().then(function(doc) {
      if (!doc.exists) { _rebuildIfDone(); return; }
      var data = doc.data();
      if (!data || !data.players) { _rebuildIfDone(); return; }
      var updated = 0;
      var players = data.players;
      D.forEach(function(d) {
        if (!d.n || !players[d.n]) return;
        var newTeam = players[d.n];
        if (newTeam && d.t !== newTeam) {
          d.t = newTeam;
          updated++;
        }
      });
      if (updated > 0) {
        console.log('[RosterUpdates] Updated ' + updated + ' team assignments (updated: ' + (data.updated || 'unknown') + ')');
      }
      _rebuildIfDone();
    }).catch(function(e) {
      console.log('[RosterUpdates] Could not load:', e.message || e);
      _rebuildIfDone();
    });
  } catch(e) { _rebuildIfDone(); }
})();

// === NAME COLLISION FIX: Clear old career data for current players with same name as retired NFL players ===
// Must be RE-RUNNABLE, not a one-shot IIFE: all_players.js / legend_careers.js / the weekly
// bundles are lazy-loaded, and each enrichment pass (_enrichFromAllPlayers,
// _applyLegendCareerBindings, _mergeAllPlayersWeekly) can re-graft the retired player's
// career or game logs by bare name AFTER a one-shot fix already ran. Each of those passes
// calls window._fixNameCollisions() again after merging.
window._fixNameCollisions = function() {
  // Drop pre-debut seasons from a current player's career (a same-named retired
  // player's rows merged in by name). Keeps the current player's real seasons.
  function _dropPreDebut(name, pos, debutYr) {
    var d = D.find(function(x) { return x.n === name && (!pos || x.s === pos) && !x._retired; });
    if (d) {
      // Snapshot the pristine d.js career on first run (parse time, before any lazy
      // merge) — a wholesale career replacement by _bestCareer drops the current
      // player's real rows along with the bogus ones, so we restore them below.
      if (!d._preMergeCareer) d._preMergeCareer = (d.career || []).slice();
      if (d.career && d.career.some(function(s) { return s.yr < debutYr; })) {
        d.career = d.career.filter(function(s) { return s.yr >= debutYr; });
      }
      d._preMergeCareer.forEach(function(row) {
        if (row.yr >= debutYr && !(d.career || []).some(function(s) { return s.yr === row.yr; })) {
          d.career = (d.career || []).concat([row]);
        }
      });
      if (d.career) d.career.sort(function(a, b) { return a.yr - b.yr; });
    }
    // Same-named retired player's game logs merged into WEEKLY_STATS by bare name.
    if (typeof WEEKLY_STATS !== 'undefined' && WEEKLY_STATS[name] && WEEKLY_STATS[name].seasons) {
      var seasons = WEEKLY_STATS[name].seasons;
      Object.keys(seasons).forEach(function(y) { if (+y < debutYr) delete seasons[y]; });
    }
  }
  // Kyle Williams (2025 WR, Washington State, NE) — collides with old Kyle Williams (49ers WR 2010-2013)
  _dropPreDebut('Kyle Williams', 'WR', 2025);
  // Antonio Williams (2026 WR, Washington Commanders) — collides with Antonio Williams (RB, BUF 2020)
  _dropPreDebut('Antonio Williams', 'WR', 2026);
  // Chris Brazzell II (2026 WR, Tennessee) — ALL_PLAYERS_DB once held the 1999-2000 Cowboys WR
  // (Chris Brazzell, no suffix) under the suffixed key; renamed in data 2026-07-21, guarded here too.
  _dropPreDebut('Chris Brazzell II', 'WR', 2026);
  // Marvin Harrison (HOF WR, Colts 1996-2008) vs Marvin Harrison Jr. (Cardinals
  // 2024+). Some data sources (weekly_stats.js, ALL_PLAYERS_DB) merged the
  // rookie's stats under the bare "Marvin Harrison" key, inflating the dad's
  // career totals by ~100 rec in trivia. Split: any season >= 2024 belongs
  // to Jr.; any season < 2024 is the HOF dad. The dad is _retired (career
  // ended 2008) so D entry should keep only pre-2024 seasons. The Jr. entry
  // (separate D row at offset ~1.67M in all_players.js) keeps its own data.
  var mh = D.find(function(d) { return d.n === 'Marvin Harrison' && d.s === 'WR'; });
  if (mh && mh.career && mh.career.length > 0) {
    var modernSeasons = mh.career.filter(function(s) { return s.yr >= 2024; });
    if (modernSeasons.length > 0) {
      // Drop the rookie's seasons from the dad's career array.
      mh.career = mh.career.filter(function(s) { return s.yr < 2024; });
    }
  }
};
window._fixNameCollisions();


// Add HP players with LEGEND_CAREERS data to D so they get full career log cards
