window.fmtHeight = fmtHeight;




// === PROFILE BADGE SYSTEM ===
(function(){
  // BADGES moved to data/badges.js

  const BADGE_STORAGE_KEY = 'jb_active_badge';
  const BADGE_UNLOCKED_KEY = 'jb_unlocked_badges';
  const GIFTED_BADGES_KEY = 'jb_gifted_badges';

  // Load gifted badges from Firestore into localStorage
  function loadGiftedBadges() {
    const db = (typeof firebase !== 'undefined' && firebase.firestore) ? firebase.firestore() : null;
    const user = (typeof firebase !== 'undefined' && firebase.auth) ? firebase.auth().currentUser : null;
    if (!db || !user) return;
    db.collection('gifted_badges').doc(user.uid).get().then(doc => {
      if (doc.exists) {
        const data = doc.data();
        const badges = data.badges || [];
        localStorage.setItem(GIFTED_BADGES_KEY, JSON.stringify(badges));
        getUnlockedBadges();
        if (typeof window._renderBadgeGrid === 'function') window._renderBadgeGrid();
      }
    }).catch(e => console.warn('[Badges] gifted load error:', e));
  }

  // Check and claim Founder badge (first 100 users)
  function checkFounderStatus() {
    const db = (typeof firebase !== 'undefined' && firebase.firestore) ? firebase.firestore() : null;
    const user = (typeof firebase !== 'undefined' && firebase.auth) ? firebase.auth().currentUser : null;
    if (!db || !user) return;
    // Already a founder? Skip
    if (localStorage.getItem('jb_is_founder') === 'true') return;

    const counterRef = db.collection('app_meta').doc('founder_counter');
    const founderRef = db.collection('founders').doc(user.uid);

    // Check if this user already claimed founder
    founderRef.get().then(doc => {
      if (doc.exists) {
        // Already a founder
        localStorage.setItem('jb_is_founder', 'true');
        getUnlockedBadges();
        renderAllAvatars();
        return;
      }
      // Check counter
      return counterRef.get().then(cDoc => {
        const count = cDoc.exists ? (cDoc.data().count || 0) : 0;
        if (count >= 100) {
          // Too late, not a founder
          localStorage.setItem('jb_is_founder', 'false');
          return;
        }
        // Claim founder spot — use a batch to atomically set both
        const batch = db.batch();
        batch.set(founderRef, {
          email: user.email || '',
          name: user.displayName || '',
          claimedAt: new Date().toISOString(),
          number: count + 1
        });
        // Increment counter
        batch.set(counterRef, { count: firebase.firestore.FieldValue.increment(1) }, { merge: true });
        return batch.commit().then(() => {
          localStorage.setItem('jb_is_founder', 'true');
          getUnlockedBadges();
          renderAllAvatars();
          console.log('[Badges] Founder badge claimed! #' + (count + 1));
        });
      });
    }).catch(e => {
      console.warn('[Badges] founder check error:', e);
    });
  }

  function getUnlockedBadges() {
    const saved = JSON.parse(localStorage.getItem(BADGE_UNLOCKED_KEY) || '[]');
    const gifted = JSON.parse(localStorage.getItem(GIFTED_BADGES_KEY) || '[]');
    const unlocked = new Set(saved);
    unlocked.add('default');
    // Admins get every badge
    if (typeof window.isAdmin === 'function' && window.isAdmin()) {
      BADGES.forEach(b => unlocked.add(b.id));
    } else {
      // Add gifted badges
      gifted.forEach(id => unlocked.add(id));
      // Check automatic unlocks
      BADGES.forEach(b => {
        if (b.always || (b.check && b.check())) unlocked.add(b.id);
      });
    }
    localStorage.setItem(BADGE_UNLOCKED_KEY, JSON.stringify([...unlocked]));
    return unlocked;
  }

  function getActiveBadge() {
    return localStorage.getItem(BADGE_STORAGE_KEY) || 'default';
  }

  function setActiveBadge(id) {
    localStorage.setItem(BADGE_STORAGE_KEY, id);
    renderAllAvatars();
    // Save to Firestore so it shows on leaderboards
    try {
      const db = (typeof firebase !== 'undefined' && firebase.firestore) ? firebase.firestore() : null;
      const user = (typeof firebase !== 'undefined' && firebase.auth) ? firebase.auth().currentUser : null;
      if (db && user) {
        const badge = getBadgeById(id);
        db.collection('leaderboard').doc(user.uid).set({
          activeBadge: id,
          activeBadgeIcon: badge ? badge.icon : null
        }, { merge: true }).then(function() {
          console.log('[Badge] Saved badge to leaderboard:', id);
        }).catch(function(e) { console.warn('[Badge] save error:', e); });
      } else {
        console.warn('[Badge] Cannot save - db:', !!db, 'user:', !!user);
      }
    } catch(e) { console.warn('[Badge] save error:', e); }
  }

  function getBadgeById(id) {
    return BADGES.find(b => b.id === id);
  }

  // Render avatars everywhere
  function renderAllAvatars() {
    const active = getActiveBadge();
    const badge = getBadgeById(active);
    const els = [
      document.getElementById('acctPageAvatar'),
      document.getElementById('globalAcctAvatar'),
      document.getElementById('homeAcctAvatar')
    ];
    els.forEach(el => {
      if (!el) return;
      if (badge && active !== 'default') {
        el.innerHTML = '<span class="avatar-badge" style="font-size:' + (el.classList.contains('acct-avatar-lg') ? '2.2rem' : '.95rem') + '">' + badge.icon + '</span>';
        el.style.background = 'var(--surface2)';
        el.style.border = '2px solid var(--accent)';
      } else {
        const user = (typeof firebase !== 'undefined' && firebase.auth) ? firebase.auth().currentUser : null;
        const initial = user ? (user.displayName || user.email || '?')[0].toUpperCase() : '?';
        el.textContent = initial;
        el.style.background = '';
        el.style.border = '';
      }
    });
  }

  function renderBadgeGrid() {
    const grid = document.getElementById('badgeGrid');
    const progList = document.getElementById('badgeProgressList');
    if (!grid) return;
    const unlocked = getUnlockedBadges();
    const active = getActiveBadge();

    grid.innerHTML = BADGES.map(b => {
      const isUnlocked = unlocked.has(b.id);
      const isActive = active === b.id;
      return `<div class="badge-cell ${isUnlocked ? '' : 'badge-locked'} ${isActive ? 'badge-active' : ''}" data-badge="${b.id}" title="${b.desc}">
        ${!isUnlocked ? '<span class="badge-lock">🔒</span>' : ''}
        <div class="badge-icon">${b.icon}</div>
        <div class="badge-label">${b.name}</div>
        ${isActive ? '<div style="font-size:.5rem;color:var(--accent);font-weight:700;letter-spacing:.5px">ACTIVE</div>' : ''}
      </div>`;
    }).join('');

    grid.querySelectorAll('.badge-cell:not(.badge-locked)').forEach(cell => {
      cell.addEventListener('click', () => {
        setActiveBadge(cell.dataset.badge);
        renderBadgeGrid();
      });
    });

    // Progress list
    if (progList) {
      progList.innerHTML = BADGES.filter(b => !b.always).map(b => {
        const isUnlocked = unlocked.has(b.id);
        const current = b.getCurrent ? b.getCurrent() : (isUnlocked ? 1 : 0);
        const goal = b.goal || 1;
        const pct = Math.min(100, Math.round((current / goal) * 100));
        return `<div class="badge-prog-row ${isUnlocked ? 'done' : ''}">
          <span class="badge-prog-icon">${b.icon}</span>
          <div class="badge-prog-info">
            <div class="badge-prog-name">${b.name}</div>
            <div class="badge-prog-desc">${b.desc}</div>
            ${!isUnlocked && b.goal ? `<div class="badge-prog-bar"><div class="badge-prog-fill" style="width:${pct}%"></div></div>
            <div style="font-size:.55rem;color:var(--text2);margin-top:2px">${typeof current==='number'?current.toFixed(current%1?1:0):current} / ${goal}</div>` : ''}
          </div>
          <span class="badge-prog-check">${isUnlocked ? '✅' : ''}</span>
        </div>`;
      }).join('');
    }
  }

  // Hook into tab switching to render badges when tab opens
  const origTabClick = document.querySelectorAll('.acct-tab');
  origTabClick.forEach(tab => {
    tab.addEventListener('click', () => {
      if (tab.dataset.acctTab === 'badges') setTimeout(renderBadgeGrid, 50);
    });
  });

  // === ADMIN PANEL LOGIC ===
  function findUserUid(db, email) {
    return db.collection('leaderboard').get().then(snap => {
      let uid = null;
      snap.forEach(doc => {
        const data = doc.data();
        if (data.email && data.email.toLowerCase() === email) uid = doc.id;
      });
      if (uid) return uid;
      return db.collection('gifted_badges').get().then(gbSnap => {
        gbSnap.forEach(doc => {
          const data = doc.data();
          if (data.email && data.email.toLowerCase() === email) uid = doc.id;
        });
        return uid || ('email_' + email.replace(/[^a-z0-9]/g, '_'));
      });
    });
  }

  function showAdminMsg(el, msg, type) {
    if (!el) return;
    el.textContent = msg;
    el.className = 'acct-msg ' + type;
    setTimeout(() => { el.className = 'acct-msg'; el.textContent = ''; }, 8000);
  }

  function initAdminPanel() {
    const adminTab = document.getElementById('acctAdminTab');
    const adminPanel = document.getElementById('acctPanelAdmin');
    if (typeof window.isAdmin === 'function' && window.isAdmin()) {
      adminTab.style.display = '';
      if (adminPanel) adminPanel.style.display = '';
      // Reveal the admin-only Tier Cards view toggle on the rankings page
      if (typeof window._refreshAdminViewToggle === 'function') window._refreshAdminViewToggle();
    } else {
      adminTab.style.display = 'none';
      if (adminPanel) { adminPanel.classList.remove('active'); adminPanel.style.display = 'none'; }
      return;
    }

    // Populate badge dropdown
    const badgeSelect = document.getElementById('adminGiftBadgeSelect');
    if (badgeSelect && !badgeSelect.children.length) {
      BADGES.filter(b => b.id !== 'default').forEach(b => {
        const opt = document.createElement('option');
        opt.value = b.id;
        opt.textContent = b.icon + ' ' + b.name;
        badgeSelect.appendChild(opt);
      });
    }

    // Badge gift/revoke
    const giftBadgeBtn = document.getElementById('adminGiftBadgeBtn');
    const revokeBadgeBtn = document.getElementById('adminRevokeBadgeBtn');
    const badgeMsg = document.getElementById('adminGiftBadgeMsg');

    if (giftBadgeBtn && !giftBadgeBtn._bound) {
      giftBadgeBtn._bound = true;
      giftBadgeBtn.addEventListener('click', () => {
        const db = (typeof firebase !== 'undefined' && firebase.firestore) ? firebase.firestore() : null;
        const email = document.getElementById('adminGiftBadgeEmail').value.trim().toLowerCase();
        const badgeId = document.getElementById('adminGiftBadgeSelect').value;
        if (!db) { showAdminMsg(badgeMsg, 'Database not available', 'error'); return; }
        if (!email) { showAdminMsg(badgeMsg, 'Enter an email', 'error'); return; }
        findUserUid(db, email).then(uid => {
          const docRef = db.collection('gifted_badges').doc(uid);
          return docRef.get().then(doc => {
            let badges = doc.exists ? (doc.data().badges || []) : [];
            if (!badges.includes(badgeId)) badges.push(badgeId);
            return docRef.set({ email, badges, updatedAt: new Date().toISOString() }, { merge: true });
          }).then(() => {
            const badge = getBadgeById(badgeId);
            showAdminMsg(badgeMsg, 'Gifted ' + (badge ? badge.icon + ' ' + badge.name : badgeId) + ' to ' + email, 'success');
          });
        }).catch(e => showAdminMsg(badgeMsg, 'Error: ' + e.message, 'error'));
      });

      revokeBadgeBtn.addEventListener('click', () => {
        const db = (typeof firebase !== 'undefined' && firebase.firestore) ? firebase.firestore() : null;
        const email = document.getElementById('adminGiftBadgeEmail').value.trim().toLowerCase();
        const badgeId = document.getElementById('adminGiftBadgeSelect').value;
        if (!db) { showAdminMsg(badgeMsg, 'Database not available', 'error'); return; }
        if (!email) { showAdminMsg(badgeMsg, 'Enter an email', 'error'); return; }
        findUserUid(db, email).then(uid => {
          const docRef = db.collection('gifted_badges').doc(uid);
          return docRef.get().then(doc => {
            let badges = doc.exists ? (doc.data().badges || []) : [];
            badges = badges.filter(b => b !== badgeId);
            return docRef.set({ email, badges, updatedAt: new Date().toISOString() }, { merge: true });
          }).then(() => {
            const badge = getBadgeById(badgeId);
            showAdminMsg(badgeMsg, 'Revoked ' + (badge ? badge.icon + ' ' + badge.name : badgeId) + ' from ' + email, 'success');
          });
        }).catch(e => showAdminMsg(badgeMsg, 'Error: ' + e.message, 'error'));
      });
    }

    // Premium gift/revoke
    const giftPremBtn = document.getElementById('adminGiftPremBtn');
    const premMsg = document.getElementById('adminGiftPremMsg');

    if (giftPremBtn && !giftPremBtn._bound) {
      giftPremBtn._bound = true;
      giftPremBtn.addEventListener('click', () => {
        try {
          const db = (typeof firebase !== 'undefined' && firebase.firestore) ? firebase.firestore() : null;
          const email = document.getElementById('adminGiftPremEmail').value.trim().toLowerCase();
          const days = parseInt(document.getElementById('adminGiftPremDuration').value);
          if (!db) { showAdminMsg(premMsg, 'Database not available', 'error'); return; }
          if (!email) { showAdminMsg(premMsg, 'Enter an email', 'error'); return; }
          giftPremBtn.disabled = true;
          giftPremBtn.textContent = 'GRANTING...';
          const expires = Date.now() + (days * 24 * 60 * 60 * 1000);
          const labels = { 7: '1 Week', 30: '1 Month', 150: 'Season Pass', 365: 'Yearly Pass' };
          const expDate = new Date(expires).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
          const docId = email.replace(/[^a-z0-9]/g, '_');
          const adminEmail = (typeof firebase !== 'undefined' && firebase.auth && firebase.auth().currentUser) ? firebase.auth().currentUser.email : 'admin';
          db.collection('gifted_premium').doc(docId).set({
            email: email,
            expires: expires,
            days: days,
            label: labels[days] || days + ' days',
            grantedBy: adminEmail,
            grantedAt: new Date().toISOString()
          }).then(function() {
            giftPremBtn.disabled = false;
            giftPremBtn.textContent = 'GRANT PREMIUM';
            showAdminMsg(premMsg, '✅ Granted ' + (labels[days] || days + ' days') + ' premium to ' + email + ' — expires ' + expDate, 'success');
          }).catch(function(e) {
            giftPremBtn.disabled = false;
            giftPremBtn.textContent = 'GRANT PREMIUM';
            showAdminMsg(premMsg, 'Firestore error: ' + e.message, 'error');
          });
        } catch(err) {
          giftPremBtn.disabled = false;
          giftPremBtn.textContent = 'GRANT PREMIUM';
          showAdminMsg(premMsg, 'Error: ' + err.message, 'error');
          console.error('[Admin] Grant premium error:', err);
        }
      });
    }

    // ===== Premium Redeem Codes =====
    const premCodeCreateBtn = document.getElementById('adminPremCodeCreateBtn');
    const premCodeRefreshBtn = document.getElementById('adminPremCodeRefreshBtn');
    const premCodeListEl = document.getElementById('adminPremCodeList');
    const premCodeMsg = document.getElementById('adminPremCodeMsg');

    function _renderPremCodeRow(code, data) {
      const expiresStr = data.expires || '';
      let expDate = null;
      if (expiresStr) {
        const [ey, em, ed] = expiresStr.split('-').map(Number);
        expDate = new Date(ey, em - 1, ed, 23, 59, 59, 999);
      }
      const expired = expDate ? (Date.now() > expDate.getTime()) : false;
      const disabled = !!data.disabled;
      const uses = (typeof data.uses === 'number') ? data.uses : 0;
      const status = disabled ? 'DISABLED' : (expired ? 'EXPIRED' : 'ACTIVE');
      const statusColor = disabled ? '#ef4444' : (expired ? '#9ca3af' : '#22c55e');
      return '<div style="display:flex;align-items:center;justify-content:space-between;gap:.5rem;padding:.5rem .65rem;border:1px solid var(--border);border-radius:6px;background:var(--elev-1)">' +
        '<div style="display:flex;flex-direction:column;gap:2px;min-width:0;flex:1">' +
          '<div style="display:flex;align-items:center;gap:.5rem;flex-wrap:wrap"><span style="font-family:\'JetBrains Mono\',\'DM Sans\',monospace;font-weight:700;letter-spacing:1px">' + code + '</span>' +
          '<span style="font-size:.62rem;color:' + statusColor + ';letter-spacing:1px;font-weight:600">' + status + '</span></div>' +
          '<div style="font-size:.68rem;color:var(--text2)">' + (data.days || 0) + 'd premium · expires ' + (expiresStr || '?') + ' · used ' + uses + 'x</div>' +
        '</div>' +
        '<div style="display:flex;gap:4px;flex-shrink:0">' +
          '<button class="acct-btn acct-btn-outline" data-pc-copy="' + code + '" style="padding:.3rem .55rem;font-size:.65rem">COPY</button>' +
          '<button class="acct-btn acct-btn-outline" data-pc-toggle="' + code + '" data-pc-disabled="' + (disabled ? '1' : '0') + '" style="padding:.3rem .55rem;font-size:.65rem">' + (disabled ? 'ENABLE' : 'DISABLE') + '</button>' +
          '<button class="acct-btn acct-btn-outline" data-pc-delete="' + code + '" style="padding:.3rem .55rem;font-size:.65rem;color:#ef4444">DELETE</button>' +
        '</div>' +
      '</div>';
    }

    function loadPremiumCodes() {
      if (!premCodeListEl) return;
      const db = (typeof firebase !== 'undefined' && firebase.firestore) ? firebase.firestore() : null;
      if (!db) { premCodeListEl.innerHTML = '<div style="color:var(--text2);font-size:.7rem">Database unavailable.</div>'; return; }
      premCodeListEl.innerHTML = '<div style="color:var(--text2);font-size:.7rem">Loading…</div>';
      db.collection('premium_codes').orderBy('createdAt', 'desc').limit(50).get().then(snap => {
        if (snap.empty) {
          premCodeListEl.innerHTML = '<div style="color:var(--text2);font-size:.7rem">No codes yet.</div>';
          return;
        }
        const rows = [];
        snap.forEach(doc => { rows.push(_renderPremCodeRow(doc.id, doc.data() || {})); });
        premCodeListEl.innerHTML = rows.join('');
      }).catch(e => {
        premCodeListEl.innerHTML = '<div style="color:#ef4444;font-size:.7rem">Load error: ' + (e.message || e) + '</div>';
      });
    }

    if (premCodeCreateBtn && !premCodeCreateBtn._bound) {
      premCodeCreateBtn._bound = true;
      premCodeCreateBtn.addEventListener('click', () => {
        try {
          const db = (typeof firebase !== 'undefined' && firebase.firestore) ? firebase.firestore() : null;
          if (!db) { showAdminMsg(premCodeMsg, 'Database not available', 'error'); return; }
          const codeRaw = (document.getElementById('adminPremCodeName').value || '').trim().toUpperCase();
          const days = parseInt(document.getElementById('adminPremCodeDays').value, 10);
          const expires = (document.getElementById('adminPremCodeExpires').value || '').trim();
          if (!codeRaw || !/^[A-Z0-9_-]{3,40}$/.test(codeRaw)) {
            showAdminMsg(premCodeMsg, 'Code must be 3–40 chars, letters/numbers/-/_ only.', 'error'); return;
          }
          if (!days || days < 1 || days > 3650) {
            showAdminMsg(premCodeMsg, 'Days must be between 1 and 3650.', 'error'); return;
          }
          if (!expires || !/^\d{4}-\d{2}-\d{2}$/.test(expires)) {
            showAdminMsg(premCodeMsg, 'Pick a valid expiration date.', 'error'); return;
          }
          const [ey, em, ed] = expires.split('-').map(Number);
          const expEnd = new Date(ey, em - 1, ed, 23, 59, 59, 999).getTime();
          if (expEnd < Date.now()) {
            showAdminMsg(premCodeMsg, 'Expiration date is in the past.', 'error'); return;
          }
          premCodeCreateBtn.disabled = true;
          premCodeCreateBtn.textContent = 'CREATING…';
          const adminEmail = (firebase.auth && firebase.auth().currentUser) ? firebase.auth().currentUser.email : 'admin';
          const docRef = db.collection('premium_codes').doc(codeRaw);
          docRef.get().then(snap => {
            if (snap.exists) {
              throw new Error('Code ' + codeRaw + ' already exists.');
            }
            return docRef.set({
              code: codeRaw,
              days: days,
              expires: expires,
              disabled: false,
              uses: 0,
              createdBy: adminEmail,
              createdAt: new Date().toISOString()
            });
          }).then(() => {
            premCodeCreateBtn.disabled = false;
            premCodeCreateBtn.textContent = 'CREATE CODE';
            showAdminMsg(premCodeMsg, '✅ Created code ' + codeRaw + ' — ' + days + ' days premium, redeemable until ' + expires, 'success');
            document.getElementById('adminPremCodeName').value = '';
            loadPremiumCodes();
          }).catch(e => {
            premCodeCreateBtn.disabled = false;
            premCodeCreateBtn.textContent = 'CREATE CODE';
            showAdminMsg(premCodeMsg, 'Error: ' + (e.message || e), 'error');
          });
        } catch (err) {
          premCodeCreateBtn.disabled = false;
          premCodeCreateBtn.textContent = 'CREATE CODE';
          showAdminMsg(premCodeMsg, 'Error: ' + err.message, 'error');
        }
      });
    }

    if (premCodeRefreshBtn && !premCodeRefreshBtn._bound) {
      premCodeRefreshBtn._bound = true;
      premCodeRefreshBtn.addEventListener('click', loadPremiumCodes);
    }

    if (premCodeListEl && !premCodeListEl._bound) {
      premCodeListEl._bound = true;
      premCodeListEl.addEventListener('click', (e) => {
        const btn = e.target.closest('button');
        if (!btn) return;
        const db = (typeof firebase !== 'undefined' && firebase.firestore) ? firebase.firestore() : null;
        if (!db) return;
        const copyCode = btn.getAttribute('data-pc-copy');
        const toggleCode = btn.getAttribute('data-pc-toggle');
        const deleteCode = btn.getAttribute('data-pc-delete');
        if (copyCode) {
          if (navigator.clipboard) navigator.clipboard.writeText(copyCode).catch(()=>{});
          showAdminMsg(premCodeMsg, 'Copied ' + copyCode + ' to clipboard.', 'success');
          return;
        }
        if (toggleCode) {
          const willDisable = btn.getAttribute('data-pc-disabled') !== '1';
          db.collection('premium_codes').doc(toggleCode).update({ disabled: willDisable }).then(() => {
            showAdminMsg(premCodeMsg, (willDisable ? 'Disabled ' : 'Enabled ') + toggleCode, 'success');
            loadPremiumCodes();
          }).catch(err => showAdminMsg(premCodeMsg, 'Error: ' + err.message, 'error'));
          return;
        }
        if (deleteCode) {
          if (!confirm('Delete code ' + deleteCode + '? This cannot be undone.')) return;
          db.collection('premium_codes').doc(deleteCode).delete().then(() => {
            showAdminMsg(premCodeMsg, 'Deleted ' + deleteCode, 'success');
            loadPremiumCodes();
          }).catch(err => showAdminMsg(premCodeMsg, 'Error: ' + err.message, 'error'));
          return;
        }
      });
    }

    // Load the list on admin panel init
    loadPremiumCodes();

    // ===== Rankings Graphic Generator =====
    const gfxPreviewBtn = document.getElementById('adminGfxPreviewBtn');
    const gfxDownloadBtn = document.getElementById('adminGfxDownloadBtn');
    const gfxMsg = document.getElementById('adminGfxMsg');

    function _gfxLoadHtml2Canvas() {
      if (typeof window.html2canvas === 'function') return Promise.resolve();
      if (window._gfxH2cLoading) return window._gfxH2cLoading;
      // Try local copy first (bypasses CDN-blocking privacy extensions); fall back to CDNs
      const sources = [
        { url: 'vendor_html2canvas.min.js', cors: false },               // local (same-origin)
        { url: 'https://cdn.jsdelivr.net/npm/html2canvas@1.4.1/dist/html2canvas.min.js', cors: true },
        { url: 'https://unpkg.com/html2canvas@1.4.1/dist/html2canvas.min.js', cors: true },
        { url: 'https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js', cors: true },
        { url: 'https://cdn.skypack.dev/html2canvas@1.4.1', cors: true }
      ];
      window._gfxH2cLoading = (async () => {
        let lastErr = null;
        for (const src of sources) {
          try {
            await new Promise((resolve, reject) => {
              const s = document.createElement('script');
              s.src = src.url;
              if (src.cors) s.crossOrigin = 'anonymous';
              s.onload = () => resolve();
              s.onerror = () => reject(new Error('script error: ' + src.url));
              document.head.appendChild(s);
              setTimeout(() => reject(new Error('timeout: ' + src.url)), 8000);
            });
            if (typeof window.html2canvas === 'function') return;
          } catch (e) {
            lastErr = e;
            console.warn('[Gfx] source failed:', src.url, e && e.message);
          }
        }
        throw new Error('html2canvas could not be loaded. Last attempt: ' + (lastErr && lastErr.message));
      })();
      return window._gfxH2cLoading;
    }

    // NFL team primary colors (background + readable foreground for the row)
    const _GFX_TEAM_COLORS = {
      'Arizona Cardinals':     { bg: '#97233F', fg: '#FFFFFF' },
      'Atlanta Falcons':       { bg: '#A71930', fg: '#FFFFFF' },
      'Baltimore Ravens':      { bg: '#241773', fg: '#FFFFFF' },
      'Buffalo Bills':         { bg: '#00338D', fg: '#FFFFFF' },
      'Carolina Panthers':     { bg: '#0085CA', fg: '#FFFFFF' },
      'Chicago Bears':         { bg: '#0B162A', fg: '#C83803' },
      'Cincinnati Bengals':    { bg: '#FB4F14', fg: '#000000' },
      'Cleveland Browns':      { bg: '#311D00', fg: '#FF3C00' },
      'Dallas Cowboys':        { bg: '#003594', fg: '#FFFFFF' },
      'Denver Broncos':        { bg: '#FB4F14', fg: '#002244' },
      'Detroit Lions':         { bg: '#0076B6', fg: '#FFFFFF' },
      'Green Bay Packers':     { bg: '#203731', fg: '#FFB612' },
      'Houston Texans':        { bg: '#03202F', fg: '#FFFFFF' },
      'Indianapolis Colts':    { bg: '#002C5F', fg: '#FFFFFF' },
      'Jacksonville Jaguars':  { bg: '#101820', fg: '#D7A22A' },
      'Kansas City Chiefs':    { bg: '#E31837', fg: '#FFFFFF' },
      'Las Vegas Raiders':     { bg: '#000000', fg: '#A5ACAF' },
      'Los Angeles Chargers':  { bg: '#0080C6', fg: '#FFC20E' },
      'Los Angeles Rams':      { bg: '#003594', fg: '#FFA300' },
      'Miami Dolphins':        { bg: '#008E97', fg: '#FFFFFF' },
      'Minnesota Vikings':     { bg: '#4F2683', fg: '#FFC62F' },
      'New England Patriots':  { bg: '#002244', fg: '#FFFFFF' },
      'New Orleans Saints':    { bg: '#D3BC8D', fg: '#000000' },
      'New York Giants':       { bg: '#0B2265', fg: '#FFFFFF' },
      'New York Jets':         { bg: '#125740', fg: '#FFFFFF' },
      'Philadelphia Eagles':   { bg: '#004C54', fg: '#FFFFFF' },
      'Pittsburgh Steelers':   { bg: '#FFB612', fg: '#000000' },
      'San Francisco 49ers':   { bg: '#AA0000', fg: '#FFFFFF' },
      'Seattle Seahawks':      { bg: '#002244', fg: '#69BE28' },
      'Tampa Bay Buccaneers':  { bg: '#D50A0A', fg: '#FFFFFF' },
      'Tennessee Titans':      { bg: '#0C2340', fg: '#4B92DB' },
      'Washington Commanders': { bg: '#5A1414', fg: '#FFB612' }
    };
    function _gfxTeamColor(teamName) {
      return _GFX_TEAM_COLORS[teamName] || { bg: '#1f2937', fg: '#FFFFFF' };
    }

    function _gfxBuildList(pos, count, source, format) {
      // Pick the right board based on the source/format selectors. Falls back to live `board`.
      function _pickBoard() {
        if (typeof versionBoards === 'undefined') return null;
        const src = source && versionBoards[source] ? source : (typeof currentVersion !== 'undefined' ? currentVersion : null);
        if (!src || !versionBoards[src]) return null;
        const fmt = format && versionBoards[src][format] ? format : (typeof currentMode !== 'undefined' ? currentMode : null);
        if (!fmt) return null;
        return versionBoards[src][fmt];
      }
      const _activeBoard = _pickBoard() || (typeof board !== 'undefined' ? board : []);
      if (pos === 'DEVY') {
        if (typeof COMBINE_DATA === 'undefined') return [];
        const useFmt = format || (typeof currentMode !== 'undefined' ? currentMode : 'dynasty');
        const useSrc = source || (typeof currentVersion !== 'undefined' ? currentVersion : 'mine');
        const ktcMap = (useFmt === 'dynastysf')
          ? (typeof KTC_SF !== 'undefined' ? KTC_SF : {})
          : (typeof KTC_1QB !== 'undefined' ? KTC_1QB : {});
        const map = {};
        Object.keys(COMBINE_DATA).forEach(name => {
          const cb = COMBINE_DATA[name];
          if (!cb.devy) return;
          map[name] = { n: name, s: cb.pos || '??', t: cb.school || '—', _ktc: ktcMap[name] || 0, _isDevy: true };
        });
        const devyKey = 'devy_board_' + useSrc + '_' + useFmt;
        let saved = null;
        try { saved = JSON.parse(localStorage.getItem(devyKey)); } catch(e) {}
        let list;
        if (saved && Array.isArray(saved) && saved.length) {
          list = [];
          saved.forEach(name => { if (map[name]) { list.push(map[name]); delete map[name]; } });
          const rest = Object.values(map).sort((a, b) => b._ktc - a._ktc);
          list = list.concat(rest);
        } else {
          list = Object.values(map).sort((a, b) => b._ktc - a._ktc);
        }
        return list.slice(0, count);
      }
      if (typeof D === 'undefined' || !_activeBoard || !_activeBoard.length) return [];
      let list = _activeBoard.map(i => D[i]).filter(d => d && !d._retired && !d._isFuturePick);
      const seen = new Set();
      list = list.filter(d => { if (seen.has(d.n)) return false; seen.add(d.n); return true; });
      if (pos === 'ROOKIE' || pos === 'ROOKIE_QB' || pos === 'ROOKIE_RB' || pos === 'ROOKIE_WR' || pos === 'ROOKIE_TE') {
        const subPos = pos === 'ROOKIE' ? null : pos.split('_')[1];
        list = list.filter(d => {
          if (d.career && d.career.length > 0) return false;
          const cb = (typeof COMBINE_DATA !== 'undefined') ? COMBINE_DATA[d.n] : null;
          const is2026 = (cb && cb.yr === 2026);
          if (!is2026 && d.t && d.t !== 'TBD' && d.t !== 'FA') return false;
          if (subPos && d.s !== subPos) return false;
          return true;
        });
      } else if (pos === 'ALL') {
        list = list.filter(d => d.s !== 'K' && d.s !== 'DST');
      } else {
        list = list.filter(d => d.s === pos);
      }
      return list.slice(0, count);
    }

    function _gfxLogoUrl(player) {
      if (player._isDevy) {
        if (typeof _COLLEGE_LOGO_IDS === 'undefined') return '';
        const t = player.t || '';
        const id = _COLLEGE_LOGO_IDS[t] || _COLLEGE_LOGO_IDS[t.toUpperCase()];
        return id ? ('https://a.espncdn.com/i/teamlogos/ncaa/500/' + id + '.png') : '';
      }
      if (typeof TEAM_LOGO_IDS === 'undefined') return '';
      const id = TEAM_LOGO_IDS[player.t];
      return id ? ('https://a.espncdn.com/i/teamlogos/nfl/500/' + id + '.png') : '';
    }

    function _gfxBuildNode(opts) {
      const { pos, count, title, accent, posColor, theme, pageSlice, totalCount, source, format } = opts;
      const _posColor = posColor || '#FFD700';
      let list = _gfxBuildList(pos, count, source, format);
      if (pageSlice) list = list.slice(pageSlice[0], pageSlice[1]);
      if (!list.length) return { node: null, count: 0 };
      const startRank = pageSlice ? (pageSlice[0] + 1) : 1;
      const endRank = pageSlice ? Math.min(pageSlice[1], (totalCount || count)) : list.length;
      const showPageBadge = !!pageSlice;
      const themes = {
        purple: 'linear-gradient(135deg,#4c1d95 0%,#7c3aed 55%,#a78bfa 100%)',
        blue:   'linear-gradient(135deg,#1e3a8a 0%,#2563eb 55%,#60a5fa 100%)',
        red:    'linear-gradient(135deg,#7f1d1d 0%,#dc2626 55%,#fb7185 100%)',
        green:  'linear-gradient(135deg,#14532d 0%,#16a34a 55%,#4ade80 100%)',
        orange: 'linear-gradient(135deg,#7c2d12 0%,#ea580c 55%,#fb923c 100%)',
        dark:   'linear-gradient(135deg,#0f172a 0%,#1e293b 55%,#475569 100%)'
      };
      const headerBg = themes[theme] || themes.purple;
      const posLabels = { QB:'QB', RB:'RB', WR:'WR', TE:'TE', ROOKIE:'ROOKIE', ROOKIE_QB:'ROOKIE QB', ROOKIE_RB:'ROOKIE RB', ROOKIE_WR:'ROOKIE WR', ROOKIE_TE:'ROOKIE TE', ALL:'OVERALL', DEVY:'DEVY' };
      const posLabel = posLabels[pos] || pos;
      const rawTitle = title || '2026|FANTASY [POS]|RANKINGS';
      // Split on | for explicit line breaks; each line renders as its own block
      const titleLines = rawTitle.split('|').map(line =>
        line.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
            .replace(/\[POS\]/g, '<span style="color:' + _posColor + '">' + posLabel + '</span>')
      );
      const titleHtml = titleLines.map(line => '<div>' + line + '</div>').join('');
      const useTwoCols = list.length > 10;
      const half = useTwoCols ? Math.ceil(list.length / 2) : list.length;
      const col1 = list.slice(0, half);
      const col2 = list.slice(half);

      // Row sizing scales down as the per-page count grows (more rows = tighter)
      const _rowScale = list.length <= 12 ? 1.0 : list.length <= 24 ? 0.78 : 0.62;
      const RZ = (n) => Math.round(n * _rowScale);
      function rowHtml(player, rank) {
        const url = _gfxLogoUrl(player);
        const logoSize = RZ(72);
        const logo = url
          ? '<div style="width:' + logoSize + 'px;height:' + logoSize + 'px;display:flex;align-items:center;justify-content:center;flex:0 0 ' + logoSize + 'px;background:rgba(255,255,255,.95);border-radius:50%;padding:' + RZ(6) + 'px"><img src="' + url + '" alt="" crossorigin="anonymous" style="max-width:100%;max-height:100%;object-fit:contain"/></div>'
          : '<div style="width:' + logoSize + 'px;height:' + logoSize + 'px;background:rgba(255,255,255,.15);border-radius:50%;flex:0 0 ' + logoSize + 'px;display:flex;align-items:center;justify-content:center;color:#fff;font-size:' + RZ(20) + 'px">?</div>';
        const safeName = (player.n || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
        const tc = player._isDevy ? { bg: '#1f2937', fg: '#FFFFFF' } : _gfxTeamColor(player.t);
        const projPpg = (typeof adjProjPpg === 'function' && !player._isDevy) ? adjProjPpg(player) : null;
        const ppgHtml = (projPpg != null && isFinite(projPpg))
          ? '<div style="font-family:\'Bebas Neue\',Impact,Arial,sans-serif;font-size:' + RZ(40) + 'px;color:' + tc.fg + ';opacity:.92;letter-spacing:.5px;line-height:1;padding-left:' + RZ(14) + 'px;flex:0 0 auto">' + projPpg + '</div>'
          : '';
        return '<div style="display:flex;align-items:center;gap:' + RZ(18) + 'px;padding:' + RZ(14) + 'px ' + RZ(20) + 'px;background:' + tc.bg + ';border-radius:' + RZ(10) + 'px;box-shadow:inset 0 0 0 2px rgba(255,255,255,.07)">' +
          '<div style="font-family:\'Bebas Neue\',Impact,Arial,sans-serif;font-size:' + RZ(46) + 'px;color:' + tc.fg + ';min-width:' + RZ(60) + 'px;text-align:right;font-weight:700;line-height:1">' + rank + '.</div>' +
          logo +
          '<div style="font-family:\'Bebas Neue\',Impact,Arial,sans-serif;font-size:' + RZ(42) + 'px;color:' + tc.fg + ';letter-spacing:.6px;line-height:1;flex:1 1 0;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + safeName.toUpperCase() + '</div>' +
          ppgHtml +
          '</div>';
      }

      const wrap = document.createElement('div');
      wrap.style.cssText = 'width:1080px;background:#000;font-family:"Bebas Neue",Impact,Arial,sans-serif;color:#fff;position:relative;overflow:hidden;box-sizing:border-box';
      // Column layout for 1080×1920 portrait: single column for ≤12 (IG Story friendly), more cols as count grows
      const cols = list.length <= 12 ? 1
                 : list.length <= 24 ? 2
                 : list.length <= 36 ? 3
                 : 4;
      const rowsPerCol = Math.ceil(list.length / cols);
      const columnArrays = [];
      for (let c = 0; c < cols; c++) {
        columnArrays.push(list.slice(c * rowsPerCol, (c + 1) * rowsPerCol));
      }

      const pageBadgeHtml = showPageBadge
        ? '<div style="font-family:\'Bebas Neue\',Impact,Arial,sans-serif;font-size:34px;color:rgba(255,255,255,.92);letter-spacing:3px;background:rgba(0,0,0,.45);padding:6px 18px;border-radius:5px;display:inline-block;margin-top:14px">' + startRank + '–' + endRank + '</div>'
        : '';
      // MFF logo (ascending bars + trend line) — viewBox extended to include polyline tip + circle that go above y=0
      const mffLogo =
        '<svg viewBox="-2 -8 46 44" width="56" height="54" style="display:block">' +
          '<rect x="0" y="20" width="8" height="12" rx="1.5" fill="#000" opacity=".35"/>' +
          '<rect x="11" y="14" width="8" height="18" rx="1.5" fill="#000" opacity=".55"/>' +
          '<rect x="22" y="7" width="8" height="25" rx="1.5" fill="#000" opacity=".75"/>' +
          '<rect x="33" y="0" width="8" height="32" rx="1.5" fill="#000" opacity=".95"/>' +
          '<polyline points="4,17 15,11 26,4 37,-3" fill="none" stroke="#000" stroke-width="2" stroke-linecap="round"/>' +
          '<circle cx="37" cy="-3" r="3.5" fill="#000"/>' +
        '</svg>';
      wrap.innerHTML =
        '<div style="background:' + headerBg + ';padding:50px 56px 40px;position:relative;overflow:hidden;box-sizing:border-box">' +
          '<div style="position:absolute;top:0;right:0;width:0;height:0;border-style:solid;border-width:0 150px 150px 0;border-color:transparent ' + accent + ' transparent transparent"></div>' +
          '<div style="position:absolute;top:14px;right:14px;display:flex;align-items:center;justify-content:center">' + mffLogo + '</div>' +
          '<div style="font-family:\'Bebas Neue\',Impact,Arial,sans-serif;font-size:130px;line-height:.92;color:#fff;letter-spacing:3px;font-weight:900;text-transform:uppercase;padding-right:160px">' + titleHtml + '</div>' +
          pageBadgeHtml +
        '</div>' +
        '<div style="background:#000;padding:28px 36px;display:grid;grid-template-columns:repeat(' + cols + ',1fr);gap:18px;box-sizing:border-box">' +
          columnArrays.map((colPlayers, ci) => {
            const startIndexInPage = ci * rowsPerCol;
            return '<div style="display:flex;flex-direction:column;gap:10px">' +
              colPlayers.map((p, ri) => rowHtml(p, startRank + startIndexInPage + ri)).join('') +
            '</div>';
          }).join('') +
        '</div>' +
        '<div style="background:#000;padding:16px 40px 22px;text-align:center;font-family:\'Bebas Neue\',Impact,Arial,sans-serif;font-size:24px;color:rgba(255,255,255,.45);letter-spacing:6px;box-sizing:border-box">MYFANTASYFOOTBALL.CO</div>';
      return { node: wrap, count: list.length };
    }

    async function _gfxRender(opts) {
      await _gfxLoadHtml2Canvas();
      const built = _gfxBuildNode(opts);
      if (!built.node) return null;
      const holder = document.createElement('div');
      holder.style.cssText = 'position:fixed;left:-10000px;top:0;z-index:-1;pointer-events:none';
      holder.appendChild(built.node);
      document.body.appendChild(holder);
      try {
        const imgs = built.node.querySelectorAll('img');
        await Promise.all(Array.from(imgs).map(img => {
          if (img.complete && img.naturalWidth > 0) return Promise.resolve();
          return new Promise(res => {
            const t = setTimeout(res, 4000);
            img.onload = () => { clearTimeout(t); res(); };
            img.onerror = () => { clearTimeout(t); res(); };
          });
        }));
        const measuredHeight = built.node.offsetHeight;
        const canvas = await window.html2canvas(built.node, {
          backgroundColor: '#000',
          scale: 1,
          useCORS: true,
          allowTaint: false,
          logging: false,
          width: 1080,
          height: measuredHeight,
          windowWidth: 1080,
          windowHeight: measuredHeight
        });
        return canvas;
      } finally {
        holder.remove();
      }
    }

    function _gfxReadOpts() {
      const count = parseInt(document.getElementById('adminGfxCount').value, 10) || 12;
      let perPage = parseInt(document.getElementById('adminGfxPerPage').value, 10) || count;
      if (perPage > count) perPage = count;
      const srcEl = document.getElementById('adminGfxSource');
      const fmtEl = document.getElementById('adminGfxFormat');
      const posColorEl = document.getElementById('adminGfxPosColor');
      return {
        pos: document.getElementById('adminGfxPos').value,
        count: count,
        perPage: perPage,
        title: document.getElementById('adminGfxTitle').value,
        accent: document.getElementById('adminGfxAccent').value || '#facc15',
        posColor: (posColorEl && posColorEl.value) || '#FFD700',
        theme: document.getElementById('adminGfxTheme').value || 'purple',
        source: srcEl ? srcEl.value : null,
        format: fmtEl ? fmtEl.value : null
      };
    }

    function _gfxPageRanges(count, perPage) {
      // Returns array of [start, end) slices. Single page if perPage >= count.
      if (!perPage || perPage >= count) return [null]; // null = no slicing, single image
      const out = [];
      for (let s = 0; s < count; s += perPage) {
        out.push([s, Math.min(s + perPage, count)]);
      }
      return out;
    }

    async function _gfxRenderAllPages(opts) {
      const ranges = _gfxPageRanges(opts.count, opts.perPage);
      const canvases = [];
      for (const r of ranges) {
        const pageOpts = Object.assign({}, opts, { pageSlice: r, totalCount: opts.count });
        const c = await _gfxRender(pageOpts);
        if (c) canvases.push({ canvas: c, range: r });
      }
      return canvases;
    }

    if (gfxPreviewBtn && !gfxPreviewBtn._bound) {
      gfxPreviewBtn._bound = true;
      gfxPreviewBtn.addEventListener('click', async () => {
        const opts = _gfxReadOpts();
        showAdminMsg(gfxMsg, 'Generating preview…', 'success');
        try {
          const pages = await _gfxRenderAllPages(opts);
          if (!pages.length) { showAdminMsg(gfxMsg, 'No players for that filter — check your board', 'error'); return; }
          const wrap = document.getElementById('adminGfxPreviewWrap');
          wrap.innerHTML = '';
          pages.forEach((p, i) => {
            const label = document.createElement('div');
            label.style.cssText = 'font-family:\'Bebas Neue\',sans-serif;font-size:.7rem;color:var(--text2);letter-spacing:1.5px;margin:8px 0 4px;text-align:left';
            label.textContent = pages.length > 1 ? ('PAGE ' + (i + 1) + ' OF ' + pages.length + (p.range ? ' · #' + (p.range[0] + 1) + '–' + p.range[1] : '')) : '';
            if (label.textContent) wrap.appendChild(label);
            const img = new Image();
            img.src = p.canvas.toDataURL('image/png');
            img.style.cssText = 'max-width:100%;height:auto;border-radius:4px;box-shadow:0 4px 12px rgba(0,0,0,.5);display:block;margin-bottom:8px';
            wrap.appendChild(img);
          });
          wrap.style.display = 'block';
          showAdminMsg(gfxMsg, '✅ Preview ready · ' + pages.length + ' page' + (pages.length === 1 ? '' : 's'), 'success');
        } catch (e) {
          showAdminMsg(gfxMsg, 'Error: ' + (e && e.message || e), 'error');
        }
      });
    }

    if (gfxDownloadBtn && !gfxDownloadBtn._bound) {
      gfxDownloadBtn._bound = true;
      gfxDownloadBtn.addEventListener('click', async () => {
        const opts = _gfxReadOpts();
        showAdminMsg(gfxMsg, 'Generating PNG…', 'success');
        try {
          const pages = await _gfxRenderAllPages(opts);
          if (!pages.length) { showAdminMsg(gfxMsg, 'No players for that filter — check your board', 'error'); return; }
          const slug = opts.pos.toLowerCase().replace(/_/g, '-');
          let downloaded = 0;
          for (let i = 0; i < pages.length; i++) {
            const p = pages[i];
            const blob = await new Promise(res => p.canvas.toBlob(res, 'image/png'));
            if (!blob) continue;
            const a = document.createElement('a');
            a.href = URL.createObjectURL(blob);
            const suffix = pages.length > 1
              ? '-pg' + (i + 1) + '-of-' + pages.length + '-rk' + (p.range[0] + 1) + '-' + p.range[1]
              : '-top' + opts.count;
            a.download = 'mff-rankings-' + slug + suffix + '.png';
            document.body.appendChild(a);
            a.click();
            a.remove();
            setTimeout(((href) => () => URL.revokeObjectURL(href))(a.href), 4000);
            downloaded++;
            // Brief pause between downloads so browsers don't block them
            if (i < pages.length - 1) await new Promise(r => setTimeout(r, 350));
          }
          showAdminMsg(gfxMsg, '✅ Downloaded ' + downloaded + ' image' + (downloaded === 1 ? '' : 's'), 'success');
        } catch (e) {
          showAdminMsg(gfxMsg, 'Error: ' + (e && e.message || e), 'error');
        }
      });
    }

    // ===== Drafted Team Graphic Generator =====
    const tgfxSrcSel      = document.getElementById('adminTgfxSource');
    const tgfxTeamSel     = document.getElementById('adminTgfxTeam');
    const tgfxTitleInput  = document.getElementById('adminTgfxTitle');
    const tgfxThemeSel    = document.getElementById('adminTgfxTheme');
    const tgfxAccentInp   = document.getElementById('adminTgfxAccent');
    const tgfxHighlightInp= document.getElementById('adminTgfxHighlight');
    const tgfxPreviewBtn  = document.getElementById('adminTgfxPreviewBtn');
    const tgfxDownloadBtn = document.getElementById('adminTgfxDownloadBtn');
    const tgfxMsg         = document.getElementById('adminTgfxMsg');
    const tgfxPreviewWrap = document.getElementById('adminTgfxPreviewWrap');

    function _tgfxFormatPick(overall, leagueSize) {
      // Format like "1.05" given an overall pick number and league size (default 12)
      const n = parseInt(overall, 10);
      if (!isFinite(n) || n < 1) return String(overall || '');
      const sz = leagueSize || 12;
      const round = Math.ceil(n / sz);
      const slot = ((n - 1) % sz) + 1;
      return round + '.' + String(slot).padStart(2, '0');
    }

    function _tgfxLookupPlayer(name) {
      if (!name || typeof D === 'undefined') return null;
      // Direct match first
      let p = D.find(d => d && d.n === name);
      if (p) return p;
      // Loose match (lowercase, strip punctuation)
      const norm = String(name).toLowerCase().replace(/[^a-z0-9]/g, '');
      p = D.find(d => d && d.n && String(d.n).toLowerCase().replace(/[^a-z0-9]/g, '') === norm);
      return p || null;
    }

    function _tgfxPopulateTeams() {
      const src = tgfxSrcSel.value;
      tgfxTeamSel.innerHTML = '';

      if (src === 'myteams') {
        const sources = [];
        // Saved leagues (cloud)
        if (window._mtSavedLeagues && Object.keys(window._mtSavedLeagues).length) {
          Object.entries(window._mtSavedLeagues).forEach(([leagueId, league]) => {
            if (!league || !Array.isArray(league.teams)) return;
            league.teams.forEach((team, idx) => {
              const isMine = team.isMyTeam || (league.myTeamIdx === idx);
              if (!isMine && !team.players) return; // skip empty entries
              sources.push({
                id: 'saved|' + leagueId + '|' + (team.id || idx),
                label: (league.name || 'League') + ' — ' + (team.owner || ('Team ' + (idx + 1))) + (isMine ? ' ⭐' : ''),
                _isMine: isMine
              });
            });
          });
        }
        // Currently-loaded league (might not be saved yet)
        if (window._mtTeams && window._mtTeams.length) {
          const lname = (window._mtLeague && window._mtLeague.name) || 'Current League';
          window._mtTeams.forEach((team, idx) => {
            sources.push({
              id: 'live|' + idx,
              label: '[LIVE] ' + lname + ' — ' + (team.owner || ('Team ' + (idx + 1))) + (team.isMyTeam ? ' ⭐' : '')
            });
          });
        }
        if (!sources.length) {
          tgfxTeamSel.innerHTML = '<option value="">No teams found — import a Sleeper league on the My Teams page first</option>';
          return;
        }
        // Sort: starred first, then by label
        sources.sort((a, b) => (b._isMine ? 1 : 0) - (a._isMine ? 1 : 0) || a.label.localeCompare(b.label));
        sources.forEach(t => {
          const opt = document.createElement('option');
          opt.value = t.id;
          opt.textContent = t.label;
          tgfxTeamSel.appendChild(opt);
        });
      } else if (src === 'underdog') {
        const drafts = (window._udPortfolio && window._udPortfolio.drafts) || {};
        const list = Object.values(drafts);
        if (!list.length) {
          tgfxTeamSel.innerHTML = '<option value="">No Underdog drafts found — sync via the Underdog extension first</option>';
          return;
        }
        list.sort((a, b) => String(b.date || '').localeCompare(String(a.date || '')));
        list.forEach(d => {
          const opt = document.createElement('option');
          opt.value = d.id;
          const date = d.date ? (' · ' + d.date) : '';
          // Show custom team name if user renamed on Underdog, else just contest name
          const baseName = d.tournament || 'Draft';
          const label = d.teamName ? (baseName + ' — ' + d.teamName) : baseName;
          opt.textContent = label + date;
          tgfxTeamSel.appendChild(opt);
        });
      }
    }

    function _tgfxGetTeamData() {
      const src = tgfxSrcSel.value;
      const teamId = tgfxTeamSel.value;
      if (!teamId) return null;

      if (src === 'myteams') {
        let team = null, league = null, leagueSize = 12;
        if (teamId.startsWith('saved|')) {
          const [_, leagueId, sleeperTeamId] = teamId.split('|');
          league = (window._mtSavedLeagues || {})[leagueId];
          if (!league) return null;
          team = (league.teams || []).find((t, i) => String(t.id) === sleeperTeamId || String(i) === sleeperTeamId);
          leagueSize = (league.teams || []).length || 12;
        } else if (teamId.startsWith('live|')) {
          const idx = parseInt(teamId.split('|')[1], 10);
          team = (window._mtTeams || [])[idx];
          league = window._mtLeague || {};
          leagueSize = (window._mtTeams || []).length || 12;
        }
        if (!team) return null;

        const playerNames = team.players || [];
        // Order roster by current ADP (best-on-team first)
        const enriched = playerNames.map((name, i) => {
          const player = _tgfxLookupPlayer(name);
          return {
            origIdx: i,
            name: name,
            pos: player ? player.s : '',
            team: player ? player.t : '',
            adp: (player && (player.a != null ? player.a : player.udA)) || 9999
          };
        }).sort((a, b) => a.adp - b.adp);

        return {
          title: league.name || 'My Team',
          subtitle: team.owner || '',
          leagueSize: leagueSize,
          source: 'sleeper',
          picks: enriched.map((p, i) => ({
            pick: i + 1,
            label: String(i + 1) + '.',
            name: p.name,
            pos: p.pos,
            team: p.team
          }))
        };
      } else if (src === 'underdog') {
        const draft = ((window._udPortfolio || {}).drafts || {})[teamId];
        if (!draft || !Array.isArray(draft.picks) || !draft.picks.length) return null;
        const sz = draft.size || 12;
        const picks = draft.picks.slice().sort((a, b) => (a.pick || 0) - (b.pick || 0)).map(p => {
          const player = _tgfxLookupPlayer(p.name);
          return {
            pick: p.pick,
            label: _tgfxFormatPick(p.pick, sz),
            name: p.name,
            pos: p.pos || (player ? player.s : ''),
            team: player ? player.t : (p.team || '')   // prefer full team name from D[]
          };
        });
        return {
          title: draft.tournament || 'Underdog Draft',
          subtitle: draft.date || '',
          leagueSize: sz,
          source: 'underdog',
          picks: picks
        };
      }
      return null;
    }

    function _tgfxBuildNode(opts) {
      const { teamData, title, accent, highlight, theme } = opts;
      if (!teamData || !teamData.picks.length) return null;

      const themes = {
        purple: 'linear-gradient(135deg,#4c1d95 0%,#7c3aed 55%,#a78bfa 100%)',
        blue:   'linear-gradient(135deg,#1e3a8a 0%,#2563eb 55%,#60a5fa 100%)',
        red:    'linear-gradient(135deg,#7f1d1d 0%,#dc2626 55%,#fb7185 100%)',
        green:  'linear-gradient(135deg,#14532d 0%,#16a34a 55%,#4ade80 100%)',
        orange: 'linear-gradient(135deg,#7c2d12 0%,#ea580c 55%,#fb923c 100%)',
        dark:   'linear-gradient(135deg,#0f172a 0%,#1e293b 55%,#475569 100%)'
      };
      const headerBg = themes[theme] || themes.purple;
      const _highlight = highlight || '#FFD700';
      const teamLabel = (teamData.title || 'TEAM').toUpperCase();

      const rawTitle = title || 'MY|[TEAM]|DRAFT';
      const titleLines = rawTitle.split('|').map(line =>
        line.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
            .replace(/\[TEAM\]/g, '<span style="color:' + _highlight + '">' + teamLabel + '</span>')
      );
      const titleHtml = titleLines.map(line => '<div>' + line + '</div>').join('');

      // Layout: 1 col for ≤14 picks, 2 cols above
      const picks = teamData.picks;
      const cols = picks.length <= 14 ? 1 : 2;
      const rowsPerCol = Math.ceil(picks.length / cols);
      const colArrays = [];
      for (let c = 0; c < cols; c++) {
        colArrays.push(picks.slice(c * rowsPerCol, (c + 1) * rowsPerCol));
      }

      // Row sizing scales with pick count
      const _scale = picks.length <= 14 ? 1.0 : picks.length <= 20 ? 0.85 : 0.7;
      const RZ = (n) => Math.round(n * _scale);

      function rowHtml(p) {
        const player = _tgfxLookupPlayer(p.name);
        const teamName = p.team || (player && player.t);
        const tc = teamName ? _gfxTeamColor(teamName) : { bg: '#1f2937', fg: '#FFFFFF' };
        const logoId = (typeof TEAM_LOGO_IDS !== 'undefined' && teamName) ? TEAM_LOGO_IDS[teamName] : null;
        const logoUrl = logoId ? ('https://a.espncdn.com/i/teamlogos/nfl/500/' + logoId + '.png') : '';
        const logoSize = RZ(70);
        const logoHtml = logoUrl
          ? '<div style="width:' + logoSize + 'px;height:' + logoSize + 'px;display:flex;align-items:center;justify-content:center;flex:0 0 ' + logoSize + 'px;background:rgba(255,255,255,.95);border-radius:50%;padding:' + RZ(6) + 'px"><img src="' + logoUrl + '" alt="" crossorigin="anonymous" style="max-width:100%;max-height:100%;object-fit:contain"/></div>'
          : '<div style="width:' + logoSize + 'px;height:' + logoSize + 'px;background:rgba(255,255,255,.15);border-radius:50%;flex:0 0 ' + logoSize + 'px;display:flex;align-items:center;justify-content:center;color:#fff;font-size:' + RZ(20) + 'px">?</div>';

        const safeName = (p.name || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
        const posPill = p.pos
          ? '<div style="background:rgba(0,0,0,.35);color:' + tc.fg + ';font-family:\'Bebas Neue\',Impact,Arial,sans-serif;font-size:' + RZ(28) + 'px;padding:' + RZ(3) + 'px ' + RZ(10) + 'px;border-radius:' + RZ(5) + 'px;letter-spacing:1px;flex:0 0 auto">' + p.pos + '</div>'
          : '';

        return '<div style="display:flex;align-items:center;gap:' + RZ(16) + 'px;padding:' + RZ(14) + 'px ' + RZ(20) + 'px;background:' + tc.bg + ';border-radius:' + RZ(10) + 'px;box-shadow:inset 0 0 0 2px rgba(255,255,255,.07)">' +
          '<div style="font-family:\'Bebas Neue\',Impact,Arial,sans-serif;font-size:' + RZ(38) + 'px;color:' + _highlight + ';min-width:' + RZ(80) + 'px;text-align:right;font-weight:700;line-height:1;letter-spacing:.5px;text-shadow:0 1px 2px rgba(0,0,0,.5)">' + p.label + '</div>' +
          logoHtml +
          '<div style="font-family:\'Bebas Neue\',Impact,Arial,sans-serif;font-size:' + RZ(38) + 'px;color:' + tc.fg + ';letter-spacing:.6px;line-height:1;flex:1 1 0;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + safeName.toUpperCase() + '</div>' +
          posPill +
          '</div>';
      }

      const wrap = document.createElement('div');
      wrap.style.cssText = 'width:1080px;background:#000;font-family:"Bebas Neue",Impact,Arial,sans-serif;color:#fff;position:relative;overflow:hidden;box-sizing:border-box';

      const subHtml = teamData.subtitle
        ? '<div style="font-family:\'Bebas Neue\',Impact,Arial,sans-serif;font-size:32px;color:rgba(255,255,255,.85);letter-spacing:3px;margin-top:12px">' + teamData.subtitle.replace(/</g,'&lt;') + '</div>'
        : '';

      // MFF logo in corner (same as rankings)
      const mffLogo =
        '<svg viewBox="-2 -8 46 44" width="56" height="54" style="display:block">' +
          '<rect x="0" y="20" width="8" height="12" rx="1.5" fill="#000" opacity=".35"/>' +
          '<rect x="11" y="14" width="8" height="18" rx="1.5" fill="#000" opacity=".55"/>' +
          '<rect x="22" y="7" width="8" height="25" rx="1.5" fill="#000" opacity=".75"/>' +
          '<rect x="33" y="0" width="8" height="32" rx="1.5" fill="#000" opacity=".95"/>' +
          '<polyline points="4,17 15,11 26,4 37,-3" fill="none" stroke="#000" stroke-width="2" stroke-linecap="round"/>' +
          '<circle cx="37" cy="-3" r="3.5" fill="#000"/>' +
        '</svg>';

      wrap.innerHTML =
        '<div style="background:' + headerBg + ';padding:50px 56px 42px;position:relative;overflow:hidden;box-sizing:border-box">' +
          '<div style="position:absolute;top:0;right:0;width:0;height:0;border-style:solid;border-width:0 150px 150px 0;border-color:transparent ' + accent + ' transparent transparent"></div>' +
          '<div style="position:absolute;top:14px;right:14px;display:flex;align-items:center;justify-content:center">' + mffLogo + '</div>' +
          '<div style="font-family:\'Bebas Neue\',Impact,Arial,sans-serif;font-size:120px;line-height:.92;color:#fff;letter-spacing:3px;font-weight:900;text-transform:uppercase;padding-right:160px">' + titleHtml + '</div>' +
          subHtml +
        '</div>' +
        '<div style="background:#000;padding:28px 36px;display:grid;grid-template-columns:repeat(' + cols + ',1fr);gap:18px;box-sizing:border-box">' +
          colArrays.map(colPicks =>
            '<div style="display:flex;flex-direction:column;gap:10px">' +
              colPicks.map(p => rowHtml(p)).join('') +
            '</div>'
          ).join('') +
        '</div>' +
        '<div style="background:#000;padding:16px 40px 22px;text-align:center;font-family:\'Bebas Neue\',Impact,Arial,sans-serif;font-size:24px;color:rgba(255,255,255,.45);letter-spacing:6px;box-sizing:border-box">MYFANTASYFOOTBALL.CO</div>';

      return wrap;
    }

    async function _tgfxRender() {
      await _gfxLoadHtml2Canvas();
      const teamData = _tgfxGetTeamData();
      if (!teamData) return null;
      const node = _tgfxBuildNode({
        teamData: teamData,
        title: tgfxTitleInput.value,
        accent: tgfxAccentInp.value || '#facc15',
        highlight: tgfxHighlightInp.value || '#FFD700',
        theme: tgfxThemeSel.value || 'purple'
      });
      if (!node) return null;
      const holder = document.createElement('div');
      holder.style.cssText = 'position:fixed;left:-10000px;top:0;z-index:-1;pointer-events:none';
      holder.appendChild(node);
      document.body.appendChild(holder);
      try {
        const imgs = node.querySelectorAll('img');
        await Promise.all(Array.from(imgs).map(img => {
          if (img.complete && img.naturalWidth > 0) return Promise.resolve();
          return new Promise(res => {
            const t = setTimeout(res, 4000);
            img.onload = () => { clearTimeout(t); res(); };
            img.onerror = () => { clearTimeout(t); res(); };
          });
        }));
        const canvas = await window.html2canvas(node, {
          backgroundColor: '#000',
          scale: 1,
          useCORS: true,
          allowTaint: false,
          logging: false,
          width: 1080,
          height: node.offsetHeight,
          windowWidth: 1080,
          windowHeight: node.offsetHeight
        });
        return canvas;
      } finally {
        holder.remove();
      }
    }

    if (tgfxSrcSel && !tgfxSrcSel._bound) {
      tgfxSrcSel._bound = true;
      tgfxSrcSel.addEventListener('change', _tgfxPopulateTeams);
      _tgfxPopulateTeams();
    }

    if (tgfxPreviewBtn && !tgfxPreviewBtn._bound) {
      tgfxPreviewBtn._bound = true;
      tgfxPreviewBtn.addEventListener('click', async () => {
        if (!tgfxTeamSel.value) { showAdminMsg(tgfxMsg, 'Pick a team first', 'error'); return; }
        showAdminMsg(tgfxMsg, 'Generating preview…', 'success');
        try {
          const canvas = await _tgfxRender();
          if (!canvas) { showAdminMsg(tgfxMsg, 'Could not build team graphic — no picks found', 'error'); return; }
          tgfxPreviewWrap.innerHTML = '';
          const img = new Image();
          img.src = canvas.toDataURL('image/png');
          img.style.cssText = 'max-width:100%;height:auto;border-radius:4px;box-shadow:0 4px 12px rgba(0,0,0,.5)';
          tgfxPreviewWrap.appendChild(img);
          tgfxPreviewWrap.style.display = 'block';
          showAdminMsg(tgfxMsg, '✅ Preview ready', 'success');
        } catch (e) {
          showAdminMsg(tgfxMsg, 'Error: ' + (e && e.message || e), 'error');
        }
      });
    }

    if (tgfxDownloadBtn && !tgfxDownloadBtn._bound) {
      tgfxDownloadBtn._bound = true;
      tgfxDownloadBtn.addEventListener('click', async () => {
        if (!tgfxTeamSel.value) { showAdminMsg(tgfxMsg, 'Pick a team first', 'error'); return; }
        showAdminMsg(tgfxMsg, 'Generating PNG…', 'success');
        try {
          const canvas = await _tgfxRender();
          if (!canvas) { showAdminMsg(tgfxMsg, 'Could not build team graphic — no picks found', 'error'); return; }
          const td = _tgfxGetTeamData();
          const slug = (td && td.title ? td.title : 'team').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
          canvas.toBlob(blob => {
            if (!blob) { showAdminMsg(tgfxMsg, 'PNG encode failed', 'error'); return; }
            const a = document.createElement('a');
            a.href = URL.createObjectURL(blob);
            a.download = 'mff-team-' + slug + '.png';
            document.body.appendChild(a);
            a.click();
            a.remove();
            setTimeout(() => URL.revokeObjectURL(a.href), 4000);
            showAdminMsg(tgfxMsg, '✅ Downloaded ' + a.download, 'success');
          }, 'image/png');
        } catch (e) {
          showAdminMsg(tgfxMsg, 'Error: ' + (e && e.message || e), 'error');
        }
      });
    }

    // ===== Exposure Graphic Generator (Underdog) =====
    const expModeSel       = document.getElementById('adminExpgfxMode');
    const expPosSel        = document.getElementById('adminExpgfxPos');
    const expCountSel      = document.getElementById('adminExpgfxCount');
    const expMinDraftsSel  = document.getElementById('adminExpgfxMinDrafts');
    const expTitleInput    = document.getElementById('adminExpgfxTitle');
    const expThemeSel      = document.getElementById('adminExpgfxTheme');
    const expAccentInp     = document.getElementById('adminExpgfxAccent');
    const expHighlightInp  = document.getElementById('adminExpgfxHighlight');
    const expPreviewBtn    = document.getElementById('adminExpgfxPreviewBtn');
    const expDownloadBtn   = document.getElementById('adminExpgfxDownloadBtn');
    const expMsg           = document.getElementById('adminExpgfxMsg');
    const expPreviewWrap   = document.getElementById('adminExpgfxPreviewWrap');

    // Auto-update default title when mode/pos changes (only if user hasn't customized)
    function _expDefaultTitle() {
      const mode = expModeSel.value;
      return (mode === 'least' ? 'LEAST' : 'MOST') + '|DRAFTED|[POS]';
    }
    let _expTitleCustomized = false;
    if (expTitleInput) {
      expTitleInput.addEventListener('input', () => { _expTitleCustomized = true; });
    }
    function _expSyncTitle() {
      if (!_expTitleCustomized && expTitleInput) {
        expTitleInput.value = _expDefaultTitle();
      }
    }
    if (expModeSel) expModeSel.addEventListener('change', _expSyncTitle);

    function _expBuildList() {
      const portfolio = window._udPortfolio || {};
      const playersMap = portfolio.players || {};
      const numDrafts = portfolio.numDrafts || Object.keys(portfolio.drafts || {}).length || 0;
      if (!Object.keys(playersMap).length || !numDrafts) return { items: [], numDrafts: 0 };

      const mode    = expModeSel.value;          // 'most' | 'least'
      const pos     = expPosSel.value;           // 'ALL' | 'QB' | ...
      const count   = parseInt(expCountSel.value, 10) || 12;
      const minDr   = parseInt(expMinDraftsSel.value, 10) || 1;

      // Normalize entries; recompute exposure defensively in case it's stale
      const items = Object.entries(playersMap).map(([name, p]) => {
        const draftCount = (p.draftIds && (p.draftIds.size != null ? p.draftIds.size : (Array.isArray(p.draftIds) ? p.draftIds.length : 0))) || p.count || 0;
        const exposure = (p.exposure != null) ? p.exposure : (numDrafts > 0 ? draftCount / numDrafts : 0);
        // Lookup full NFL team name + position from D[] (more reliable than UD's short codes)
        const dPlayer = _tgfxLookupPlayer(name);
        return {
          name: name,
          pos: (dPlayer && dPlayer.s) || p.pos || '',
          team: (dPlayer && dPlayer.t) || p.team || '',
          exposure: exposure,
          draftCount: draftCount
        };
      }).filter(item => {
        if (item.draftCount < minDr) return false;
        if (pos !== 'ALL' && item.pos !== pos) return false;
        return true;
      });

      items.sort((a, b) => mode === 'least'
        ? (a.exposure - b.exposure) || (a.draftCount - b.draftCount)
        : (b.exposure - a.exposure) || (b.draftCount - a.draftCount));

      return { items: items.slice(0, count), numDrafts: numDrafts, totalAvailable: items.length };
    }

    function _expBuildNode(opts) {
      const { items, numDrafts, totalAvailable, title, accent, highlight, theme, mode, pos } = opts;
      if (!items || !items.length) return null;

      const themes = {
        purple: 'linear-gradient(135deg,#4c1d95 0%,#7c3aed 55%,#a78bfa 100%)',
        blue:   'linear-gradient(135deg,#1e3a8a 0%,#2563eb 55%,#60a5fa 100%)',
        red:    'linear-gradient(135deg,#7f1d1d 0%,#dc2626 55%,#fb7185 100%)',
        green:  'linear-gradient(135deg,#14532d 0%,#16a34a 55%,#4ade80 100%)',
        orange: 'linear-gradient(135deg,#7c2d12 0%,#ea580c 55%,#fb923c 100%)',
        dark:   'linear-gradient(135deg,#0f172a 0%,#1e293b 55%,#475569 100%)'
      };
      const headerBg = themes[theme] || themes.purple;
      const _highlight = highlight || '#FFD700';
      const posLabel = (pos === 'ALL') ? 'OVERALL' : pos;

      const rawTitle = title || _expDefaultTitle();
      const titleLines = rawTitle.split('|').map(line =>
        line.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
            .replace(/\[POS\]/g, '<span style="color:' + _highlight + '">' + posLabel + '</span>')
      );
      const titleHtml = titleLines.map(line => '<div>' + line + '</div>').join('');

      // Layout: same column rules as rankings graphic
      const cols = items.length <= 12 ? 1
                 : items.length <= 24 ? 2
                 : items.length <= 36 ? 3
                 : 4;
      const rowsPerCol = Math.ceil(items.length / cols);
      const colArrays = [];
      for (let c = 0; c < cols; c++) {
        colArrays.push(items.slice(c * rowsPerCol, (c + 1) * rowsPerCol));
      }

      const _scale = items.length <= 12 ? 1.0 : items.length <= 24 ? 0.78 : 0.62;
      const RZ = (n) => Math.round(n * _scale);

      function rowHtml(item, rank) {
        const tc = item.team ? _gfxTeamColor(item.team) : { bg: '#1f2937', fg: '#FFFFFF' };
        const logoId = (typeof TEAM_LOGO_IDS !== 'undefined' && item.team) ? TEAM_LOGO_IDS[item.team] : null;
        const logoUrl = logoId ? ('https://a.espncdn.com/i/teamlogos/nfl/500/' + logoId + '.png') : '';
        const logoSize = RZ(72);
        const logoHtml = logoUrl
          ? '<div style="width:' + logoSize + 'px;height:' + logoSize + 'px;display:flex;align-items:center;justify-content:center;flex:0 0 ' + logoSize + 'px;background:rgba(255,255,255,.95);border-radius:50%;padding:' + RZ(6) + 'px"><img src="' + logoUrl + '" alt="" crossorigin="anonymous" style="max-width:100%;max-height:100%;object-fit:contain"/></div>'
          : '<div style="width:' + logoSize + 'px;height:' + logoSize + 'px;background:rgba(255,255,255,.15);border-radius:50%;flex:0 0 ' + logoSize + 'px;display:flex;align-items:center;justify-content:center;color:#fff;font-size:' + RZ(20) + 'px">?</div>';
        const safeName = (item.name || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
        const pct = Math.round(item.exposure * 1000) / 10; // one decimal
        const pctText = (pct % 1 === 0 ? pct.toFixed(0) : pct.toFixed(1)) + '%';
        return '<div style="display:flex;align-items:center;gap:' + RZ(18) + 'px;padding:' + RZ(14) + 'px ' + RZ(20) + 'px;background:' + tc.bg + ';border-radius:' + RZ(10) + 'px;box-shadow:inset 0 0 0 2px rgba(255,255,255,.07)">' +
          '<div style="font-family:\'Bebas Neue\',Impact,Arial,sans-serif;font-size:' + RZ(46) + 'px;color:' + tc.fg + ';min-width:' + RZ(60) + 'px;text-align:right;font-weight:700;line-height:1">' + rank + '.</div>' +
          logoHtml +
          '<div style="font-family:\'Bebas Neue\',Impact,Arial,sans-serif;font-size:' + RZ(42) + 'px;color:' + tc.fg + ';letter-spacing:.6px;line-height:1;flex:1 1 0;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + safeName.toUpperCase() + '</div>' +
          '<div style="font-family:\'Bebas Neue\',Impact,Arial,sans-serif;font-size:' + RZ(40) + 'px;color:' + _highlight + ';letter-spacing:.5px;line-height:1;padding-left:' + RZ(14) + 'px;flex:0 0 auto;text-shadow:0 1px 2px rgba(0,0,0,.5)">' + pctText + '</div>' +
          '</div>';
      }

      const wrap = document.createElement('div');
      wrap.style.cssText = 'width:1080px;background:#000;font-family:"Bebas Neue",Impact,Arial,sans-serif;color:#fff;position:relative;overflow:hidden;box-sizing:border-box';

      const subText = numDrafts + ' drafts · ' + items.length + ' shown' + (totalAvailable && totalAvailable > items.length ? ' / ' + totalAvailable + ' eligible' : '');
      const subHtml = '<div style="font-family:\'Bebas Neue\',Impact,Arial,sans-serif;font-size:30px;color:rgba(255,255,255,.85);letter-spacing:3px;margin-top:14px">' + subText + '</div>';

      const mffLogo =
        '<svg viewBox="-2 -8 46 44" width="56" height="54" style="display:block">' +
          '<rect x="0" y="20" width="8" height="12" rx="1.5" fill="#000" opacity=".35"/>' +
          '<rect x="11" y="14" width="8" height="18" rx="1.5" fill="#000" opacity=".55"/>' +
          '<rect x="22" y="7" width="8" height="25" rx="1.5" fill="#000" opacity=".75"/>' +
          '<rect x="33" y="0" width="8" height="32" rx="1.5" fill="#000" opacity=".95"/>' +
          '<polyline points="4,17 15,11 26,4 37,-3" fill="none" stroke="#000" stroke-width="2" stroke-linecap="round"/>' +
          '<circle cx="37" cy="-3" r="3.5" fill="#000"/>' +
        '</svg>';

      wrap.innerHTML =
        '<div style="background:' + headerBg + ';padding:50px 56px 42px;position:relative;overflow:hidden;box-sizing:border-box">' +
          '<div style="position:absolute;top:0;right:0;width:0;height:0;border-style:solid;border-width:0 150px 150px 0;border-color:transparent ' + accent + ' transparent transparent"></div>' +
          '<div style="position:absolute;top:14px;right:14px;display:flex;align-items:center;justify-content:center">' + mffLogo + '</div>' +
          '<div style="font-family:\'Bebas Neue\',Impact,Arial,sans-serif;font-size:130px;line-height:.92;color:#fff;letter-spacing:3px;font-weight:900;text-transform:uppercase;padding-right:160px">' + titleHtml + '</div>' +
          subHtml +
        '</div>' +
        '<div style="background:#000;padding:28px 36px;display:grid;grid-template-columns:repeat(' + cols + ',1fr);gap:18px;box-sizing:border-box">' +
          colArrays.map((colItems, ci) => {
            const startIdx = ci * rowsPerCol;
            return '<div style="display:flex;flex-direction:column;gap:10px">' +
              colItems.map((it, ri) => rowHtml(it, startIdx + ri + 1)).join('') +
            '</div>';
          }).join('') +
        '</div>' +
        '<div style="background:#000;padding:16px 40px 22px;text-align:center;font-family:\'Bebas Neue\',Impact,Arial,sans-serif;font-size:24px;color:rgba(255,255,255,.45);letter-spacing:6px;box-sizing:border-box">MYFANTASYFOOTBALL.CO</div>';

      return wrap;
    }

    async function _expRender() {
      await _gfxLoadHtml2Canvas();
      const data = _expBuildList();
      if (!data.items.length) return null;
      const node = _expBuildNode({
        items: data.items,
        numDrafts: data.numDrafts,
        totalAvailable: data.totalAvailable,
        title: expTitleInput.value,
        accent: expAccentInp.value || '#facc15',
        highlight: expHighlightInp.value || '#FFD700',
        theme: expThemeSel.value || 'purple',
        mode: expModeSel.value,
        pos: expPosSel.value
      });
      if (!node) return null;
      const holder = document.createElement('div');
      holder.style.cssText = 'position:fixed;left:-10000px;top:0;z-index:-1;pointer-events:none';
      holder.appendChild(node);
      document.body.appendChild(holder);
      try {
        const imgs = node.querySelectorAll('img');
        await Promise.all(Array.from(imgs).map(img => {
          if (img.complete && img.naturalWidth > 0) return Promise.resolve();
          return new Promise(res => {
            const t = setTimeout(res, 4000);
            img.onload = () => { clearTimeout(t); res(); };
            img.onerror = () => { clearTimeout(t); res(); };
          });
        }));
        const canvas = await window.html2canvas(node, {
          backgroundColor: '#000',
          scale: 1,
          useCORS: true,
          allowTaint: false,
          logging: false,
          width: 1080,
          height: node.offsetHeight,
          windowWidth: 1080,
          windowHeight: node.offsetHeight
        });
        return canvas;
      } finally {
        holder.remove();
      }
    }

    if (expPreviewBtn && !expPreviewBtn._bound) {
      expPreviewBtn._bound = true;
      expPreviewBtn.addEventListener('click', async () => {
        const portfolio = window._udPortfolio || {};
        if (!portfolio.numDrafts && !Object.keys(portfolio.drafts || {}).length) {
          showAdminMsg(expMsg, 'No Underdog portfolio loaded — sync via the extension first', 'error');
          return;
        }
        showAdminMsg(expMsg, 'Generating preview…', 'success');
        try {
          const canvas = await _expRender();
          if (!canvas) { showAdminMsg(expMsg, 'No players match those filters', 'error'); return; }
          expPreviewWrap.innerHTML = '';
          const img = new Image();
          img.src = canvas.toDataURL('image/png');
          img.style.cssText = 'max-width:100%;height:auto;border-radius:4px;box-shadow:0 4px 12px rgba(0,0,0,.5)';
          expPreviewWrap.appendChild(img);
          expPreviewWrap.style.display = 'block';
          showAdminMsg(expMsg, '✅ Preview ready', 'success');
        } catch (e) {
          showAdminMsg(expMsg, 'Error: ' + (e && e.message || e), 'error');
        }
      });
    }

    if (expDownloadBtn && !expDownloadBtn._bound) {
      expDownloadBtn._bound = true;
      expDownloadBtn.addEventListener('click', async () => {
        const portfolio = window._udPortfolio || {};
        if (!portfolio.numDrafts && !Object.keys(portfolio.drafts || {}).length) {
          showAdminMsg(expMsg, 'No Underdog portfolio loaded — sync via the extension first', 'error');
          return;
        }
        showAdminMsg(expMsg, 'Generating PNG…', 'success');
        try {
          const canvas = await _expRender();
          if (!canvas) { showAdminMsg(expMsg, 'No players match those filters', 'error'); return; }
          const slug = expModeSel.value + '-drafted-' + expPosSel.value.toLowerCase() + '-top' + expCountSel.value;
          canvas.toBlob(blob => {
            if (!blob) { showAdminMsg(expMsg, 'PNG encode failed', 'error'); return; }
            const a = document.createElement('a');
            a.href = URL.createObjectURL(blob);
            a.download = 'mff-exposure-' + slug + '.png';
            document.body.appendChild(a);
            a.click();
            a.remove();
            setTimeout(() => URL.revokeObjectURL(a.href), 4000);
            showAdminMsg(expMsg, '✅ Downloaded ' + a.download, 'success');
          }, 'image/png');
        } catch (e) {
          showAdminMsg(expMsg, 'Error: ' + (e && e.message || e), 'error');
        }
      });
    }
  }

  // Load gifted premium on auth
  function loadGiftedPremium() {
    const db = (typeof firebase !== 'undefined' && firebase.firestore) ? firebase.firestore() : null;
    const user = (typeof firebase !== 'undefined' && firebase.auth) ? firebase.auth().currentUser : null;
    if (!db || !user || !user.email) return;
    const myUid = user.uid;
    const docId = user.email.toLowerCase().replace(/[^a-z0-9]/g, '_');
    db.collection('gifted_premium').doc(docId).get().then(doc => {
      // Bail if user switched accounts since query started
      const stillCurrent = (typeof firebase !== 'undefined' && firebase.auth && firebase.auth().currentUser);
      if (!stillCurrent || stillCurrent.uid !== myUid) return;
      // Wipe stale localStorage from a prior user before applying
      const existing = JSON.parse(localStorage.getItem('jb_premium') || 'null');
      if (existing && existing.uid && existing.uid !== myUid) {
        localStorage.removeItem('jb_premium');
      }
      if (doc.exists) {
        const data = doc.data();
        if (data.expires && data.expires > Date.now()) {
          const refreshed = JSON.parse(localStorage.getItem('jb_premium') || 'null');
          if (!refreshed || (refreshed.uid === myUid && data.expires > (refreshed.expires || 0)) || !refreshed.uid) {
            localStorage.setItem('jb_premium', JSON.stringify({
              plan: 'Gifted: ' + (data.label || 'Admin Grant'),
              activated: Date.now(),
              expires: data.expires,
              gifted: true,
              uid: myUid
            }));
            console.log('[Premium] Gifted premium applied — expires', new Date(data.expires).toLocaleDateString());
            if (typeof window.checkPremiumStatus === 'function') window.checkPremiumStatus();
          }
        }
      }
    }).catch(e => console.warn('[Premium] gifted load error:', e));
  }
  window._loadGiftedPremium = loadGiftedPremium;

  // Load Stripe-purchased premium on auth
  // Reads users/{uid}.premium (written by the stripeWebhook Cloud Function)
  // and mirrors active premium into localStorage so checkPremiumStatus() unlocks features.
  // Helper: clear any stripe/gifted localStorage premium that doesn't belong
  // to the currently signed-in user, so account switches don't carry premium.
  function _clearStaleStripePremium(reason) {
    const existing = JSON.parse(localStorage.getItem('jb_premium') || 'null');
    // Only clear stripe-sourced entries here. Gifted premium has its own
    // Firestore source (`gifted_premium`) and must NOT be wiped just
    // because the user has no active Stripe sub.
    if (existing && existing.source === 'stripe') {
      localStorage.removeItem('jb_premium');
      console.log('[Premium] Cleared stale localStorage premium (' + reason + ')');
      if (typeof window.checkPremiumStatus === 'function') window.checkPremiumStatus();
    }
  }

  function loadStripePremium() {
    const db = (typeof firebase !== 'undefined' && firebase.firestore) ? firebase.firestore() : null;
    const user = (typeof firebase !== 'undefined' && firebase.auth) ? firebase.auth().currentUser : null;
    if (!db || !user) return;
    const myUid = user.uid;
    db.collection('users').doc(myUid).get().then(doc => {
      // Bail if the user has switched accounts since this query started
      const stillCurrent = (typeof firebase !== 'undefined' && firebase.auth && firebase.auth().currentUser);
      if (!stillCurrent || stillCurrent.uid !== myUid) return;
      const data = doc.exists ? (doc.data() || {}) : {};
      const prem = data.premium;
      const expires = (prem && prem.currentPeriodEnd) || 0;
      const isActive = !!prem && (prem.status === 'active' || prem.status === 'trialing') && expires > Date.now();
      // Tag localStorage with this user's uid so we can detect stale entries on the next sign-in
      const existing = JSON.parse(localStorage.getItem('jb_premium') || 'null');
      const existingForOtherUser = existing && existing.source === 'stripe' && existing.uid && existing.uid !== myUid;
      if (existingForOtherUser) {
        // Came from a previous sign-in on this device — wipe before deciding what to do
        localStorage.removeItem('jb_premium');
      }
      if (!isActive) {
        _clearStaleStripePremium('no active stripe premium for this user');
        return;
      }
      const planLabel = prem.plan === 'yearly' ? 'Yearly' : prem.plan === 'monthly' ? 'Monthly' : 'Premium';
      const refreshed = JSON.parse(localStorage.getItem('jb_premium') || 'null');
      const existingExpires = (refreshed && refreshed.uid === myUid && refreshed.expires) || 0;
      if (expires >= existingExpires) {
        localStorage.setItem('jb_premium', JSON.stringify({
          plan: planLabel,
          activated: Date.now(),
          expires: expires,
          source: 'stripe',
          uid: myUid,
          subscriptionId: prem.stripeSubscriptionId || null,
          cancelAtPeriodEnd: !!prem.cancelAtPeriodEnd
        }));
        console.log('[Premium] Stripe premium applied — plan ' + planLabel + ', expires ' + new Date(expires).toLocaleDateString());
        if (typeof window.checkPremiumStatus === 'function') window.checkPremiumStatus();
      }
    }).catch(e => console.warn('[Premium] stripe load error:', e));
  }
  window._loadStripePremium = loadStripePremium;

  // Detect ?premium_success=1 on page load — happens when Stripe redirects back after checkout.
  // The webhook may take a few seconds to fire, so we poll Firestore briefly.
  function handlePremiumSuccess() {
    try {
      const params = new URLSearchParams(window.location.search);
      if (params.get('premium_success') !== '1') return;
      // Clean the URL so refreshing doesn't re-trigger
      const cleanUrl = window.location.pathname + (window.location.hash || '');
      window.history.replaceState({}, '', cleanUrl);
      if (typeof toast === 'function') toast('Payment received — activating premium…');
      // Poll Firestore up to 6 times over ~30 seconds for the webhook to land
      let attempts = 0;
      const maxAttempts = 6;
      const poll = () => {
        attempts++;
        loadStripePremium();
        const data = JSON.parse(localStorage.getItem('jb_premium') || 'null');
        const active = data && data.expires > Date.now() && data.source === 'stripe';
        if (active) {
          if (typeof toast === 'function') toast('Welcome to Premium! Enjoy full access.');
          return;
        }
        if (attempts < maxAttempts) {
          setTimeout(poll, 5000);
        } else {
          if (typeof toast === 'function') toast('Premium not yet active. If charged, refresh in a minute or contact support.');
        }
      };
      setTimeout(poll, 2000); // Initial 2-second delay so the webhook has a chance to write
    } catch(e) { console.warn('[Premium] success handler error:', e); }
  }
  // Expose so it can be triggered from the main auth listener after Firebase initializes
  window._handlePremiumSuccess = handlePremiumSuccess;

  window._initAdminPanel = initAdminPanel;

  // Check for new unlocks whenever fantasy game or elite pull finishes
  const _origLbFG = window._lbUpdateFantasyGame;
  window._lbUpdateFantasyGame = function(score) {
    if (_origLbFG) _origLbFG(score);
    getUnlockedBadges();
  };
  const _origLbFGW = window._lbUpdateFantasyGameWeek;
  window._lbUpdateFantasyGameWeek = function(score) {
    if (_origLbFGW) _origLbFGW(score);
    getUnlockedBadges();
  };
  const _origLbDaily = window._lbUpdateDaily;
  window._lbUpdateDaily = function(won, streak) {
    if (_origLbDaily) _origLbDaily(won, streak);
    getUnlockedBadges();
  };
  const _origLbUnlimited = window._lbUpdateUnlimited;
  window._lbUpdateUnlimited = function(played, correct, streak) {
    if (_origLbUnlimited) _origLbUnlimited(played, correct, streak);
    getUnlockedBadges();
  };
  const _origLbGwDaily = window._lbUpdateGwDaily;
  window._lbUpdateGwDaily = function(won, streak) {
    if (_origLbGwDaily) _origLbGwDaily(won, streak);
    getUnlockedBadges();
  };
  const _origLbGwDaily00s = window._lbUpdateGwDaily00s;
  window._lbUpdateGwDaily00s = function(won, streak) {
    if (_origLbGwDaily00s) _origLbGwDaily00s(won, streak);
    getUnlockedBadges();
  };
  const _origLbGwDaily10s = window._lbUpdateGwDaily10s;
  window._lbUpdateGwDaily10s = function(won, streak) {
    if (_origLbGwDaily10s) _origLbGwDaily10s(won, streak);
    getUnlockedBadges();
  };
  const _origLbGwDaily00s150 = window._lbUpdateGwDaily00s150;
  window._lbUpdateGwDaily00s150 = function(won, streak) {
    if (_origLbGwDaily00s150) _origLbGwDaily00s150(won, streak);
    getUnlockedBadges();
  };
  const _origLbGwDaily10s150 = window._lbUpdateGwDaily10s150;
  window._lbUpdateGwDaily10s150 = function(won, streak) {
    if (_origLbGwDaily10s150) _origLbGwDaily10s150(won, streak);
    getUnlockedBadges();
  };

  // Render badge avatars on page load
  window._renderBadgeAvatars = renderAllAvatars;
  window._renderBadgeGrid = renderBadgeGrid;

  // Initial render after auth
  const _origPopulate = window.populateAccountPage;
  if (typeof populateAccountPage === 'function') {
    const _origPop = populateAccountPage;
    // Override only if not already done
  }
  // Render on load
  setTimeout(() => { renderAllAvatars(); loadGiftedBadges(); checkFounderStatus(); loadGiftedPremium(); loadStripePremium(); initAdminPanel(); }, 500);

  // Hook badge tab to render
  function renderBadgeGridFull() {
    renderBadgeGrid();
  }
  document.querySelectorAll('.acct-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      if (tab.dataset.acctTab === 'badges') setTimeout(renderBadgeGridFull, 50);
      if (tab.dataset.acctTab === 'admin') setTimeout(initAdminPanel, 50);
    });
  });

  window._renderBadgeGrid = renderBadgeGridFull;
  window._loadGiftedBadges = loadGiftedBadges;
  window._checkFounderStatus = checkFounderStatus;
})();

// === CLOUD SYNC — Game data across devices ===
(function(){
  const SYNC_KEYS_MAX = ['ep_streak','ep_longest_streak','epu_played','epu_correct','epu_streak','epu_best_streak','fg_games_played','fg_highscore','fg_highscore_week','md_games_played','gw_daily_streak','gw_daily_00s_streak','gw_daily_10s_streak','gw_daily_00s150_streak','gw_daily_10s150_streak','lastSavedAt'];
  const SYNC_KEYS_STR = ['ep_last_win','jb_active_badge','jb_is_founder','gw_daily_last_win','gw_daily_00s_last_win','gw_daily_10s_last_win','gw_daily_00s150_last_win','gw_daily_10s150_last_win','mff_seen_intro','mff_theme'];
  const SYNC_KEYS_JSON = ['jb_unlocked_badges'];
  // Object-array merge: dedupe by `ts`, sort by ts desc, cap to most recent N.
  // Used for things like md_draft_history where each entry is a {ts, ...} object.
  const SYNC_KEYS_OBJARR = [{ key: 'md_draft_history', dedupeBy: 'ts', cap: 10 }];

  // Helper: get today's Eastern date key parts
  function _syncEasternDate() {
    const now = new Date();
    const d = new Date(now.toLocaleString('en-US', { timeZone: 'America/New_York' }));
    return { y: d.getFullYear(), m: d.getMonth()+1, d: d.getDate() };
  }
  function _syncDailyKeys() {
    const e = _syncEasternDate();
    return {
      ep: `ep_v3_${e.y}_${e.m}_${e.d}`,
      gwC: `gwd_c_${e.y}_${e.m}_${e.d}`,
      gw00s: `gwd_00s_${e.y}_${e.m}_${e.d}`,
      gw10s: `gwd_10s_${e.y}_${e.m}_${e.d}`,
      gw00s150: `gwd_00s150_${e.y}_${e.m}_${e.d}`,
      gw10s150: `gwd_10s150_${e.y}_${e.m}_${e.d}`,
      dateStr: `${e.y}-${e.m}-${e.d}`
    };
  }

  function saveGameDataToCloud() {
    const db = (typeof firebase !== 'undefined' && firebase.firestore) ? firebase.firestore() : null;
    const user = (typeof firebase !== 'undefined' && firebase.auth) ? firebase.auth().currentUser : null;
    if (!db || !user) return;
    const data = {};
    SYNC_KEYS_MAX.forEach(k => { const v = localStorage.getItem(k); if (v !== null) data[k] = parseFloat(v) || 0; });
    SYNC_KEYS_STR.forEach(k => { const v = localStorage.getItem(k); if (v !== null) data[k] = v; });
    SYNC_KEYS_JSON.forEach(k => { const v = localStorage.getItem(k); if (v !== null) data[k] = v; });
    SYNC_KEYS_OBJARR.forEach(spec => { const v = localStorage.getItem(spec.key); if (v !== null) data[spec.key] = v; });
    // Save today's daily game states — only include if the state's target matches today's seed
    const keys = _syncDailyKeys();
    const dailyStates = { date: keys.dateStr };
    const epState = localStorage.getItem(keys.ep);
    const gwCState = localStorage.getItem(keys.gwC);
    const gw00sState = localStorage.getItem(keys.gw00s);
    const gw10sState = localStorage.getItem(keys.gw10s);
    const gw00s150State = localStorage.getItem(keys.gw00s150);
    const gw10s150State = localStorage.getItem(keys.gw10s150);
    // Verify each state's target matches today's actual target before syncing
    // This prevents stale game data (wrong player) from being saved with today's date
    function _saveVerifyTarget(stateJson, poolGetter, seedOffset) {
      try {
        const state = JSON.parse(stateJson);
        if (!state.targetName) return true;
        const pool = (typeof poolGetter === 'function') ? poolGetter() : null;
        if (!pool || !pool.length) return false; // can't verify, don't sync
        const d = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/New_York' }));
        const seed = d.getFullYear() * 10000 + (d.getMonth()+1) * 100 + d.getDate() + (seedOffset || 0);
        const todayTarget = pool[Math.abs(seed * 2654435761 >>> 0) % pool.length];
        return todayTarget && state.targetName === todayTarget.name;
      } catch(e) { return false; }
    }
    const _pool150Sync = (getter) => { const p = (typeof getter === 'function') ? getter() : null; return p ? p.filter(x => x.bestSzn != null && x.bestSzn >= 150) : null; };
    // Only sync daily states that actually exist AND match today's target.
    // Each entry gets its own <key>Date stamp: the doc is written with
    // {merge:true}, so Firestore keeps yesterday's entries in the dailyStates
    // map while the shared `date` field gets bumped to today — the per-key
    // date is what lets the restore side tell fresh entries from leftovers.
    if (epState) { dailyStates.ep = epState; dailyStates.epDate = keys.dateStr; }
    if (gwCState && _saveVerifyTarget(gwCState, window._gwGetPoolCurrent, 0)) { dailyStates.gwC = gwCState; dailyStates.gwCDate = keys.dateStr; }
    if (gw00sState && _saveVerifyTarget(gw00sState, window._gwGetPool2000s, 20003)) { dailyStates.gw00s = gw00sState; dailyStates.gw00sDate = keys.dateStr; }
    if (gw10sState && _saveVerifyTarget(gw10sState, window._gwGetPool2010s, 20107)) { dailyStates.gw10s = gw10sState; dailyStates.gw10sDate = keys.dateStr; }
    if (gw00s150State && _saveVerifyTarget(gw00s150State, () => _pool150Sync(window._gwGetPool2000s), 31502)) { dailyStates.gw00s150 = gw00s150State; dailyStates.gw00s150Date = keys.dateStr; }
    if (gw10s150State && _saveVerifyTarget(gw10s150State, () => _pool150Sync(window._gwGetPool2010s), 31503)) { dailyStates.gw10s150 = gw10s150State; dailyStates.gw10s150Date = keys.dateStr; }
    if (dailyStates.ep || dailyStates.gwC || dailyStates.gw00s || dailyStates.gw10s || dailyStates.gw00s150 || dailyStates.gw10s150) data.dailyStates = dailyStates;
    data.syncedAt = new Date().toISOString();
    db.collection('user_game_data').doc(user.uid).set(data, { merge: true }).catch(e => console.warn('[Sync] save error:', e));
  }

  function loadGameDataFromCloud() {
    const db = (typeof firebase !== 'undefined' && firebase.firestore) ? firebase.firestore() : null;
    const user = (typeof firebase !== 'undefined' && firebase.auth) ? firebase.auth().currentUser : null;
    if (!db || !user) return;
    db.collection('user_game_data').doc(user.uid).get().then(doc => {
      if (!doc.exists) return;
      const cloud = doc.data();
      // For numeric keys, take the higher value between local and cloud
      SYNC_KEYS_MAX.forEach(k => {
        if (cloud[k] !== undefined) {
          const local = parseFloat(localStorage.getItem(k) || '0');
          const remote = parseFloat(cloud[k] || 0);
          if (remote > local) {
            localStorage.setItem(k, String(remote));
          }
        }
      });
      // For string keys, use cloud if local is empty
      SYNC_KEYS_STR.forEach(k => {
        if (cloud[k] !== undefined) {
          const local = localStorage.getItem(k);
          if (!local || local === '' || local === 'false') {
            localStorage.setItem(k, cloud[k]);
          }
        }
      });
      // For JSON array keys, merge
      SYNC_KEYS_JSON.forEach(k => {
        if (cloud[k]) {
          try {
            const localArr = JSON.parse(localStorage.getItem(k) || '[]');
            const cloudArr = JSON.parse(cloud[k] || '[]');
            const merged = [...new Set([...localArr, ...cloudArr])];
            localStorage.setItem(k, JSON.stringify(merged));
          } catch(e) {}
        }
      });
      // For object-array keys, merge by dedupeBy field, sort desc by it, cap.
      SYNC_KEYS_OBJARR.forEach(spec => {
        if (cloud[spec.key]) {
          try {
            const localArr = JSON.parse(localStorage.getItem(spec.key) || '[]');
            const cloudArr = JSON.parse(cloud[spec.key] || '[]');
            const seen = new Set();
            const merged = [];
            [...localArr, ...cloudArr]
              .sort((a, b) => (b[spec.dedupeBy] || 0) - (a[spec.dedupeBy] || 0))
              .forEach(item => {
                const id = item[spec.dedupeBy];
                if (id != null && !seen.has(id)) { seen.add(id); merged.push(item); }
              });
            const capped = merged.slice(0, spec.cap || merged.length);
            localStorage.setItem(spec.key, JSON.stringify(capped));
          } catch(e) {}
        }
      });
      // Load today's daily game states from cloud if not played locally
      let _dailyRestored = false;
      if (cloud.dailyStates) {
        const keys = _syncDailyKeys();
        if (cloud.dailyStates.date === keys.dateStr) {
          // Fallback verification for legacy docs without per-key dates: check
          // that the cloud state's target matches today's seed. NOTE: an
          // unloaded pool means "can't verify" → SKIP. The old "allow it"
          // behavior was the bug that kept resurrecting yesterday's finished
          // era games: this load runs ~400ms after auth, the 2000s/2010s pools
          // arrive seconds later with the lazy retired data, so a stale entry
          // (kept alive in the merged dailyStates map) sailed through
          // unverified and landed under TODAY's localStorage key.
          function _verifyDailyTarget(stateJson, poolGetter, seedOffset) {
            try {
              const state = JSON.parse(stateJson);
              if (!state.targetName) return true; // no target to verify
              const pool = (typeof poolGetter === 'function') ? poolGetter() : null;
              if (!pool || !pool.length) return false; // can't verify without pool — skip
              const d = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/New_York' }));
              const seed = d.getFullYear() * 10000 + (d.getMonth()+1) * 100 + d.getDate() + (seedOffset || 0);
              const todayTarget = pool[Math.abs(seed * 2654435761 >>> 0) % pool.length];
              return todayTarget && state.targetName === todayTarget.name;
            } catch(e) { return false; }
          }
          // Per-key freshness: true/false when the save stamped a <key>Date,
          // null for legacy docs (fall back to target verification).
          function _cloudFresh(k) {
            const dt = cloud.dailyStates[k + 'Date'];
            if (dt === undefined) return null;
            return dt === keys.dateStr;
          }
          function _restoreDaily(k, localKey, poolGetter, seedOffset) {
            if (!cloud.dailyStates[k] || localStorage.getItem(localKey)) return;
            const fresh = _cloudFresh(k);
            const ok = fresh === true || (fresh === null && poolGetter !== null && _verifyDailyTarget(cloud.dailyStates[k], poolGetter, seedOffset));
            if (ok) {
              localStorage.setItem(localKey, cloud.dailyStates[k]);
              _dailyRestored = true;
            } else {
              console.log('[Sync] Skipped stale ' + k + ' daily state');
            }
          }
          const _pool150R = (getter) => { const p = (typeof getter === 'function') ? getter() : null; return p ? p.filter(x => x.bestSzn != null && x.bestSzn >= 150) : null; };
          // Guess Who daily (picture game) has no target to verify, so legacy
          // docs (no epDate) are skipped outright. Key "ep" is legacy naming.
          _restoreDaily('ep', keys.ep, null, 0);
          // Elite Pull dailies (clue-grid). Key "gwC" is legacy naming.
          _restoreDaily('gwC', keys.gwC, window._gwGetPoolCurrent, 0);
          _restoreDaily('gw00s', keys.gw00s, window._gwGetPool2000s, 20003);
          _restoreDaily('gw10s', keys.gw10s, window._gwGetPool2010s, 20107);
          _restoreDaily('gw00s150', keys.gw00s150, () => _pool150R(window._gwGetPool2000s), 31502);
          _restoreDaily('gw10s150', keys.gw10s150, () => _pool150R(window._gwGetPool2010s), 31503);
        }
      }
      // If we restored daily state that the games already initialized without, reload once
      if (_dailyRestored && !sessionStorage.getItem('_dailySyncReloaded')) {
        sessionStorage.setItem('_dailySyncReloaded', '1');
        setTimeout(() => window.location.reload(), 300);
        return;
      }
      console.log('[Sync] Game data loaded from cloud');
      // Refresh badge display
      if (typeof window._renderBadgeAvatars === 'function') window._renderBadgeAvatars();
    }).catch(e => console.warn('[Sync] load error:', e));
  }

  window._saveGameDataToCloud = saveGameDataToCloud;
  window._loadGameDataFromCloud = loadGameDataFromCloud;

  // Auto-save periodically when user is active (every 30 seconds)
  setInterval(() => {
    const user = (typeof firebase !== 'undefined' && firebase.auth) ? firebase.auth().currentUser : null;
    if (user) saveGameDataToCloud();
  }, 30000);
})();

// === TRADE CALCULATOR ===
(function() {
  let tradeMode = 'redraft';
  let tradeSource = 'consensus'; // default to consensus (available to all users)
  const sideA = { players: [], picks: [] };
  const sideB = { players: [], picks: [] };
  let activeYearA = '2027';
  let activeYearB = '2027';
  let pendingPick = null;

  const PICK_BASE = {
    '1st': { redraft: 80, superflex: 90 },
    '2nd': { redraft: 35, superflex: 40 },
    '3rd': { redraft: 15, superflex: 18 },
    '4th': { redraft: 5, superflex: 7 }
  };
  const YEAR_MULT = { '2026': 1.15, '2027': 1.0, '2028': 0.85, '2029': 0.7 };
  const SLOT_MULT = { 'early': 1.2, 'mid': 1.0, 'late': 0.8 };

  // Look up a pick entry in D by name and get its trade value from the board
  function _pickTradeValue(round, year, slot, src, mode, pickNum) {
    // For current-year picks with exact pick numbers (e.g. "1.03"),
    // find the actual rookie player at that board position and use THEIR trade value.
    if (pickNum) {
      const rdNum = parseInt(pickNum.split('.')[0]);
      const pickInRound = parseInt(pickNum.split('.')[1]);
      if (rdNum && pickInRound) {
        // Determine league size from the pick number format (pick 1.12 → 12-team league)
        // Default to 12 if unclear
        const leagueSize = (typeof window._mtTeams !== 'undefined' && window._mtTeams) ? window._mtTeams.length : 12;
        const overallIdx = (rdNum - 1) * leagueSize + (pickInRound - 1);
        // Find rookies on the board in order (same logic as rookiePickMap)
        const board = versionBoards[src] ? versionBoards[src][mode] : null;
        if (board) {
          const rookies = [];
          board.forEach(function(dIdx) {
            const p = D[dIdx];
            if (!p || p.s === 'K' || p.s === 'DST' || p._isFuturePick) return;
            const _cb2026 = (typeof COMBINE_DATA !== 'undefined' && COMBINE_DATA[p.n] && COMBINE_DATA[p.n].yr === 2026);
            const isRookie = (!p.career || p.career.length === 0) && (_cb2026 || !p.t || p.t === 'TBD' || p.t === 'FA');
            if (isRookie) rookies.push(dIdx);
          });
          if (overallIdx < rookies.length) {
            const rookieEntry = D[rookies[overallIdx]];
            if (rookieEntry && typeof window._getTradeValue === 'function') {
              return window._getTradeValue(rookieEntry, src, mode);
            }
          }
        }
      }
    }
    // Fallback: generic Early/Mid/Late pick entry
    const slotLabel = slot === 'early' ? 'Early' : slot === 'late' ? 'Late' : 'Mid';
    const rdLabel = round;
    // For 3rd/4th, picks are just "2027 3rd" (no slot prefix)
    const pickName = (round === '3rd' || round === '4th') ? `${year} ${rdLabel}` : `${year} ${slotLabel} ${rdLabel}`;
    const entry = D.find(d => d.n === pickName && d._isFuturePick);
    if (entry && typeof window._getTradeValue === 'function') {
      return window._getTradeValue(entry, src, mode);
    }
    return 0;
  }

  function getPickValue(round, year, slot, pickNum) {
    // Dynasty modes: use board position (wherever Jack ranked the pick).
    // pickNum (e.g. "1.04") routes _pickTradeValue to the actual rookie at that
    // board position rather than the generic Early/Mid/Late slot value.
    if (tradeMode === 'dynasty' || tradeMode === 'dynastysf') {
      return _pickTradeValue(round, year, slot, tradeSource, tradeMode, pickNum);
    }
    // Redraft/superflex: use static base values
    const base = PICK_BASE[round] ? PICK_BASE[round][tradeMode] : 0;
    return Math.round(base * (YEAR_MULT[year] || 0.7) * (SLOT_MULT[slot] || 1.0));
  }

  // Expose pick value function globally for My Teams
  window._getPickValue = function(round, year, slot, mode, pickNum) {
    const m = mode || tradeMode;
    // Dynasty modes: use board position
    if (m === 'dynasty' || m === 'dynastysf') {
      return _pickTradeValue(round, year, slot, 'jacks', m, pickNum);
    }
    // Redraft/superflex: use static base values
    const base = PICK_BASE[round] ? PICK_BASE[round][m] : 0;
    return Math.round(base * (YEAR_MULT[year] || 0.7) * (SLOT_MULT[slot] || 1.0));
  };

  // Tier multipliers — sharper separation, elite scarcity premium
  const TIER_MULT = {
    'S': 1.45,  // Elite — scarcity premium
    'A': 1.20,  // Top tier
    'B': 1.07,  // Above average
    'C': 1.0,   // Average — baseline
    'D': 0.88,  // Below average
    'E': 0.72,  // Low tier
    'F': 0.50   // Bottom — heavy discount
  };

  // Note: no age multiplier — age is already baked into every ranking source
  // (Jack's, Consensus, KTC, Sleeper dynasty ADP), so applying one
  // on top of the rank would double-count age decay.

  function _getTierForPlayerFull(d, src, mode) {
    const srcTiers = versionTiers[src][mode].ALL || [];
    const srcBoard = versionBoards[src][mode];
    const boardPos = srcBoard.indexOf(d.idx);
    const rank = boardPos >= 0 ? boardPos + 1 : 999;
    let currentTier = null;
    const sorted = srcTiers.slice().sort((a,b) => a.afterRank - b.afterRank);
    for (const t of sorted) {
      if (t.afterRank <= rank) currentTier = t;
      else break;
    }
    return currentTier ? currentTier.label : '';
  }

  function getTierForPlayer(d) {
    return _getTierForPlayerFull(d, tradeSource, tradeMode);
  }

  // ADP-source aware board cache. Builds a rank order from the chosen ADP source.
  const _adpBoardsCache = {};
  window._invalidateAdpBoards = function() { Object.keys(_adpBoardsCache).forEach(k => delete _adpBoardsCache[k]); };
  function _getAdpBoard(src, mode) {
    const key = src + ':' + mode;
    if (_adpBoardsCache[key]) return _adpBoardsCache[key];
    if (typeof D === 'undefined') return [];
    const getVal = d => {
      if (src === 'underdog') {
        if (mode === 'dynastysf') return d.sa != null ? d.sa : null;
        if (mode === 'dynasty') return d.da != null ? d.da : null;
        if (mode === 'superflex') return d.sfa != null ? d.sfa : null;
        return d.a != null ? d.a : null;
      }
      if (src === 'sleeper') {
        // Sleeper fields: slR (redraft), slSf (superflex), slDy (dynasty), slDsf (dynasty SF)
        if (mode === 'dynastysf') return d.slDsf != null ? d.slDsf : null;
        if (mode === 'dynasty') return d.slDy != null ? d.slDy : null;
        if (mode === 'superflex') return d.slSf != null ? d.slSf : null;
        return d.slR != null ? d.slR : null;
      }
      if (src === 'ktc') {
        const map = mode === 'dynastysf' ? (typeof KTC_SF !== 'undefined' ? KTC_SF : {}) : (typeof KTC_1QB !== 'undefined' ? KTC_1QB : {});
        return map[d.n] != null ? map[d.n] : null;
      }
      // espn/yahoo not yet implemented — fall back to underdog
      if (mode === 'dynastysf') return d.sa != null ? d.sa : null;
      if (mode === 'dynasty') return d.da != null ? d.da : null;
      if (mode === 'superflex') return d.sfa != null ? d.sfa : null;
      return d.a != null ? d.a : null;
    };
    const items = [];
    D.forEach((d, idx) => {
      const v = getVal(d);
      if (v != null && v < 900) items.push({idx, v});
    });
    // KTC: higher value = better (descending). ADP: lower = better (ascending).
    if (src === 'ktc') items.sort((a, b) => b.v - a.v);
    else items.sort((a, b) => a.v - b.v);
    const board = items.map(x => x.idx);
    _adpBoardsCache[key] = board;
    return board;
  }
  // Expose for other modules (My Teams, etc.)
  window._getAdpBoard = _getAdpBoard;

  // Global trade value function — single source of truth for rankings, trade calc, My Teams, portfolio
  // Mode-specific power law CALIBRATED against KeepTradeCut:
  //   redraft/superflex:  1000 / (rank^0.8 + 3)   — steep top, rewards elite picks
  //   dynasty/dynastysf:  7750 / (rank^0.8 + 30)  — KTC-shaped: flat top, long depth tail
  // The dynasty offset of 30 flattens rank #1 vs #50 ratio to ~1.7x (matches KTC) instead of ~5x.
  const _ADP_SRCS = ['underdog', 'ktc', 'espn', 'sleeper', 'yahoo'];
  window._getTradeValue = function(d, src, mode) {
    const s = src || tradeSource;
    const m = mode || tradeMode;
    const isAdpSrc = _ADP_SRCS.indexOf(s) >= 0;
    const srcBoard = isAdpSrc ? _getAdpBoard(s, m) : (versionBoards[s] && versionBoards[s][m]);
    if (!srcBoard) return 1;
    const boardPos = srcBoard.indexOf(d.idx);
    const rank = boardPos >= 0 ? boardPos + 1 : 999;
    if (rank >= 400) return 1;
    const isDyn = (m === 'dynasty' || m === 'dynastysf');
    let val;
    if (isDyn) {
      val = Math.max(Math.round(7750 / (Math.pow(rank, 0.8) + 30)), 1);
    } else {
      val = Math.max(Math.round(1000 / (Math.pow(rank, 0.8) + 3)), 1);
    }
    // Tier multiplier only applies to version-based sources (consensus/jacks/mine)
    if (!isAdpSrc) {
      const tierLabel = _getTierForPlayerFull(d, s, m);
      if (tierLabel && TIER_MULT[tierLabel] !== undefined) {
        val = Math.round(val * TIER_MULT[tierLabel]);
      }
    }
    return Math.max(val, 1);
  };

  // Expose TIER_MULT globally so other IIFEs can read it
  window._TIER_MULT = TIER_MULT;

  function getPlayerValue(d) {
    return window._getTradeValue(d, tradeSource, tradeMode);
  }

  function calcSideTotal(side) {
    let total = 0;
    side.players.forEach(idx => { total += getPlayerValue(D[idx]); });
    side.picks.forEach(p => { total += getPickValue(p.round, p.year, p.slot, p._pickNum); });
    return total;
  }

  function slotLabel(slot) {
    return slot.charAt(0).toUpperCase() + slot.slice(1);
  }

  function renderSide(side, containerId, totalId, sideClass) {
    const container = document.getElementById(containerId);
    const totalEl = document.getElementById(totalId);
    if (side.players.length === 0 && side.picks.length === 0) {
      container.innerHTML = '<div class="trade-empty">No players added yet</div>';
    } else {
      let html = '';
      side.players.forEach(idx => {
        const d = D[idx];
        const val = getPlayerValue(d);
        const tier = getTierForPlayer(d);
        const tierHtml = tier ? `<span class="tier-badge ${tierColor(tier)}" style="font-size:.55rem;padding:1px 5px;min-width:auto;margin-left:auto">${tier}</span>` : '';
        html += `<div class="trade-player-chip">
          <span class="tp-pos ${d.s}">${d.s}</span>
          <a class="tp-name tp-card-link" href="javascript:void(0)" data-didx="${idx}" style="color:inherit;text-decoration:none;cursor:pointer">${d.n}</a>
          ${tierHtml}
          <span class="tp-val">${val}</span>
          <button class="tp-remove" data-idx="${idx}" data-side="${sideClass}">&times;</button>
        </div>`;
      });
      side.picks.forEach((p, i) => {
        const val = getPickValue(p.round, p.year, p.slot, p._pickNum);
        // Real picks (with _pickNum from synced rosters) display as "2027 1.04 · via Sam"
        // so it's clear which exact pick is in the trade. Falls back to generic slot label.
        const pickLabel = p._pickNum
          ? (p.year + ' ' + p._pickNum + (p.original ? ' <span style="color:var(--text2);font-weight:400">· via ' + _esc(p.original) + '</span>' : ''))
          : (p.year + ' ' + slotLabel(p.slot) + ' ' + p.round);
        html += `<div class="trade-player-chip">
          <span class="tp-pos" style="background:rgba(245,158,11,.12);color:var(--accent);font-size:.55rem">PICK</span>
          <span class="tp-name">${pickLabel}</span>
          <span class="tp-val">${val}</span>
          <button class="tp-remove" data-pick-idx="${i}" data-side="${sideClass}">&times;</button>
        </div>`;
      });
      container.innerHTML = html;
    }
    totalEl.textContent = calcSideTotal(side);
    attachRemoveListeners();
    updateResult();
  }

  function updateResult() {
    const totalA = calcSideTotal(sideA);
    const totalB = calcSideTotal(sideB);
    const sum = totalA + totalB;
    const verdict = document.getElementById('tradeVerdict');
    const sub = document.getElementById('tradeVerdictSub');
    const barA = document.getElementById('tradeBarA');
    const barB = document.getElementById('tradeBarB');
    const insightsEl = document.getElementById('tradeInsights');

    const resultEl = document.getElementById('tradeResult');
    if (sum === 0) {
      barA.style.width = '50%'; barB.style.width = '50%';
      verdict.textContent = '';
      verdict.className = 'trade-verdict even'; sub.textContent = '';
      if (resultEl) resultEl.classList.add('is-empty');
      if (insightsEl) { insightsEl.style.display = 'none'; insightsEl.innerHTML = ''; }
      return;
    }
    if (resultEl) resultEl.classList.remove('is-empty');
    // Symmetric bar widths: clamp to [8, 92] so the losing side always shows a sliver,
    // and swapping A↔B produces a mirror image rather than a vanishing bar.
    const pctA = Math.max(8, Math.min(92, Math.round((totalA / sum) * 100)));
    barA.style.width = pctA + '%'; barB.style.width = (100 - pctA) + '%';
    const diff = Math.abs(totalA - totalB);
    // Use diff / max(A,B) instead of diff / (A+B): symmetric, bounded [0,100%],
    // and ~2x more resistant to "equal-value dilution" where adding identical
    // filler to both sides used to collapse an unfair trade into a FAIR verdict.
    const diffPct = Math.round((diff / Math.max(totalA, totalB)) * 100);

    if (diffPct <= 5) {
      verdict.textContent = 'FAIR TRADE'; verdict.className = 'trade-verdict even';
      sub.textContent = 'Both sides are roughly equal in value';
    } else if (totalA > totalB) {
      verdict.textContent = 'TEAM A WINS'; verdict.className = 'trade-verdict win-a';
      sub.textContent = `Team A gets +${diff} more value (${diffPct}% advantage)`;
    } else {
      verdict.textContent = 'TEAM B WINS'; verdict.className = 'trade-verdict win-b';
      sub.textContent = `Team B gets +${diff} more value (${diffPct}% advantage)`;
    }

    // Insights — peak, depth, age, picks, position split
    const insights = _buildTradeInsights(sideA, sideB);
    if (insightsEl) {
      if (insights.length) {
        insightsEl.style.display = '';
        insightsEl.innerHTML = insights.map(t => '<div class="trade-insight-row">• ' + t + '</div>').join('');
      } else {
        insightsEl.style.display = 'none';
        insightsEl.innerHTML = '';
      }
    }
  }

  // Rule-based 1-3 sentence summary of what each side is getting.
  function _buildTradeInsights(a, b) {
    const out = [];
    const aPlayers = a.players.map(i => D[i]).filter(Boolean);
    const bPlayers = b.players.map(i => D[i]).filter(Boolean);
    const aValues = aPlayers.map(d => getPlayerValue(d));
    const bValues = bPlayers.map(d => getPlayerValue(d));
    const aTotal = calcSideTotal(a);
    const bTotal = calcSideTotal(b);
    if (!aTotal || !bTotal) return out;

    const isDyn = tradeMode === 'dynasty' || tradeMode === 'dynastysf';

    // 1. Peak — highest single-asset value
    const aPeak = aValues.length ? Math.max(...aValues) : 0;
    const bPeak = bValues.length ? Math.max(...bValues) : 0;
    if (aPeak && bPeak) {
      const peakDiffPct = Math.round((Math.abs(aPeak - bPeak) / Math.max(aPeak, bPeak)) * 100);
      if (peakDiffPct >= 15) {
        const winSide = aPeak > bPeak ? 'A' : 'B';
        const winName = (aPeak > bPeak ? aPlayers[aValues.indexOf(aPeak)] : bPlayers[bValues.indexOf(bPeak)]).n;
        out.push(`Team ${winSide} gets the higher peak (${_esc(winName)})`);
      }
    }

    // 2. Depth — sides with notably more assets
    const aCount = aPlayers.length + a.picks.length;
    const bCount = bPlayers.length + b.picks.length;
    if (Math.abs(aCount - bCount) >= 2) {
      const moreSide = aCount > bCount ? 'A' : 'B';
      const moreN = Math.max(aCount, bCount);
      const lessN = Math.min(aCount, bCount);
      out.push(`Team ${moreSide} gets more depth (${moreN} assets vs ${lessN})`);
    }

    // 3. Age — only meaningful in dynasty
    if (isDyn) {
      const aAges = aPlayers.map(d => d.age).filter(v => typeof v === 'number');
      const bAges = bPlayers.map(d => d.age).filter(v => typeof v === 'number');
      if (aAges.length && bAges.length) {
        const aAvg = aAges.reduce((s, v) => s + v, 0) / aAges.length;
        const bAvg = bAges.reduce((s, v) => s + v, 0) / bAges.length;
        if (Math.abs(aAvg - bAvg) >= 2) {
          const youngSide = aAvg < bAvg ? 'A' : 'B';
          out.push(`Team ${youngSide} leans younger (avg age ${aAvg.toFixed(1)} vs ${bAvg.toFixed(1)})`);
        }
      }
    }

    // 4. Pick capital — dynasty only
    if (isDyn && (a.picks.length || b.picks.length) && a.picks.length !== b.picks.length) {
      const moreSide = a.picks.length > b.picks.length ? 'A' : 'B';
      out.push(`Team ${moreSide} gets more pick capital (${Math.max(a.picks.length, b.picks.length)} picks vs ${Math.min(a.picks.length, b.picks.length)})`);
    }

    // 5. Position concentration — which side is loading up where
    const posTotal = (players) => {
      const m = {};
      players.forEach(d => { m[d.s] = (m[d.s] || 0) + 1; });
      return m;
    };
    const aPos = posTotal(aPlayers);
    const bPos = posTotal(bPlayers);
    ['QB','RB','WR','TE'].forEach(pos => {
      const aN = aPos[pos] || 0, bN = bPos[pos] || 0;
      if (aN >= 2 && bN === 0) out.push(`Team A loads up at ${pos} (${aN} ${pos}s)`);
      else if (bN >= 2 && aN === 0) out.push(`Team B loads up at ${pos} (${bN} ${pos}s)`);
    });

    // Cap at 3 to keep it scannable
    return out.slice(0, 3);
  }

  function renderAll() {
    renderSide(sideA, 'tradePlayersA', 'tradeTotalA', 'a');
    renderSide(sideB, 'tradePlayersB', 'tradeTotalB', 'b');
  }

  function attachRemoveListeners() {
    document.querySelectorAll('.tp-remove').forEach(btn => {
      btn.addEventListener('click', () => {
        const side = btn.dataset.side === 'a' ? sideA : sideB;
        const wasPick = btn.dataset.pickIdx !== undefined;
        if (btn.dataset.idx !== undefined) {
          side.players = side.players.filter(i => i !== +btn.dataset.idx);
        } else if (wasPick) {
          side.picks.splice(+btn.dataset.pickIdx, 1);
        }
        renderAll();
        if (wasPick && typeof _calcRenderRealPicks === 'function') {
          _calcRenderRealPicks(btn.dataset.side);
        }
      });
    });
    // Player name clicks open player card — pass tradeMode so the card shows
    // dynasty rank/ADP when the trade is in dynasty mode, etc.
    document.querySelectorAll('.tp-card-link').forEach(link => {
      link.addEventListener('click', e => {
        e.stopPropagation();
        const dIdx = parseInt(link.dataset.didx);
        const d = D[dIdx];
        if (d && typeof openPlayerCard === 'function') openPlayerCard(d, tradeMode);
      });
    });
  }

  // Per-side roster filter — set when an owner is picked in the Calc-view team picker.
  // Each entry: { idxSet: Set<dIdx>, owner: string } or null = no filter (all players).
  const _calcSideFilters = { a: null, b: null };
  window._calcSideFilters = _calcSideFilters;

  // Search
  function setupSearch(inputId, dropId, side) {
    const input = document.getElementById(inputId);
    const drop = document.getElementById(dropId);
    const sideKey = side === sideA ? 'a' : 'b';
    let debounce = null;
    input.addEventListener('input', () => {
      clearTimeout(debounce);
      debounce = setTimeout(() => {
        const q = input.value.trim().toLowerCase();
        if (q.length < 2) { drop.classList.remove('show'); return; }
        const usedIdxs = new Set([...sideA.players, ...sideB.players]);
        const rosterFilter = _calcSideFilters[sideKey];
        const matches = D.filter(d =>
          !usedIdxs.has(d.idx) && d.s !== 'K' && !d._retired && d.t !== 'Retired' &&
          (!rosterFilter || rosterFilter.idxSet.has(d.idx)) &&
          (d.n.toLowerCase().includes(q) || d.t.toLowerCase().includes(q))
        ).slice(0, 8);
        if (!matches.length) { drop.classList.remove('show'); return; }
        drop.innerHTML = matches.map(d => {
          const val = getPlayerValue(d);
          return `<div class="trade-drop-item" data-idx="${d.idx}">
            <span class="td-pos ${d.s}">${d.s}</span><span>${d.n}</span>
            <span class="td-team">${d.t}</span><span class="td-val">${val}</span>
          </div>`;
        }).join('');
        drop.classList.add('show');
        drop.querySelectorAll('.trade-drop-item').forEach(item => {
          item.addEventListener('click', () => {
            side.players.push(+item.dataset.idx);
            input.value = ''; drop.classList.remove('show'); renderAll();
          });
        });
      }, 150);
    });
    input.addEventListener('blur', () => { setTimeout(() => drop.classList.remove('show'), 200); });
    input.addEventListener('focus', () => { if (input.value.trim().length >= 2) input.dispatchEvent(new Event('input')); });
  }
  setupSearch('tradeSearchA', 'tradeDropA', sideA);
  setupSearch('tradeSearchB', 'tradeDropB', sideB);

  // Year tabs
  document.querySelectorAll('.trade-yr-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      const side = tab.dataset.side;
      tab.closest('.trade-pick-year-tabs').querySelectorAll('.trade-yr-tab').forEach(t => t.classList.remove('active'));
      tab.classList.add('active');
      if (side === 'a') activeYearA = tab.dataset.yr;
      else activeYearB = tab.dataset.yr;
    });
  });

  // Slot popover logic
  const slotPop = document.getElementById('tradeSlotPop');
  const slotTitle = document.getElementById('tradeSlotTitle');

  function showSlotPopover(btnEl, round, side) {
    pendingPick = { side, round };
    slotTitle.textContent = round.toUpperCase() + ' ROUND';
    // Position near the button
    const rect = btnEl.getBoundingClientRect();
    const wrapper = document.querySelector('.trade-wrapper');
    const wrapRect = wrapper.getBoundingClientRect();
    slotPop.style.display = '';
    slotPop.style.position = 'fixed';
    slotPop.style.left = Math.min(rect.left, window.innerWidth - 130) + 'px';
    slotPop.style.top = (rect.bottom + 4) + 'px';
  }

  function hideSlotPopover() {
    slotPop.style.display = 'none';
    pendingPick = null;
  }

  // Round buttons open slot popover
  document.querySelectorAll('.trade-pick-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const round = btn.dataset.round;
      const side = btn.dataset.side;
      showSlotPopover(btn, round, side);
    });
  });

  // Slot buttons add the pick
  document.querySelectorAll('.trade-slot-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      if (!pendingPick) return;
      const side = pendingPick.side === 'a' ? sideA : sideB;
      const year = pendingPick.side === 'a' ? activeYearA : activeYearB;
      side.picks.push({ round: pendingPick.round, year, slot: btn.dataset.slot });
      hideSlotPopover();
      renderAll();
    });
  });

  // Close popover on outside click
  document.addEventListener('click', (e) => {
    if (slotPop.style.display !== 'none' && !slotPop.contains(e.target)) {
      hideSlotPopover();
    }
  });

  // Mode tabs
  function updatePickVisibility() {
    // Draft-pick trading is a dynasty-only concept. Redraft AND superflex are
    // both redraft-style (players only) — only the two dynasty modes trade picks.
    const show = tradeMode === 'dynasty' || tradeMode === 'dynastysf';
    document.getElementById('tradePickSectionA').style.display = show ? '' : 'none';
    document.getElementById('tradePickSectionB').style.display = show ? '' : 'none';
    if (!show) { sideA.picks = []; sideB.picks = []; }
    const sub = document.getElementById('tradeSubtitle');
    if (sub) sub.textContent = show
      ? 'Add players and draft picks to each side to evaluate trades'
      : 'Add players to each side to evaluate trades';
  }

  document.querySelectorAll('.trade-mode-tab').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.trade-mode-tab').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      tradeMode = btn.dataset.tmode;
      updatePickVisibility();
      hideSlotPopover();
      renderAll();
    });
  });
  updatePickVisibility();

  // Ranking source tabs (Consensus / Jack's / JS Model / My Ranks + ADP sources)
  const LOCKED_ADP_SRCS = ['espn', 'yahoo'];
  document.querySelectorAll('.trade-src-tab').forEach(btn => {
    btn.addEventListener('click', () => {
      const src = btn.dataset.tsrc;
      // Lock Jack's Ranks behind premium
      if (src === 'jacks' && !hasPremium()) {
        const existing = document.getElementById('tradePremiumLock');
        if (existing) existing.remove();
        const lockMsg = document.createElement('div');
        lockMsg.id = 'tradePremiumLock';
        lockMsg.style.cssText = 'text-align:center;padding:1.25rem;margin:1rem 0;border-radius:10px;background:rgba(245,158,11,.06);border:1px solid rgba(245,158,11,.18)';
        lockMsg.innerHTML = '<div style="font-size:1.3rem;margin-bottom:.4rem">&#128274;</div>' +
          '<div style="font-family:Bebas Neue,sans-serif;font-size:.95rem;letter-spacing:1.5px;color:var(--accent);margin-bottom:.3rem">PREMIUM FEATURE</div>' +
          '<div style="font-size:.75rem;color:var(--text2);margin-bottom:.75rem">Jack\'s trade values are a Pro feature. Upgrade to unlock.</div>' +
          '<button class="premium-wall-btn" onclick="document.querySelector(\'[data-page=account]\').click();setTimeout(()=>document.querySelector(\'[data-acct-tab=premium]\').click(),100)">GET PREMIUM</button>';
        const tradeLayout = document.querySelector('.trade-layout');
        if (tradeLayout) tradeLayout.parentElement.insertBefore(lockMsg, tradeLayout);
        return;
      }
      // Locked ADP sources (ESPN/Sleeper/Yahoo) — not implemented yet
      if (LOCKED_ADP_SRCS.indexOf(src) >= 0) {
        if (typeof toast === 'function') toast(src.toUpperCase() + ' ADP coming soon — Premium only');
        return;
      }
      // Underdog ADP is premium (matches Rankings + Mock Draft)
      if (src === 'underdog' && !hasPremium()) {
        if (typeof toast === 'function') toast('Underdog ADP requires Premium');
        return;
      }
      // Remove lock message when switching to unlocked source
      const existing = document.getElementById('tradePremiumLock');
      if (existing) existing.remove();
      document.querySelectorAll('.trade-src-tab').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      tradeSource = src;
      renderAll();
    });
  });

  // Reset
  document.getElementById('tradeResetBtn').addEventListener('click', () => {
    sideA.players = []; sideA.picks = [];
    sideB.players = []; sideB.picks = [];
    document.getElementById('tradeSearchA').value = '';
    document.getElementById('tradeSearchB').value = '';
    hideSlotPopover();
    renderAll();
  });

  // Share — encode current trade state into a URL the user can paste anywhere.
  function _buildTradeShareUrl() {
    const sideToObj = (side) => ({
      p: side.players.map(idx => D[idx] && D[idx].n).filter(Boolean),
      k: side.picks.map(p => [p.round, p.year, p.slot])
    });
    const state = { m: tradeMode, s: tradeSource, a: sideToObj(sideA), b: sideToObj(sideB) };
    const encoded = btoa(unescape(encodeURIComponent(JSON.stringify(state))));
    const base = window.location.origin + window.location.pathname;
    return base + '?trade=' + encoded;
  }

  document.getElementById('tradeShareBtn').addEventListener('click', () => {
    if (!sideA.players.length && !sideA.picks.length && !sideB.players.length && !sideB.picks.length) {
      if (typeof toast === 'function') toast('Add players first, then share');
      return;
    }
    const url = _buildTradeShareUrl();
    const ok = (msg) => { if (typeof toast === 'function') toast(msg); };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(url)
        .then(() => ok('Trade URL copied — paste it anywhere'))
        .catch(() => { window.prompt('Copy this trade URL:', url); });
    } else {
      window.prompt('Copy this trade URL:', url);
    }
  });

  // Apply ?trade=... from the URL on initial load (and clean the URL afterwards).
  function _applyTradeShareUrl() {
    try {
      const params = new URLSearchParams(window.location.search);
      const raw = params.get('trade');
      if (!raw) return;
      let state;
      try {
        state = JSON.parse(decodeURIComponent(escape(atob(raw))));
      } catch (_e) { return; }
      if (!state || typeof state !== 'object') return;

      // Mode
      if (state.m) {
        const mTab = document.querySelector('.trade-mode-tab[data-tmode="' + state.m + '"]');
        if (mTab) mTab.click();
      }
      // Source
      if (state.s) {
        const sTab = document.querySelector('.trade-src-tab[data-tsrc="' + state.s + '"]');
        if (sTab && !sTab.classList.contains('locked')) sTab.click();
      }
      // Sides
      sideA.players = []; sideA.picks = [];
      sideB.players = []; sideB.picks = [];
      const fillSide = (saved, side) => {
        if (!saved) return;
        (saved.p || []).forEach(name => {
          if (typeof name !== 'string') return;
          const idx = (typeof nameToIdx !== 'undefined') ? nameToIdx[name] : undefined;
          if (idx !== undefined) side.players.push(idx);
        });
        (saved.k || []).forEach(triple => {
          if (Array.isArray(triple) && triple.length === 3) {
            side.picks.push({ round: triple[0], year: triple[1], slot: triple[2] });
          }
        });
      };
      fillSide(state.a, sideA);
      fillSide(state.b, sideB);

      // Navigate to the trade page
      const navBtn = document.querySelector('.nav-btn[data-page="trade"]');
      if (navBtn) navBtn.click();

      renderAll();

      // Clean the URL so refreshes / further share clicks don't double-encode.
      try {
        const cleanUrl = window.location.origin + window.location.pathname;
        window.history.replaceState({}, document.title, cleanUrl);
      } catch (_e) {}

      if (typeof toast === 'function') toast('Loaded shared trade');
    } catch (_e) {}
  }
  // Defer one tick so the surrounding IIFE finishes wiring tab handlers.
  setTimeout(_applyTradeShareUrl, 0);

  // Set initial active tab to consensus (default, works for all users)
  document.querySelectorAll('.trade-src-tab').forEach(b => {
    b.classList.toggle('active', b.dataset.tsrc === tradeSource);
  });

  // Hide lock icon on Jack's + Underdog tabs for premium users (icons are hardcoded in HTML)
  function _tradeUpdateJacksLock() {
    const prem = typeof hasPremium === 'function' && hasPremium();
    ['jacks', 'underdog'].forEach(function(srcKey) {
      const tab = document.querySelector('.trade-src-tab[data-tsrc="' + srcKey + '"]');
      if (!tab) return;
      const icon = tab.querySelector('.lock-icon');
      if (prem) {
        tab.classList.remove('locked');
        if (icon) icon.style.display = 'none';
      } else {
        if (icon) icon.style.display = '';
      }
    });
  }
  _tradeUpdateJacksLock();
  window._tradeUpdateJacksLock = _tradeUpdateJacksLock;

  // ═══════════════════════════════════════════════════════════
  // TRADE FINDER — engine + UI
  // Recommends trade packages by scanning your synced Sleeper league.
  // ═══════════════════════════════════════════════════════════
  function _esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }
  const _finderState = { targetDIdx: null, leagueIdx: 0 };

  function _finderLookupD(name) {
    if (typeof D === 'undefined' || !name) return null;
    if (typeof nameToIdx !== 'undefined' && nameToIdx[name] !== undefined) {
      return D[nameToIdx[name]];
    }
    const found = D.find(p => p.n === name);
    if (found) return found;
    const norm = String(name).toLowerCase().replace(/[.\-'\s]/g, '');
    return D.find(p => p.n && p.n.toLowerCase().replace(/[.\-'\s]/g, '') === norm) || null;
  }

  function _finderGetActiveLeague() {
    const leagues = window._mtSavedLeagues || [];
    if (!leagues.length) return null;
    const sel = document.getElementById('finderLeague');
    let idx = _finderState.leagueIdx;
    if (sel && sel.value !== '') idx = parseInt(sel.value);
    if (!leagues[idx]) idx = 0;
    return { league: leagues[idx], idx };
  }

  // Team archetype — Contender / Retool / Rebuilder. Manual override stored in
  // localStorage and respected over the heuristic. Dynasty-relevant only.
  const _ARCH_VALUES = ['auto', 'contender', 'retool', 'rebuilder'];
  function _archKey(league, team) {
    const lid = (league && (league.leagueId || league.name)) || '?';
    const tid = (team && (team.id != null ? team.id : team.owner)) || '?';
    return '_calcArch:' + lid + ':' + tid;
  }
  window._calcGetArchOverride = function(league, team) {
    try {
      const v = localStorage.getItem(_archKey(league, team));
      return _ARCH_VALUES.indexOf(v) >= 0 ? v : 'auto';
    } catch (_e) { return 'auto'; }
  };
  window._calcSetArchOverride = function(league, team, val) {
    try {
      if (!val || val === 'auto') localStorage.removeItem(_archKey(league, team));
      else localStorage.setItem(_archKey(league, team), val);
    } catch (_e) {}
  };
  // Archetype heuristic — LEAGUE-RELATIVE on projected PPG of the best lineup.
  // 1. Get each team's projected lineup PPG (already computed by _mtBestLineup
  //    at Sleeper-import time and stored as t.lineupPpg). Fallback: sum of top 9
  //    players' PPG if not yet computed (e.g. fresh import or test data).
  // 2. Rank teams; top third = Contender (highest PPG), bottom third = Rebuilder.
  // 3. Middle third gets nudged by pick capital — stacked picks → Rebuilder.
  function _calcPlayerPpg(d) {
    if (!d || d.s === 'K' || d.s === 'DST') return 0;
    // Mirrors _mtBestLineup's priority order: Clay → 2025 season → last career → JS model
    if (typeof MIKE_CLAY_PROJ !== 'undefined' && typeof clayLookup === 'function') {
      const cp = clayLookup(d.n);
      if (cp && cp.pts && cp.gm) return cp.pts / cp.gm;
    }
    if (d.s25 && d.s25.gp > 0 && d.s25.fpts > 0) return d.s25.fpts / d.s25.gp;
    if (d.career && d.career.length) {
      const last = d.career[d.career.length - 1];
      if (last.gp > 0 && last.fpts > 0) return last.fpts / last.gp;
    }
    return 0;
  }
  function _calcAutoArchetype(team, league) {
    if (!team) return null;
    function _teamProjPpg(t) {
      if (!t) return 0;
      // Prefer the lineup PPG computed by _mtBestLineup at import time —
      // it respects the league's actual starting positions.
      if (typeof t.lineupPpg === 'number' && t.lineupPpg > 0) return t.lineupPpg;
      // Fallback: top 9 PPG sum (no roster-position constraint, rough proxy).
      const ppgs = [];
      (t.players || []).forEach(name => {
        const d = _finderLookupD(name);
        const p = _calcPlayerPpg(d);
        if (p > 0) ppgs.push(p);
      });
      ppgs.sort((a, b) => b - a);
      return ppgs.slice(0, 9).reduce((s, v) => s + v, 0);
    }
    function _pickCapital(t) {
      let p = 0;
      (t.draftPicks || []).forEach(pk => {
        if (pk.round === '1st') p += 3;
        else if (pk.round === '2nd') p += 1;
      });
      return p;
    }
    const myPpg = _teamProjPpg(team);
    const myPicks = _pickCapital(team);
    // No league context — coarse absolute fallback.
    if (!league || !(league.teams || []).length || league.teams.length < 3) {
      if (myPpg > 130) return 'contender';
      if (myPpg < 80) return 'rebuilder';
      return 'retool';
    }
    const allPpg = league.teams.map(_teamProjPpg);
    const topPpg = Math.max.apply(null, allPpg);
    if (topPpg <= 0) return 'retool';
    // Relative-to-top thresholds — captures league spread, not just rank.
    // A stacked league produces multiple Contenders; a one-team-dominates
    // league produces fewer.
    //   Contender: within 12% of the top team's PPG (>= 88% of top)
    //   Rebuilder: more than 30% below the top team's PPG (<= 70% of top)
    //   Retool: in between
    const ratio = myPpg / topPpg;
    if (ratio >= 0.88) return 'contender';
    if (ratio <= 0.70) return 'rebuilder';
    // Middle band — only nudge DOWN to Rebuilder when a team is clearly
    // stacking picks (a transition-to-rebuild signal). Don't nudge UP to
    // Contender — having few picks isn't strong enough evidence on its own.
    const n = league.teams.length;
    const avgPicks = league.teams.reduce((s, t) => s + _pickCapital(t), 0) / n;
    if (avgPicks > 0 && myPicks > avgPicks * 1.7 && myPicks >= 4) return 'rebuilder';
    return 'retool';
  }
  window._calcGetArchetype = function(team, league) {
    if (!team) return null;
    const override = window._calcGetArchOverride(league, team);
    if (override && override !== 'auto') return override;
    return _calcAutoArchetype(team, league);
  };
  const _ARCH_LABEL = { contender: 'Contender', retool: 'Retool', rebuilder: 'Rebuilder' };
  const _ARCH_ICON = { contender: '🏆', retool: '🔄', rebuilder: '🌱' };

  // Engine — returns { results, otherTeam, myTeam, target } or { error }
  window._findTrade = function(targetDIdx, options) {
    options = options || {};
    const tolerance = options.tolerance != null ? options.tolerance : 0.08;
    const maxPieces = options.maxPieces || 3;
    const includePicks = options.includePicks !== false;

    // Explicit fromTeam/toTeam override (used by Calc-view team pickers + _suggestTrade).
    // Falls back to "fromTeam = isMyTeam, toTeam = whoever owns the target".
    let league, myTeam, otherTeam;
    if (options.fromTeam && options.toTeam) {
      myTeam = options.fromTeam;
      otherTeam = options.toTeam;
      league = options.league || null;
    } else {
      const lgInfo = options.league ? { league: options.league } : _finderGetActiveLeague();
      if (!lgInfo) return { error: 'no_league', results: [] };
      league = lgInfo.league;
      if (!league.teams || !league.teams.length) return { error: 'no_teams', results: [] };
      myTeam = league.teams.find(t => t.isMyTeam);
      if (!myTeam) return { error: 'no_my_team', results: [] };
    }

    const targetD = D[targetDIdx];
    if (!targetD) return { error: 'no_target', results: [] };

    if (!otherTeam) {
      for (const t of league.teams) {
        if (t.isMyTeam) continue;
        const hit = (t.players || []).some(n => {
          const d = _finderLookupD(n);
          return d && d.idx === targetDIdx;
        });
        if (hit) { otherTeam = t; break; }
      }
      if (!otherTeam) return { error: 'target_not_rostered', results: [] };
    } else {
      // Verify target is actually on the explicit toTeam's roster
      const onTo = (otherTeam.players || []).some(n => {
        const d = _finderLookupD(n);
        return d && d.idx === targetDIdx;
      });
      if (!onTo) return { error: 'target_not_rostered', results: [] };
    }

    const isDyn = tradeMode === 'dynasty' || tradeMode === 'dynastysf';

    function buildAssets(team) {
      const assets = [];
      (team.players || []).forEach(name => {
        const d = _finderLookupD(name);
        if (!d) return;
        const v = getPlayerValue(d);
        if (v <= 1) return;
        assets.push({ type: 'p', d, didx: d.idx, name: d.n, pos: d.s, value: v });
      });
      if (isDyn && includePicks) {
        (team.draftPicks || []).forEach(pk => {
          const v = window._getPickValue(pk.round, pk.year, pk.slot, tradeMode, pk._pickNum);
          if (v <= 1) return;
          const label = pk._pickNum
            ? (pk.year + ' ' + pk._pickNum)
            : (pk.year + ' ' + (pk.slot ? pk.slot.charAt(0).toUpperCase() + pk.slot.slice(1) + ' ' : '') + pk.round);
          assets.push({ type: 'k', pick: pk, value: v, name: label, pos: 'PICK' });
        });
      }
      return assets;
    }

    const myAssets = buildAssets(myTeam);
    const theirAssets = buildAssets(otherTeam);
    const targetAsset = theirAssets.find(a => a.type === 'p' && a.didx === targetDIdx);
    if (!targetAsset) return { error: 'target_not_found', results: [] };

    const myPosCount = {}, theirPosCount = {};
    myAssets.filter(a => a.type === 'p').forEach(a => { myPosCount[a.pos] = (myPosCount[a.pos] || 0) + 1; });
    theirAssets.filter(a => a.type === 'p').forEach(a => { theirPosCount[a.pos] = (theirPosCount[a.pos] || 0) + 1; });

    const mySorted = myAssets.slice().sort((a, b) => b.value - a.value);

    // Their-side extras to potentially throw in alongside target (cap to top 8 by value <= target)
    const theirExtras = theirAssets
      .filter(a => a !== targetAsset && a.value <= targetAsset.value)
      .sort((a, b) => b.value - a.value)
      .slice(0, 8);

    const getCombos = [[targetAsset]];
    for (let i = 0; i < theirExtras.length; i++) {
      getCombos.push([targetAsset, theirExtras[i]]);
      if (maxPieces >= 3) {
        for (let j = i + 1; j < theirExtras.length; j++) {
          getCombos.push([targetAsset, theirExtras[i], theirExtras[j]]);
        }
      }
    }

    const raw = [];

    // Archetypes (dynasty only) — used to bias scoring toward timeline-aligned trades.
    const fromArch = isDyn ? window._calcGetArchetype(myTeam, league) : null;
    const toArch = isDyn ? window._calcGetArchetype(otherTeam, league) : null;
    function _archAssetFit(asset, archetype) {
      // Positive = asset matches what this archetype wants to RECEIVE.
      if (!archetype || archetype === 'retool') return 0;
      if (asset.type === 'k') {
        return archetype === 'rebuilder' ? 0.04 : (archetype === 'contender' ? -0.02 : 0);
      }
      const age = asset.d && typeof asset.d.age === 'number' ? asset.d.age : null;
      if (age == null) return 0;
      if (archetype === 'contender' && age >= 26) return 0.03;
      if (archetype === 'rebuilder' && age <= 24) return 0.03;
      if (archetype === 'contender' && age <= 23) return -0.02;
      if (archetype === 'rebuilder' && age >= 28) return -0.02;
      return 0;
    }

    function scoreCombo(giveSide, getSide, getTotal) {
      const giveTotal = giveSide.reduce((s, a) => s + a.value, 0);
      const delta = (giveTotal - getTotal) / getTotal;
      let fit = 0;
      giveSide.forEach(a => {
        if (a.type !== 'p') return;
        if ((myPosCount[a.pos] || 0) >= 4) fit += 0.10;
        if ((theirPosCount[a.pos] || 0) <= 1) fit += 0.12;
      });
      getSide.forEach(a => {
        if (a.type !== 'p') return;
        if ((myPosCount[a.pos] || 0) <= 1) fit += 0.15;
        if ((theirPosCount[a.pos] || 0) >= 4) fit += 0.08;
      });

      // Timeline bonus — what I receive should match my archetype's wants,
      // and what I send should match other team's archetype's wants.
      let timeline = 0;
      if (fromArch && toArch && fromArch !== toArch) {
        getSide.forEach(a => { timeline += _archAssetFit(a, fromArch); });
        giveSide.forEach(a => { timeline += _archAssetFit(a, toArch); });
        timeline = Math.max(-0.15, Math.min(0.15, timeline));
      }

      const pieces = giveSide.length + getSide.length;
      const piecePenalty = Math.max(0.6, 1 - (pieces - 2) * 0.05);
      const valueMatch = Math.max(0, 1 - Math.abs(delta) / tolerance);
      return { giveTotal, delta, fit, timeline, score: valueMatch * (1 + fit + timeline) * piecePenalty };
    }

    for (const getSide of getCombos) {
      const getTotal = getSide.reduce((s, a) => s + a.value, 0);
      const minVal = getTotal * (1 - tolerance);
      const maxVal = getTotal * (1 + tolerance);

      // 1-piece give (mySorted desc)
      for (let i = 0; i < mySorted.length; i++) {
        const v = mySorted[i].value;
        if (v > maxVal) continue;
        if (v < minVal) break;
        const s = scoreCombo([mySorted[i]], getSide, getTotal);
        raw.push({ give: [mySorted[i]], get: getSide, getTotal, ...s });
      }

      // 2-piece
      if (maxPieces >= 2) {
        for (let i = 0; i < mySorted.length; i++) {
          if (mySorted[i].value >= maxVal) continue;
          for (let j = i + 1; j < mySorted.length; j++) {
            const sum = mySorted[i].value + mySorted[j].value;
            if (sum < minVal) break;
            if (sum > maxVal) continue;
            const s = scoreCombo([mySorted[i], mySorted[j]], getSide, getTotal);
            raw.push({ give: [mySorted[i], mySorted[j]], get: getSide, getTotal, ...s });
          }
        }
      }

      // 3-piece
      if (maxPieces >= 3) {
        for (let i = 0; i < mySorted.length; i++) {
          if (mySorted[i].value >= maxVal) continue;
          for (let j = i + 1; j < mySorted.length; j++) {
            const sum2 = mySorted[i].value + mySorted[j].value;
            if (sum2 >= maxVal) continue;
            for (let k = j + 1; k < mySorted.length; k++) {
              const sum3 = sum2 + mySorted[k].value;
              if (sum3 < minVal) break;
              if (sum3 > maxVal) continue;
              const s = scoreCombo([mySorted[i], mySorted[j], mySorted[k]], getSide, getTotal);
              raw.push({ give: [mySorted[i], mySorted[j], mySorted[k]], get: getSide, getTotal, ...s });
            }
          }
        }
      }
    }

    raw.sort((a, b) => b.score - a.score);
    const seen = new Set();
    const deduped = [];
    for (const r of raw) {
      const key = r.give.map(a => a.type + (a.didx || a.name)).sort().join('|') + '>' +
                  r.get.map(a => a.type + (a.didx || a.name)).sort().join('|');
      if (seen.has(key)) continue;
      seen.add(key);
      deduped.push(r);
      if (deduped.length >= 5) break;
    }

    return {
      results: deduped, otherTeam, myTeam, target: targetD,
      fromArch: isDyn ? window._calcGetArchetype(myTeam, league) : null,
      toArch: isDyn ? window._calcGetArchetype(otherTeam, league) : null
    };
  };

  // Suggest fair trades between two specific teams. Enumerates top N players on
  // toTeam as candidate targets, runs _findTrade for each, then dedupes/ranks.
  window._suggestTrade = function(fromTeam, toTeam, options) {
    options = options || {};
    if (!fromTeam || !toTeam) return { error: 'no_teams', results: [] };
    const topN = options.topN || 12;

    const candidates = (toTeam.players || [])
      .map(name => _finderLookupD(name))
      .filter(Boolean)
      .map(d => ({ d, v: getPlayerValue(d) }))
      .filter(x => x.v > 1)
      .sort((a, b) => b.v - a.v)
      .slice(0, topN);

    const all = [];
    for (const { d } of candidates) {
      const out = window._findTrade(d.idx, {
        tolerance: options.tolerance,
        maxPieces: options.maxPieces,
        includePicks: options.includePicks,
        league: options.league,
        fromTeam,
        toTeam
      });
      if (out && out.results) all.push(...out.results);
    }

    all.sort((a, b) => b.score - a.score);
    const seen = new Set();
    const deduped = [];
    for (const r of all) {
      const key = r.give.map(a => a.type + (a.didx || a.name)).sort().join('|') + '>' +
                  r.get.map(a => a.type + (a.didx || a.name)).sort().join('|');
      if (seen.has(key)) continue;
      seen.add(key);
      deduped.push(r);
      if (deduped.length >= 5) break;
    }
    return { results: deduped, myTeam: fromTeam, otherTeam: toTeam };
  };

  // Check if a player is rostered in any synced league (used by player-card button)
  window._finderHasOwner = function(dIdx) {
    const leagues = window._mtSavedLeagues || [];
    for (let li = 0; li < leagues.length; li++) {
      const lg = leagues[li];
      for (const t of (lg.teams || [])) {
        if (t.isMyTeam) continue;
        for (const name of (t.players || [])) {
          const d = _finderLookupD(name);
          if (d && d.idx === dIdx) return { leagueIdx: li, league: lg, team: t };
        }
      }
    }
    return null;
  };

  window._finderPopulateLeagueDropdown = _finderPopulateLeagueDropdown;
  function _finderPopulateLeagueDropdown() {
    const sel = document.getElementById('finderLeague');
    if (!sel) return;
    const leagues = window._mtSavedLeagues || [];
    if (!leagues.length) {
      sel.innerHTML = '<option value="">No synced leagues</option>';
      sel.disabled = true;
      return;
    }
    sel.disabled = false;
    sel.innerHTML = leagues.map((lg, i) => {
      const label = (lg.name || 'League ' + (i + 1)) + (lg.season ? ' · ' + lg.season : '');
      return '<option value="' + i + '">' + _esc(label) + '</option>';
    }).join('');
    if (_finderState.leagueIdx >= leagues.length) _finderState.leagueIdx = 0;
    sel.value = String(_finderState.leagueIdx);
  }

  function _finderRenderEmpty(msg) {
    const c = document.getElementById('finderResults');
    if (!c) return;
    const leagues = window._mtSavedLeagues || [];
    if (!leagues.length) {
      c.innerHTML = '<div class="trade-finder-empty">' +
        '<div style="font-size:2rem;margin-bottom:.5rem">📭</div>' +
        '<div style="font-family:Bebas Neue,sans-serif;font-size:1rem;letter-spacing:1.5px;margin-bottom:.5rem">NO LEAGUES SYNCED</div>' +
        '<div style="font-size:.78rem;color:var(--text2);margin-bottom:1rem">Import a Sleeper league on the My Teams page to enable the trade finder.</div>' +
        '<button onclick="document.querySelector(\'[data-page=myteams]\').click()" class="finder-run-btn">GO TO MY TEAMS</button>' +
        '</div>';
      return;
    }
    c.innerHTML = '<div class="trade-finder-empty"><div style="color:var(--text2);font-size:.85rem">' +
      _esc(msg || 'Pick a player to acquire, then click FIND TRADES.') + '</div></div>';
  }

  function _renderAssetChip(a) {
    if (a.type === 'k') {
      return '<div class="finder-asset"><span class="td-pos" style="background:#7c3aed;color:#fff">PICK</span><span>' + _esc(a.name) + '</span><span class="td-val">' + a.value + '</span></div>';
    }
    return '<div class="finder-asset"><span class="td-pos ' + a.d.s + '">' + a.d.s + '</span><span>' + _esc(a.d.n) + '</span><span class="td-val">' + a.value + '</span></div>';
  }

  function _finderRenderResults(out) {
    const c = document.getElementById('finderResults');
    if (!c) return;
    if (out.error) {
      const msgs = {
        no_league: 'No league synced — import one on the My Teams page first.',
        no_teams: 'League has no teams.',
        no_my_team: 'Couldn\'t find your team in this league. Make sure your Sleeper account is detected on the My Teams page.',
        no_target: 'Player not found.',
        target_not_rostered: 'That player isn\'t on a roster in this league.',
        target_not_found: 'Target not found on owner\'s roster.'
      };
      c.innerHTML = '<div class="trade-finder-empty"><div style="color:var(--text2)">' + (msgs[out.error] || out.error) + '</div></div>';
      return;
    }
    if (!out.results.length) {
      c.innerHTML = '<div class="trade-finder-empty">' +
        '<div style="font-family:Bebas Neue,sans-serif;font-size:1rem;letter-spacing:1.5px;margin-bottom:.5rem">NO MATCHES</div>' +
        '<div style="font-size:.8rem;color:var(--text2)">Try widening the tolerance slider, or pick a different target.</div></div>';
      return;
    }
    let html = '<div class="trade-finder-header">' +
      '<span style="font-family:Bebas Neue,sans-serif;letter-spacing:1.5px;font-size:.9rem">' + out.results.length + ' TRADE' + (out.results.length === 1 ? '' : 'S') + ' FOUND</span>' +
      '<span style="font-size:.72rem;color:var(--text2)">Target owner: <b style="color:var(--text)">' + _esc(out.otherTeam.owner) + '</b>' +
        (out.toArch ? ' <span class="team-arch-badge team-arch-' + out.toArch + '" style="margin-left:6px">' + (_ARCH_ICON[out.toArch] || '') + ' ' + (_ARCH_LABEL[out.toArch] || out.toArch) + '</span>' : '') +
        (out.fromArch && out.fromArch !== out.toArch ? ' <span style="color:var(--text2);margin-left:4px">· you: <b style="color:var(--text)">' + (_ARCH_LABEL[out.fromArch] || out.fromArch) + '</b></span>' : '') +
      '</span>' +
      '</div>';
    out.results.forEach((r, i) => {
      const deltaPct = Math.round(r.delta * 100);
      const deltaLabel = Math.abs(deltaPct) <= 1
        ? 'EVEN'
        : (deltaPct > 0 ? '+' + deltaPct + '% your side overpays' : deltaPct + '% (you come out ahead)');
      const deltaColor = Math.abs(deltaPct) <= 3 ? 'var(--text2)' : (deltaPct < 0 ? 'var(--green)' : 'var(--accent)');
      const giveHtml = r.give.map(_renderAssetChip).join('');
      const getHtml = r.get.map(_renderAssetChip).join('');
      const getTotal = Math.round(r.getTotal || r.get.reduce((s, a) => s + a.value, 0));
      html += '<div class="finder-result-card">' +
        '<div class="finder-result-sides">' +
          '<div class="finder-side">' +
            '<div class="finder-side-label">YOU SEND</div>' + giveHtml +
            '<div class="finder-side-total">TOTAL ' + r.giveTotal + '</div>' +
          '</div>' +
          '<div class="finder-arrow">⇄</div>' +
          '<div class="finder-side">' +
            '<div class="finder-side-label">YOU GET</div>' + getHtml +
            '<div class="finder-side-total">TOTAL ' + getTotal + '</div>' +
          '</div>' +
        '</div>' +
        '<div class="finder-result-meta">' +
          '<span style="color:' + deltaColor + ';font-weight:600">' + deltaLabel + '</span>' +
          (r.fit > 0.2 ? '<span style="color:var(--green);margin-left:.75rem">✓ mutual fit</span>' : '') +
          '<button class="finder-load-btn" data-load-idx="' + i + '">LOAD INTO CALCULATOR</button>' +
        '</div>' +
      '</div>';
    });
    c.innerHTML = html;
    c.querySelectorAll('.finder-load-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const idx = parseInt(btn.dataset.loadIdx);
        _finderLoadIntoCalc(out.results[idx]);
      });
    });
  }

  function _finderRun() {
    if (_finderState.targetDIdx == null) { _finderRenderEmpty(); return; }
    const tolInput = document.getElementById('finderTolerance');
    const tolerance = tolInput ? (parseInt(tolInput.value) / 100) : 0.08;
    const lgInfo = _finderGetActiveLeague();
    const out = window._findTrade(_finderState.targetDIdx, {
      tolerance,
      league: lgInfo ? lgInfo.league : null
    });
    _finderRenderResults(out);
  }

  function _finderLoadIntoCalc(r) {
    sideA.players = []; sideA.picks = [];
    sideB.players = []; sideB.picks = [];
    r.give.forEach(a => {
      if (a.type === 'p') sideA.players.push(a.didx);
      else if (a.type === 'k') sideA.picks.push({ round: a.pick.round, year: a.pick.year, slot: a.pick.slot, _pickNum: a.pick._pickNum, original: a.pick.original });
    });
    r.get.forEach(a => {
      if (a.type === 'p') sideB.players.push(a.didx);
      else if (a.type === 'k') sideB.picks.push({ round: a.pick.round, year: a.pick.year, slot: a.pick.slot, _pickNum: a.pick._pickNum, original: a.pick.original });
    });
    const calcTab = document.querySelector('.trade-view-tab[data-tview="calc"]');
    if (calcTab) calcTab.click();
    renderAll();
    if (typeof _calcRenderRealPicks === 'function') { _calcRenderRealPicks('a'); _calcRenderRealPicks('b'); }
    if (typeof toast === 'function') toast('Loaded — tweak as needed');
  }

  // Target search autocomplete — scoped to rostered players in selected league (excluding your team)
  (function _setupFinderTargetSearch() {
    const input = document.getElementById('finderTargetSearch');
    const drop = document.getElementById('finderTargetDrop');
    if (!input || !drop) return;
    let debounce = null;
    input.addEventListener('input', () => {
      _finderState.targetDIdx = null;
      clearTimeout(debounce);
      debounce = setTimeout(() => {
        const q = input.value.trim().toLowerCase();
        if (q.length < 2) { drop.classList.remove('show'); return; }
        const lgInfo = _finderGetActiveLeague();
        if (!lgInfo) { drop.classList.remove('show'); return; }
        const seenIdx = new Set();
        const candidates = [];
        (lgInfo.league.teams || []).forEach(t => {
          if (t.isMyTeam) return;
          (t.players || []).forEach(name => {
            const d = _finderLookupD(name);
            if (!d || seenIdx.has(d.idx)) return;
            if (!d.n.toLowerCase().includes(q)) return;
            seenIdx.add(d.idx);
            candidates.push({ d, ownerName: t.owner || 'Team' });
          });
        });
        candidates.sort((a, b) => getPlayerValue(b.d) - getPlayerValue(a.d));
        const matches = candidates.slice(0, 8);
        if (!matches.length) { drop.classList.remove('show'); return; }
        drop.innerHTML = matches.map(({ d, ownerName }) => {
          const val = getPlayerValue(d);
          return '<div class="trade-drop-item" data-idx="' + d.idx + '">' +
            '<span class="td-pos ' + d.s + '">' + d.s + '</span><span>' + _esc(d.n) + '</span>' +
            '<span class="td-team" title="Owned by ' + _esc(ownerName) + '">' + _esc(String(ownerName).slice(0, 14)) + '</span>' +
            '<span class="td-val">' + val + '</span></div>';
        }).join('');
        drop.classList.add('show');
        drop.querySelectorAll('.trade-drop-item').forEach(item => {
          item.addEventListener('click', () => {
            const idx = parseInt(item.dataset.idx);
            _finderState.targetDIdx = idx;
            if (D[idx]) input.value = D[idx].n;
            drop.classList.remove('show');
            _finderRun();
          });
        });
      }, 150);
    });
    input.addEventListener('blur', () => { setTimeout(() => drop.classList.remove('show'), 200); });
    input.addEventListener('focus', () => { if (input.value.trim().length >= 2) input.dispatchEvent(new Event('input')); });
  })();

  // View toggle
  document.querySelectorAll('.trade-view-tab').forEach(btn => {
    btn.addEventListener('click', () => {
      const view = btn.dataset.tview;
      document.querySelectorAll('.trade-view-tab').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      const calcEl = document.getElementById('tradeCalcView');
      const findEl = document.getElementById('tradeFinderView');
      if (calcEl) calcEl.style.display = view === 'calc' ? '' : 'none';
      if (findEl) findEl.style.display = view === 'finder' ? '' : 'none';
      if (view === 'finder') {
        _finderPopulateLeagueDropdown();
        if (_finderState.targetDIdx != null) _finderRun();
        else _finderRenderEmpty();
      }
    });
  });

  // League change → reset target, re-render
  const _finderLeagueSel = document.getElementById('finderLeague');
  if (_finderLeagueSel) {
    _finderLeagueSel.addEventListener('change', () => {
      _finderState.leagueIdx = parseInt(_finderLeagueSel.value) || 0;
      _finderState.targetDIdx = null;
      const ti = document.getElementById('finderTargetSearch');
      if (ti) ti.value = '';
      _finderRenderEmpty();
    });
  }

  // Tolerance slider
  const _finderTol = document.getElementById('finderTolerance');
  const _finderTolLbl = document.getElementById('finderTolVal');
  if (_finderTol && _finderTolLbl) {
    _finderTol.addEventListener('input', () => { _finderTolLbl.textContent = '±' + _finderTol.value + '%'; });
    _finderTol.addEventListener('change', () => { if (_finderState.targetDIdx != null) _finderRun(); });
  }

  // Run button
  const _finderRunBtn = document.getElementById('finderRunBtn');
  if (_finderRunBtn) _finderRunBtn.addEventListener('click', _finderRun);

  // Re-run when mode or source changes (only if finder is visible + target selected)
  function _finderMaybeReRun() {
    const findEl = document.getElementById('tradeFinderView');
    if (findEl && findEl.style.display !== 'none' && _finderState.targetDIdx != null) {
      setTimeout(_finderRun, 0);
    }
  }
  document.querySelectorAll('.trade-mode-tab').forEach(b => b.addEventListener('click', _finderMaybeReRun));
  document.querySelectorAll('.trade-src-tab').forEach(b => b.addEventListener('click', _finderMaybeReRun));
  // Archetype labels + real-pick adder both depend on tradeMode being dynasty —
  // refresh them when mode changes.
  document.querySelectorAll('.trade-mode-tab').forEach(b => b.addEventListener('click', () => {
    setTimeout(() => {
      _calcRefreshTeamOptionLabels();
      _calcUpdateSideLabels();
      _calcRenderRealPicks('a');
      _calcRenderRealPicks('b');
    }, 0);
  }));

  // Public entrypoint for the player-card button
  window._finderShowAndRun = function(targetDIdx) {
    const leagues = window._mtSavedLeagues || [];
    if (!leagues.length) {
      if (typeof toast === 'function') toast('Import a Sleeper league on My Teams first');
      return false;
    }
    // Switch to trade page first
    const navBtn = document.querySelector('.nav-btn[data-page="trade"]');
    if (navBtn) navBtn.click();
    // Click finder view tab
    const viewTab = document.querySelector('.trade-view-tab[data-tview="finder"]');
    if (viewTab) viewTab.click();
    // Set target + run
    _finderState.targetDIdx = targetDIdx;
    const input = document.getElementById('finderTargetSearch');
    if (input && D[targetDIdx]) input.value = D[targetDIdx].n;
    _finderRun();
    return true;
  };

  // ═══════════════════════════════════════════════════════════
  // CALC VIEW — league + team pickers (shared state with FIND TRADE)
  // ═══════════════════════════════════════════════════════════
  const _calcLeagueSel = document.getElementById('calcLeague');
  const _calcTeamA = document.getElementById('calcTeamA');
  const _calcTeamB = document.getElementById('calcTeamB');
  const _calcSuggestBtn = document.getElementById('calcSuggestBtn');
  const _calcPicker = document.getElementById('calcLeaguePicker');
  const _calcTeamRow = document.getElementById('calcTeamPickerRow');

  function _calcBuildRosterFilter(team) {
    if (!team) return null;
    const idxSet = new Set();
    (team.players || []).forEach(name => {
      const d = _finderLookupD(name);
      if (d) idxSet.add(d.idx);
    });
    return { idxSet, owner: team.owner || 'Team', team, pickCount: (team.draftPicks || []).length };
  }

  function _calcUpdateSideLabels() {
    const labelA = document.querySelector('#tradeCalcView .trade-side-label.side-a');
    const labelB = document.querySelector('#tradeCalcView .trade-side-label.side-b');
    const isDyn = (tradeMode === 'dynasty' || tradeMode === 'dynastysf');
    const leagues = window._mtSavedLeagues || [];
    const lg = leagues[_finderState.leagueIdx];
    function archBadge(team, sideLetter) {
      if (!isDyn || !team) return '';
      const arch = window._calcGetArchetype(team, lg);
      const override = window._calcGetArchOverride(lg, team);
      if (!arch) return '';
      const cls = 'team-arch-' + arch;
      const icon = _ARCH_ICON[arch] || '';
      const lbl = _ARCH_LABEL[arch] || arch;
      const tipPrefix = (override === 'auto' || !override) ? 'Auto-detected · ' : 'Manual · ';
      return '<span class="team-arch-badge ' + cls + '" data-arch-side="' + sideLetter + '" title="' + tipPrefix + 'Click to cycle">' + icon + ' ' + lbl + '</span>';
    }
    function fmt(f, sideLetter) {
      const sub = f.idxSet.size + ' player' + (f.idxSet.size === 1 ? '' : 's') + (f.pickCount ? ' · ' + f.pickCount + ' pick' + (f.pickCount === 1 ? '' : 's') : '');
      return _esc(f.owner) + ' <span style="display:block;font-size:.6rem;color:var(--text2);font-weight:normal;letter-spacing:1px;margin-top:2px">' + sub + '</span>' + archBadge(f.team, sideLetter);
    }
    if (labelA) labelA.innerHTML = _calcSideFilters.a ? fmt(_calcSideFilters.a, 'a') : 'TEAM A';
    if (labelB) labelB.innerHTML = _calcSideFilters.b ? fmt(_calcSideFilters.b, 'b') : 'TEAM B';
    // Wire badge click → cycle override (auto → contender → retool → rebuilder → auto)
    document.querySelectorAll('#tradeCalcView .team-arch-badge[data-arch-side]').forEach(b => {
      b.addEventListener('click', () => {
        const side = b.dataset.archSide;
        const f = _calcSideFilters[side];
        if (!f) return;
        const cur = window._calcGetArchOverride(lg, f.team);
        const next = _ARCH_VALUES[(_ARCH_VALUES.indexOf(cur) + 1) % _ARCH_VALUES.length];
        window._calcSetArchOverride(lg, f.team, next);
        _calcUpdateSideLabels();
        _calcRefreshTeamOptionLabels();
      });
    });
  }

  // Refresh the option text in calcTeamA / calcTeamB without resetting selection,
  // so archetype overrides applied via badge click show up in the dropdowns too.
  function _calcRefreshTeamOptionLabels() {
    const leagues = window._mtSavedLeagues || [];
    const lg = leagues[_finderState.leagueIdx];
    if (!lg || !lg.teams) return;
    const isDyn = (tradeMode === 'dynasty' || tradeMode === 'dynastysf');
    [_calcTeamA, _calcTeamB].forEach(sel => {
      if (!sel) return;
      Array.from(sel.options).forEach(opt => {
        if (opt.value === '') return;
        const t = lg.teams[parseInt(opt.value)];
        if (!t) return;
        const star = t.isMyTeam ? '⭐ ' : '';
        const archStr = isDyn ? (() => {
          const a = window._calcGetArchetype(t, lg);
          return a ? ' — ' + (_ARCH_LABEL[a] || a) : '';
        })() : '';
        opt.text = star + (t.owner || 'Team') + archStr;
      });
    });
  }

  function _calcApplyTeamFilters() {
    const leagues = window._mtSavedLeagues || [];
    const lg = leagues[_finderState.leagueIdx];
    if (!lg) {
      _calcSideFilters.a = null;
      _calcSideFilters.b = null;
    } else {
      const aIdx = _calcTeamA ? _calcTeamA.value : '';
      const bIdx = _calcTeamB ? _calcTeamB.value : '';
      _calcSideFilters.a = (aIdx !== '' && lg.teams[+aIdx]) ? _calcBuildRosterFilter(lg.teams[+aIdx]) : null;
      _calcSideFilters.b = (bIdx !== '' && lg.teams[+bIdx]) ? _calcBuildRosterFilter(lg.teams[+bIdx]) : null;
    }
    _calcUpdateSideLabels();
    if (_calcSuggestBtn) {
      _calcSuggestBtn.style.display = (_calcSideFilters.a && _calcSideFilters.b) ? '' : 'none';
    }
    _calcRenderRealPicks('a');
    _calcRenderRealPicks('b');
  }

  // When a team is selected on a side in dynasty mode, replace the generic
  // 1st/2nd/3rd/4th + Early/Mid/Late pick adder with the team's actual owned picks
  // (post-trades). Clicking a real pick adds it with its exact pickNum so the
  // value reflects WHICH pick it is, not just the round + slot heuristic.
  function _calcRenderRealPicks(sideLetter) {
    const section = document.getElementById('tradePickSection' + sideLetter.toUpperCase());
    if (!section) return;
    const yearTabs = section.querySelector('.trade-pick-year-tabs');
    const roundBtns = section.querySelector('.trade-pick-btns');
    let realEl = section.querySelector('.trade-real-picks');
    if (!realEl) {
      realEl = document.createElement('div');
      realEl.className = 'trade-real-picks';
      section.appendChild(realEl);
    }
    const isDyn = (tradeMode === 'dynasty' || tradeMode === 'dynastysf');
    const filter = _calcSideFilters[sideLetter];
    if (!isDyn || !filter || !filter.team || !(filter.team.draftPicks || []).length) {
      if (yearTabs) yearTabs.style.display = '';
      if (roundBtns) roundBtns.style.display = '';
      realEl.style.display = 'none';
      realEl.innerHTML = '';
      return;
    }
    const team = filter.team;
    const sideArr = sideLetter === 'a' ? sideA.picks : sideB.picks;
    const usedKeys = new Set(sideArr.map(p => p.year + ':' + p.round + ':' + (p._pickNum || p.slot)));
    const available = (team.draftPicks || [])
      .filter(pk => !usedKeys.has(pk.year + ':' + pk.round + ':' + (pk._pickNum || pk.slot)))
      .slice()
      .sort((a, b) => {
        if (a.year !== b.year) return parseInt(a.year) - parseInt(b.year);
        const rO = { '1st': 1, '2nd': 2, '3rd': 3, '4th': 4 };
        return (rO[a.round] || 5) - (rO[b.round] || 5);
      });
    if (yearTabs) yearTabs.style.display = 'none';
    if (roundBtns) roundBtns.style.display = 'none';
    realEl.style.display = '';
    if (!available.length) {
      realEl.innerHTML = '<div style="font-size:.7rem;color:var(--text2);text-align:center;padding:.5rem">All of ' + _esc(team.owner || 'this team') + '’s picks are already in the trade.</div>';
      return;
    }
    let html = '<div style="font-size:.6rem;color:var(--text2);font-family:Bebas Neue,sans-serif;letter-spacing:1.2px;margin-bottom:5px">' + _esc((team.owner || 'TEAM').toUpperCase()) + '’S PICKS</div>';
    html += '<div class="trade-real-picks-grid">';
    available.forEach((pk, i) => {
      const val = getPickValue(pk.round, pk.year, pk.slot, pk._pickNum);
      const label = pk._pickNum ? (pk.year + ' ' + pk._pickNum) : (pk.year + ' ' + slotLabel(pk.slot) + ' ' + pk.round);
      const via = pk.original && pk.original !== team.owner ? ' · via ' + pk.original : '';
      html += '<button type="button" class="real-pick-btn" data-rpidx="' + i + '" data-side="' + sideLetter + '" title="' + _esc(label + via + ' · value ' + val) + '">' +
        '<span class="rp-label">' + _esc(label) + '</span>' +
        '<span class="rp-val">' + val + '</span>' +
        '</button>';
    });
    html += '</div>';
    realEl.innerHTML = html;
    realEl.querySelectorAll('.real-pick-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const idx = parseInt(btn.dataset.rpidx);
        const pk = available[idx];
        const side = sideLetter === 'a' ? sideA : sideB;
        side.picks.push({
          round: pk.round, year: pk.year, slot: pk.slot,
          _pickNum: pk._pickNum, original: pk.original
        });
        renderAll();
        _calcRenderRealPicks(sideLetter);
      });
    });
  }
  window._calcRenderRealPicks = _calcRenderRealPicks;

  function _calcPopulateTeams() {
    const leagues = window._mtSavedLeagues || [];
    const lg = leagues[_finderState.leagueIdx];
    if (!lg || !lg.teams || !lg.teams.length) {
      if (_calcTeamRow) _calcTeamRow.style.display = 'none';
      _calcApplyTeamFilters();
      return;
    }
    if (_calcTeamRow) _calcTeamRow.style.display = '';
    const isDyn = (tradeMode === 'dynasty' || tradeMode === 'dynastysf');
    const opts = ['<option value="">— Any player —</option>'];
    lg.teams.forEach((t, i) => {
      const star = t.isMyTeam ? '⭐ ' : '';
      let archStr = '';
      if (isDyn) {
        const arch = window._calcGetArchetype(t, lg);
        if (arch) archStr = ' — ' + (_ARCH_LABEL[arch] || arch);
      }
      opts.push('<option value="' + i + '">' + star + _esc((t.owner || 'Team ' + (i + 1)) + archStr) + '</option>');
    });
    if (_calcTeamA) _calcTeamA.innerHTML = opts.join('');
    if (_calcTeamB) _calcTeamB.innerHTML = opts.join('');
    // Default Team A to user's team, Team B blank
    const myIdx = lg.teams.findIndex(t => t.isMyTeam);
    if (_calcTeamA) _calcTeamA.value = myIdx >= 0 ? String(myIdx) : '';
    if (_calcTeamB) _calcTeamB.value = '';
    _calcApplyTeamFilters();
  }

  function _calcPopulateLeagues() {
    const leagues = window._mtSavedLeagues || [];
    if (!leagues.length) {
      if (_calcPicker) _calcPicker.style.display = 'none';
      _calcApplyTeamFilters();
      return;
    }
    if (_calcPicker) _calcPicker.style.display = '';
    if (_calcLeagueSel) {
      _calcLeagueSel.innerHTML = leagues.map((lg, i) => {
        const label = (lg.name || 'League ' + (i + 1)) + (lg.season ? ' · ' + lg.season : '');
        return '<option value="' + i + '">' + _esc(label) + '</option>';
      }).join('');
      if (_finderState.leagueIdx >= leagues.length) _finderState.leagueIdx = 0;
      _calcLeagueSel.value = String(_finderState.leagueIdx);
    }
    _calcPopulateTeams();
  }

  if (_calcLeagueSel) {
    _calcLeagueSel.addEventListener('change', () => {
      _finderState.leagueIdx = parseInt(_calcLeagueSel.value) || 0;
      // Sync FIND TRADE tab
      const flSel = document.getElementById('finderLeague');
      if (flSel && flSel.value !== _calcLeagueSel.value) {
        flSel.value = _calcLeagueSel.value;
        // Reset finder target since league changed
        _finderState.targetDIdx = null;
        const ti = document.getElementById('finderTargetSearch');
        if (ti) ti.value = '';
      }
      _calcPopulateTeams();
    });
  }
  if (_calcTeamA) _calcTeamA.addEventListener('change', _calcApplyTeamFilters);
  if (_calcTeamB) _calcTeamB.addEventListener('change', _calcApplyTeamFilters);

  // Sync from FIND TRADE → Calc when finder's league changes
  const _flSelInit = document.getElementById('finderLeague');
  if (_flSelInit) {
    _flSelInit.addEventListener('change', () => {
      if (_calcLeagueSel && _calcLeagueSel.value !== _flSelInit.value) {
        _calcLeagueSel.value = _flSelInit.value;
        _calcPopulateTeams();
      }
    });
  }

  // SUGGEST FAIR TRADE — auto-load top result into the calculator
  if (_calcSuggestBtn) {
    _calcSuggestBtn.addEventListener('click', () => {
      const fA = _calcSideFilters.a;
      const fB = _calcSideFilters.b;
      if (!fA || !fB) return;
      const lg = (window._mtSavedLeagues || [])[_finderState.leagueIdx];
      _calcSuggestBtn.disabled = true;
      _calcSuggestBtn.textContent = 'SEARCHING...';
      setTimeout(() => {
        try {
          const out = window._suggestTrade(fA.team, fB.team, { league: lg, tolerance: 0.10 });
          if (!out || out.error || !out.results || !out.results.length) {
            if (typeof toast === 'function') toast('No balanced trades found — try widening tolerance');
            return;
          }
          const r = out.results[0];
          sideA.players = []; sideA.picks = [];
          sideB.players = []; sideB.picks = [];
          r.give.forEach(a => {
            if (a.type === 'p') sideA.players.push(a.didx);
            else if (a.type === 'k') sideA.picks.push({ round: a.pick.round, year: a.pick.year, slot: a.pick.slot, _pickNum: a.pick._pickNum, original: a.pick.original });
          });
          r.get.forEach(a => {
            if (a.type === 'p') sideB.players.push(a.didx);
            else if (a.type === 'k') sideB.picks.push({ round: a.pick.round, year: a.pick.year, slot: a.pick.slot, _pickNum: a.pick._pickNum, original: a.pick.original });
          });
          renderAll();
          _calcRenderRealPicks('a'); _calcRenderRealPicks('b');
          if (typeof toast === 'function') toast('Top suggestion loaded — ' + out.results.length + ' total found');
        } finally {
          _calcSuggestBtn.disabled = false;
          _calcSuggestBtn.textContent = 'SUGGEST FAIR TRADE';
        }
      }, 30);
    });
  }

  // Expose so My Teams can refresh us after league import/delete
  window._calcRefreshLeagues = _calcPopulateLeagues;

  // Populate on load + whenever Firebase auth resolves (leagues load async)
  _calcPopulateLeagues();
  _whenFirebaseReady(function(){
    if (typeof firebase !== 'undefined' && firebase.auth) {
      try {
        firebase.auth().onAuthStateChanged(function(user) {
          if (user) setTimeout(() => { _calcPopulateLeagues(); _finderPopulateLeagueDropdown(); }, 800);
        });
      } catch (_e) {}
    }
  });

  renderAll();
})();


