            const hp = String(_cbAny.ht).replace(/['"]/g,'').split('-');
            if (hp.length === 2) { const f=parseInt(hp[0]), i=parseInt(hp[1]); if (!isNaN(f)&&!isNaN(i)) _htIn = f*12+i; }
