      // Calculate season-level stats
      let totalGp = 0, bestPpg = 0, bestFpts = 0;
      let totFpts = 0;
      // Aggregated totals
      let totPy = 0, totRy = 0, totRcy = 0, totRec = 0, totPtd = 0, totRtd = 0, totRctd = 0, totInt = 0, totRa = 0;
      let totPc = 0, totPa = 0; // completions and attempts for QB completion %

