        dr, breakoutAge, breakoutPpg, boThresh, tm: tmScore, preBreakoutTm, ht: htInches, wt: wt,
        bestPpg, bestFpts, totFpts, fptsPerGame,
        totPy, totRy, totRcy, totRec, totalTd, totRa,
        pasYpg, rushYpg, recYpg, recPg, tdPg,
        totPtd, totRtd, totRctd, totInt,
        ypc, ypr,
        mktShare, improvSlope, qbRushFppg,
        domRate, numSeasons, qbDrVal, schoolDraftCount,
        qbCompPct, qbIntRate, teRecPg, pffGrade, pffRush,
        pffRisk: (pos === 'QB' && window._PFF_QB_RISK && window._PFF_QB_RISK[name]) ? window._PFF_QB_RISK[name] : 0,
        isCollege,
