        prospectRecord.jmCeil = _jmResult.ceilFinal;
        prospectRecord.compScores = _jmResult.compScores;
        prospectRecord.bustAdj = _jmResult.bustAdj;
        prospectRecord.sleeperAdj = _jmResult.sleeperAdj;
        prospectRecord.dataCoverage = _jmResult.dataCoverage;
        prospectRecord.lowConfidence = _jmResult.lowConfidence;
