  // ===== END BULK DC ENTRY =====

  // ===== BULK RAS ENTRY (admin-only) =====
  // Parse a line or CSV row into {name, ras}. Accepts:
  //   "Carson Beck, 7.82"
  //   "Carson Beck\t7.82"
  //   "Carson Beck 7.82"
  //   RAS.football CSV rows: "Link,Name,Pos,Year,College,RAS,ALLTIME"
  // Returns null if unparseable.
  function _pmParseRasLine(raw) {
    const trimmed = String(raw || '').trim();
    if (!trimmed) return null;
    // Skip RAS.football CSV header
    if (/^"?Link"?\s*,/i.test(trimmed)) return null;
    // CSV-style: at least 2 comma fields, try to find a name column and a RAS number
    if (trimmed.indexOf(',') !== -1) {
      // naive CSV split — handle quoted fields
      const parts = [];
      let cur = '', inQ = false;
      for (let i = 0; i < trimmed.length; i++) {
        const ch = trimmed[i];
        if (ch === '"') { inQ = !inQ; continue; }
        if (ch === ',' && !inQ) { parts.push(cur); cur = ''; continue; }
        cur += ch;
      }
      parts.push(cur);
      const cleaned = parts.map(s => s.trim());
      // RAS.football format: [Link, Name, Pos, Year, College, RAS, ALLTIME]
      if (cleaned.length >= 6 && /^20\d\d$/.test(cleaned[3])) {
        const name = cleaned[1];
        const ras = cleaned[5];
        if (name && ras && !isNaN(parseFloat(ras))) {
          return { name, ras: parseFloat(ras), year: cleaned[3] };
        }
        if (name && (ras === '' || isNaN(parseFloat(ras)))) {
          return { name, ras: null, year: cleaned[3], reason: 'blank-ras' };
        }
      }
      // Generic "Name, 7.82" or "Name, Pos, 7.82"
      if (cleaned.length === 2 && !isNaN(parseFloat(cleaned[1]))) {
        return { name: cleaned[0], ras: parseFloat(cleaned[1]) };
      }
      if (cleaned.length >= 3) {
        // find the last numeric field as RAS
        for (let k = cleaned.length - 1; k >= 1; k--) {
          const v = parseFloat(cleaned[k]);
          if (!isNaN(v)) {
            return { name: cleaned[0], ras: v };
          }
        }
      }
    }
    // Space/tab-delimited: "Name 7.82"
    const m = trimmed.match(/^(.+?)[\s\t]+([\d.]+)$/);
    if (m) {
      const v = parseFloat(m[2]);
      if (!isNaN(v)) return { name: m[1].trim(), ras: v };
    }
    return null;
  }

  // Parse full bulk-RAS paste. Returns array of {lineNo, raw, name, ras, status, canonical}
  //   status: 'ok' | 'unmatched' | 'out-of-range' | 'blank-ras' | 'unparsed'
  function _pmParseBulkRas(text) {
    const { idx, lastFirst } = _pmBuild2026Index();
    const out = [];
    const lines = String(text || '').split(/\r?\n/);
    for (let i = 0; i < lines.length; i++) {
      const raw = lines[i];
      if (!raw.trim()) continue;
      const parsed = _pmParseRasLine(raw);
      if (!parsed) {
        out.push({ lineNo: i+1, raw, name: raw.trim(), ras: null, status: 'unparsed' });
        continue;
      }
      if (parsed.reason === 'blank-ras') {
        out.push({ lineNo: i+1, raw, name: parsed.name, ras: null, status: 'blank-ras' });
        continue;
      }
      if (parsed.ras == null || parsed.ras < 0 || parsed.ras > 10) {
        out.push({ lineNo: i+1, raw, name: parsed.name, ras: parsed.ras, status: 'out-of-range' });
        continue;
      }
      // Match to canonical 2026 name
      const norm = _pmNormName(parsed.name);
      let canonical = idx[norm] || null;
      if (!canonical) {
        const parts = parsed.name.replace(/\s+(Jr\.?|Sr\.?|II|III|IV|V)\.?$/i, '').trim().split(/\s+/);
        if (parts.length >= 2) {
          const last = parts[parts.length - 1].toLowerCase().replace(/[^a-z0-9]/g, '');
          const firstInit = parts[0][0].toLowerCase();
          const key = last + ':' + firstInit;
          if (lastFirst[key]) canonical = lastFirst[key];
        }
      }
      if (!canonical) {
        out.push({ lineNo: i+1, raw, name: parsed.name, ras: parsed.ras, status: 'unmatched' });
        continue;
      }
      out.push({ lineNo: i+1, raw, name: parsed.name, ras: parsed.ras, status: 'ok', canonical });
    }
    return out;
  }

  // Apply parsed RAS rows — dedupe last-write-wins on canonical name, then
  // batch Firestore writes + single cache bust + one render.
  function _pmApplyBulkRas(parsed) {
    const okRows = parsed.filter(r => r.status === 'ok');
    const byName = {};
    okRows.forEach(r => { byName[r.canonical] = r.ras; });
    const names = Object.keys(byName);
    if (!names.length) return 0;
    names.forEach(function(n) {
      const val = byName[n];
      // _bioSave stores the edit in Firestore AND updates COMBINE_DATA at runtime
      _bioSave(n, 'ras', String(val));
      // JM cache is keyed by name + pos + dr — clear all entries for this player
      if (typeof _jmCache !== 'undefined') {
        const prefix = n + '::';
        Object.keys(_jmCache).forEach(k => { if (k.indexOf(prefix) === 0) delete _jmCache[k]; });
      }
    });
    _pmBuildCache = null;
    pmBuiltData = buildProspectData();
    renderTable();
    return names.length;
  }

