      const boT = (_dBoThresh[d.s] || 12) * _dBoScale;
      const boTSoft = boT * 0.75;
      let breakoutYr = null;
      collegeSeasons.forEach(s => {
        if (s.ppg >= boTSoft && (!breakoutYr || s.yr < breakoutYr)) breakoutYr = s.yr;
      });
