  function _triviaApplyTemplate(t) {
    if (!t || !t.filters) return;
    // Clear any in-flight daily run when a regular template is applied
    // directly (not via _triviaPlayDaily, which sets _triviaDailyRun AFTER
    // calling this function). Prevents a stale daily flag from finalizing
    // a different board's score against today's date.
    if (!t._isDailyApply) { _triviaDailyRun = null; }
    const f = t.filters;
    const setVal = (id, v) => { const el = document.getElementById(id); if (el && v != null) { el.value = v; el.dispatchEvent(new Event('change', { bubbles: true })); } };
    setVal('triviaFilterType', f.type);
    setVal('triviaFilterStat', f.stat);
    setVal('triviaFilterYear', f.year);
    setVal('triviaFilterEra', f.era || 'all');
    setVal('triviaFilterCount', String(f.count));
    setVal('triviaFilterConf', f.conf || 'all');
    setVal('triviaFilterTeam', f.team || 'all');
    if (f.draftRound != null) setVal('triviaFilterDraftRound', f.draftRound);
    // Default to regular season unless the template explicitly says postseason.
    setVal('triviaFilterSeasonType', f.seasonType || 'reg');

    // Position checkboxes — sync each one's checked state and fire change so the
    // existing label-styling handler updates ✓/✗ visuals.
    const wanted = new Set(f.positions || ['QB','RB','WR','TE']);
    const wrap = document.getElementById('triviaFilterPos');
    if (wrap) {
      wrap.querySelectorAll('input[type="checkbox"]').forEach(cb => {
        const should = wanted.has(cb.value);
        if (cb.checked !== should) {
          cb.checked = should;
          cb.dispatchEvent(new Event('change', { bubbles: true }));
        }
      });
    }

    // Make sure custom-prompt mode is OFF so structured filters are used.
    const cust = document.getElementById('triviaCustomPromptToggle');
    if (cust && cust.checked) { cust.checked = false; cust.dispatchEvent(new Event('change', { bubbles: true })); }

    if (typeof window._triviaGenerate === 'function') window._triviaGenerate();
    // Scroll the board into view after a brief layout settle
    setTimeout(() => {
      const board = document.getElementById('triviaBoardArea');
      if (board) board.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }, 250);
  }

  function _triviaRenderTemplates() {
    const grid = document.getElementById('triviaTemplateGrid');
    if (!grid) return;
    grid.innerHTML = _TRIVIA_TEMPLATES.map((t, i) =>
      '<button class="trivia-tpl-btn" data-tplidx="' + i + '" '
        + 'style="text-align:left;padding:10px 12px;background:var(--bg);border:1px solid var(--border);border-radius:8px;color:var(--text);cursor:pointer;transition:all .15s" '
        + 'onmouseover="this.style.borderColor=\'var(--accent)\';this.style.background=\'rgba(168,85,247,.06)\'" '
        + 'onmouseout="this.style.borderColor=\'var(--border)\';this.style.background=\'var(--bg)\'">'
        + '<div style="font-family:\'Bebas Neue\',sans-serif;font-size:.85rem;letter-spacing:1px;color:var(--text);margin-bottom:2px">' + escapeHTML(t.title) + '</div>'
        + '<div style="font-size:.65rem;color:var(--text2)">' + escapeHTML(t.desc) + '</div>'
      + '</button>'
    ).join('');
    grid.querySelectorAll('.trivia-tpl-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const i = parseInt(btn.dataset.tplidx, 10);
        _triviaApplyTemplate(_TRIVIA_TEMPLATES[i]);
      });
    });
  }
  _triviaRenderTemplates();

  // ===== DAILY BOARD =====
  // Deterministic-by-date challenge: same board for everyone on a given
  // day. Date determines the template via a stable hash; localStorage
  // tracks streak + per-date completion so the panel can show "you've
  // played today" vs "play today". Permalink: ?daily=YYYY-MM-DD locks
  // the seed so a shared link plays the same board even if the date has
  // rolled over for the visitor.
