    const qbBucket = qb1Round == null ? null
      : qb1Round <= 3 ? 'early'
      : qb1Round <= 6 ? 'mid'
      : qb1Round <= 9 ? 'late'
      : qb1Round <= 12 ? 'late2'
      : 'verylate';
    const teBucket = te1Round == null ? null
      : te1Round <= 4 ? 'early'
      : te1Round <= 8 ? 'mid'
      : te1Round <= 12 ? 'late'
      : 'verylate';
    const wrBucket = wrByR6 <= 2 ? 'slow'
      : wrByR6 <= 4 ? 'med'
      : 'heavy';
