    const buildShape = _udBuildShapeScore(counts);
    const posCount = _udPositionCountScore(counts);
    const roundPattern = _udRoundPatternScore(rosterDetails);
    const pathFit = _udPathFitScore(rosterDetails);
    const pathInfo = _udPathFitInfo(rosterDetails);
    const stacking = _udStackingScore(rosterDetails);
    const stackInfo = _udComputeStacks(rosterDetails);
    const struct = _udComputeStructural(rosterDetails);
    const structural = _udStructuralScore(struct);
    // 10/10/25/15/20/20 weighting (BuildShape/PosCount/RoundPattern/PathFit
    // /Stacking/Structural). v0.10.0: RoundPattern + PathFit + skip penalties
    // now use TOURNAMENT-EQUITY blended rates (50% QF + 30% SF + 20% Finals)
    // via _udBlendedRate, instead of QF-only. This captures the deep-round
    // upside that QF-only scoring missed (e.g. late QB + 3 QB total = +69%
    // Finals lift but only +10% QF lift, so QF-only undervalued the build).
    // Sources: aggregate_bbm_pos_rank_round.py + aggregate_bbm_conditional_construction.py.
    const score = Math.round(
      buildShape * 0.10 +
      posCount * 0.10 +
      roundPattern * 0.25 +
      pathFit * 0.15 +
      stacking * 0.20 +
      structural * 0.20
    );
